"use strict";
// Static safety scan for generated plugins. Two layers:
//   1. bytecode: `javap -c -p` over every compiled class, matched against
//      invoked owners/methods (cannot be dodged by source formatting tricks);
//   2. source: heuristics that need string literals / context (paths, UUIDs,
//      name checks feeding privileges, encoded blobs).
// Verdict is decided here, never by the model.

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

// [id, regex over javap output, plain-English message]
// The scan reads `javap -c -p -v`: the whole constant pool, not only call instructions, so method references,
// lambda handles (`Runtime.getRuntime()::exec` shows up as `REF_invokeVirtual java/lang/Runtime.exec`) and
// string constants that name a class are all seen. Anything that can run other code, reach a network, or
// load code we can't check is a BLOCK for every build (there is no networking wrapper yet, so all of java.net
// that can touch the network is blocked, not only the obvious sockets).
const NET_VALUE_TYPES = "URI|URISyntaxException|URLEncoder|URLDecoder|InetAddress|Inet4Address|Inet6Address|InetSocketAddress|SocketAddress|MalformedURLException|UnknownHostException";
const REFLECT_DATA_TYPES = "Modifier|Array|Type|ParameterizedType|GenericArrayType|TypeVariable|WildcardType";
const BYTECODE_BLOCK = [
  ["exec", /java\/lang\/(Runtime\.exec|ProcessBuilder|ProcessHandle|Process\b)|java\/awt\/Desktop/, "runs other programs on the server machine"],
  ["network", new RegExp(`java/net/(?!(?:${NET_VALUE_TYPES})\\b)[A-Z]|java/net/http/|java/nio/channels/(Async\\w*)?(Socket|ServerSocket|Datagram)Channel|javax/net/|jdk/net/|java/net/spi/`), "connects to the internet or other machines"],
  ["dns", /java\/net\/InetAddress\.(getByName|getAllByName|getLocalHost|getCanonicalHostName|isReachable)|java\/net\/InetSocketAddress\."<init>":\(Ljava\/lang\/String;I\)V/, "looks up internet names (a way to leak data through DNS)"],
  ["jndi-rmi-jmx", /javax\/naming\/|java\/rmi\/|javax\/rmi\/|javax\/management\/|java\/sql\/DriverManager|javax\/sql\//, "reaches other services through naming, RMI, JMX or database lookups"],
  ["resolver", /org\/apache\/(maven|http)\/|org\/eclipse\/aether\/|org\/eclipse\/jgit\//, "downloads code or files through a bundled resolver"],
  ["classload", /java\/lang\/ClassLoader\.(defineClass|loadClass|findClass|getSystemClassLoader|getPlatformClassLoader)|java\/lang\/Thread\.(get|set)ContextClassLoader|java\/net\/URLClassLoader|MethodHandles\$Lookup\.(defineClass|defineHiddenClass)|java\/lang\/invoke\/MethodHandleProxies|java\/lang\/instrument\/|java\/lang\/ModuleLayer|java\/lang\/module\/|java\/lang\/Module\.add\w+/, "loads code 
  ["reflection", new RegExp(`java/lang/reflect/(?!(?:${REFLECT_DATA_TYPES})\\b)[A-Z]|java/lang/Class\\.(forName|getDeclared\\w+|getMethods?|getFields?|getConstructors?|newInstance|getEnclosingMethod|getNestHost)|java/lang/invoke/MethodHandles\\.(lookup|privateLookupIn)|java/lang/invoke/MethodHandle\\.invoke|MethodHandles\\$Lookup\\.(find\\w+|unreflect\\w*|in|lookupClass)\\b|java/lang/invoke/(VarHa
  ["deserialize-beans", /java\/io\/ObjectInput(Stream)?\b|java\/beans\/|java\/util\/ServiceLoader|javax\/xml\/(ws|bind)\/|java\/util\/jar\/(JarFile|JarInputStream)|java\/util\/zip\/ZipInputStream/, "decodes objects, beans or archives that can run code"],
  ["unsafe", /(?<![\w$])(sun|com\/sun|jdk\/(?!net)\w+)\//, "uses unsafe JVM internals"],
  ["exit", /java\/lang\/(System\.exit|Runtime\.(halt|exit))/, "can shut the whole server down"],
  ["system-props", /java\/lang\/System\.(setProperty|setProperties|clearProperty|getProperties|setSecurityManager|setOut|setErr|setIn|console|inheritedChannel|getenv:\(\)|load(Library)?)|java\/lang\/Runtime\.load(Library)?/, "changes JVM-wide settings or reads machine-wide state"],
  ["jni", /java\/lang\/(System|Runtime)\.load(Library)?:/, "loads native code"],
  ["script", /javax\/script\/|javax\/tools\/|org\/(mozilla|codehaus\/groovy)\/|groovy\/|jdk\/jshell\/|jdk\/nashorn\//, "runs scripts or compiles code that we can't check"],
  ["load-plugins", /org\/bukkit\/plugin\/(PluginManager\.(loadPlugin|loadPlugins|enablePlugin|disablePlugin|disablePlugins|clearPlugins|registerInterface)|PluginLoader|SimplePluginManager|java\/JavaPluginLoader)/, "loads, enables or disables other plugins"],
  ["nms", /net\/minecraft\/|org\/bukkit\/craftbukkit\//, "reaches into server internals (breaks on updates)"],
];
// a String constant that merely NAMES a dangerous class is a strong tell even when the call itself is hidden
const STRING_BLOCK = /=\s*String\s+#\d+\s+\/\/\s+(java\.(lang\.(Runtime|ProcessBuilder|ProcessHandle|reflect\.|invoke\.Method|ClassLoader)|net\.(?!URI|URL(En|De)coder)|io\.ObjectInput|beans\.)|javax\.(script|naming|tools|net)|jdk\.internal|sun\.misc|com\.sun\.|org\.bukkit\.craftbukkit|net\.minecraft\.server)/;
const BYTECODE_WARN = [
  ["op", /setOp:\(Z\)V/, "can change who is a server operator"],
  ["console-dispatch", /org\/bukkit\/(Bukkit|Server)\.dispatchCommand/, "runs server commands"],
  ["perm-attach", /addAttachment:/, "grants permissions at runtime"],
  ["base64", /java\/util\/Base64\$Decoder/, "decodes encoded data"],
  ["getenv", /java\/lang\/System\.getenv/, "reads the server machine's environment variables"],
  ["threads", /java\/lang\/Thread\."<init>"|java\/lang\/Runtime\.addShutdownHook|java\/util\/concurrent\/(Executors|ForkJoinPool)\./, "starts its own threads or shutdown hooks (use the Bukkit scheduler)"],
];

function scanBytecode(classDir, opts) {
  const findings = [];
  const classes = [];
  (function walk(d) {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith(".class")) classes.push(p);
    }
  })(classDir);
  if (!classes.length) return findings;
  let out = "";
  for (let i = 0; i < classes.length; i += 40) {
    out += execFileSync("javap", ["-c", "-p", "-v", ...classes.slice(i, i + 40)], { encoding: "utf8", maxBuffer: 256 * 1024 * 1024, timeout: 120000 });
  }
  return scanJavapText(out, opts);
}

/** Pure: classify `javap -c -p -v` output (also what the unit tests feed it). `opts.profile`: "strict" (default) | "attested". */
function scanJavapText(out, opts) {
  // Profiles judge EVERY raw finding before de-duplication: one class with an HTTP call and a raw socket keeps the socket block.
  if (profileOf(opts) === "attested") return attested(rawJavap(out), out);
  return dedupe(rawJavap(out));
}

function rawJavap(out) {
  const findings = [];
  let current = "";
  for (const line of out.split("\n")) {
    const m = line.match(/^(?:public |final |abstract |private |protected |static )*(?:class|interface|enum|record) ([\w.$]+)/);
    if (m) current = m[1];
    if (STRING_BLOCK.test(line)) findings.push({ severity: "block", rule: "class-name-string", where: current, message: "names a dangerous class in text (a way to reach it without calling it directly)", evidence: line.trim().slice(0, 200) });
    for (const [id, re, msg] of BYTECODE_BLOCK) if (re.test(line)) findings.push({ severity: "block", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
    for (const [id, re, msg] of BYTECODE_WARN) if (re.test(line)) findings.push({ severity: "warn", rule: id, where: current, message: msg, evidence: line.trim().slice(0, 200) });
  }
  return findings;
}

// Source rules are the SAME in both profiles (paths outside the plugin folder, secrets, Nxeon paths, encoded blobs and
// privileged hard-coded players stay hard blocks); `opts` is accepted for symmetry only.
function scanSource(srcFiles, opts) {
  void opts;
  const findings = [];
  const uuidRe = /"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}"/;
  const absPathRe = /"(\/(etc|root|home|proc|sys|var|tmp|opt|usr|bin|dev)\b[^"]*|[A-Za-z]:\\\\[^"]*|[^"]*\.\.[\/\\][^"]*|~\/[^"]*)"/;
  const nameCheckRe = /getName\(\)\s*\.\s*equals(IgnoreCase)?\s*\(\s*"[^"]+"\s*\)|"[^"]+"\s*\.\s*equals(IgnoreCase)?\s*\([^)]*getName\(\)/;
  const blobRe = /"[A-Za-z0-9+\/=]{200,}"/;
  // hard-coded credentials never ship (the owner of the server keeps secrets, not the plugin author)
  const secretRes = [
    [/discord(app)?\.com\/api\/webhooks\/\d+\/[\w-]+/i, "a Discord webhook address"],
    [/[MNO][A-Za-z\d]{23}\.[\w-]{6}\.[\w-]{27,}/, "a Discord bot token"],
    [/\bsk-[A-Za-z0-9_-]{20,}/, "an API key"],
    [/\bAKIA[0-9A-Z]{16}\b/, "an AWS key"],
    [/\bgh[pousr]_[A-Za-z0-9]{30,}/, "a GitHub token"],
    [/\bxox[abprs]-[A-Za-z0-9-]{10,}/, "a Slack token"],
  ];
  const nxeonPathRe = /"[^"]*\.nxeon[^"]*"/;
  for (const f of srcFiles) {
    const text = fs.readFileSync(f.abs, "utf8");
    const lines = text.split("\n");
    const privileged = /setOp\s*\(\s*true|addAttachment|dispatchCommand|setPermission/.test(text);
    lines.forEach((l, i) => {
      const at = `${f.rel}:${i + 1}`;
      if (absPathRe.test(l) && /File|Path|Files|FileWriter|FileReader|Stream/.test(l))
        findings.push({ severity: "block", rule: "file-outside", where: at, message: "reads or writes files outside the plugin's own folder", evidence: l.trim().slice(0, 200) });
      for (const [re, what] of secretRes) if (re.test(l)) findings.push({ severity: "block", rule: "hardcoded-secret", where: at, message: `contains ${what} (secrets must never be written into a plugin)`, evidence: l.trim().slice(0, 40) + "…" });
      if (nxeonPathRe.test(l)) findings.push({ severity: "block", rule: "nxeon-path", where: at, message: "touches Nxeon's own control files", evidence: l.trim().slice(0, 200) });
      if (blobRe.test(l)) findings.push({ severity: "block", rule: "encoded-blob", where: at, message: "contains a large encoded blob (possible hidden payload)", evidence: l.trim().slice(0, 80) + "…" });
      if (uuidRe.test(l)) findings.push({ severity: privileged ? "block" : "warn", rule: "hardcoded-uuid", where: at, message: privileged ? "gives special rights to a hard-coded player" : "contains a hard-coded player ID", evidence: l.trim().slice(0, 200) });
      if (nameCheckRe.test(l) && privileged) findings.push({ severity: "block", rule: "hardcoded-name", where: at, message: "gives special rights to a hard-coded player name", evidence: l.trim().slice(0, 200) });
    });
  }
  return dedupe(findings);
}

// Secrets must never leave the box (the model can read files in its sandbox).
function scanSecrets(allFiles, secrets) {
  const hits = [];
  for (const f of allFiles) {
    let text;
    try { text = fs.readFileSync(f.abs, "utf8"); } catch { continue; }
    if (/sk-ant-[A-Za-z0-9_-]{10,}/.test(text)) hits.push(f.rel);
    else for (const s of secrets) if (s && s.length >= 16 && text.includes(s)) { hits.push(f.rel); break; }
  }
  return hits;
}

function dedupe(list) {
  const seen = new Set();
  return list.filter((x) => { const k = `${x.severity}|${x.rule}|${x.where}`; if (seen.has(k)) return false; seen.add(k); return true; });
}

// ------------------------------------------------------------------------------------------------------------------
// Scan PROFILES (Cyrus import, 2026-10-10). "strict" (the default, every generated build) is exactly the rules above.
// "attested" is ONLY for code its owner uploaded and attested (Cyrus import): it runs the same strict rules, then
// downgrades a short, fixed list of findings that legitimate plugins commonly need from BLOCK to WARNING (shown to the
// user). Everything else stays a hard block. The attested profile never says "safe": reports say "checked with the
// attested profile: N warnings". On a CHANGE build of an imported plugin, a downgraded finding that the imported code
// did not already have is a block again (applyBaseline): Cyrus never adds these to imported code.
// ------------------------------------------------------------------------------------------------------------------
const PROFILES = ["strict", "attested"];
function profileOf(opts) {
  const p = opts && opts.profile;
  if (p === undefined || p === null || p === "strict") return "strict";
  if (p === "attested") return "attested";
  throw new Error(`unknown scan profile ${String(p)}`); // fail closed: a typo never weakens the scan
}
// The only java.net / javax.net types an HTTP(S) update checker or metrics call needs (plus the value types).
const HTTP_TYPE = new RegExp(`^(java/net/(URL|URLConnection|HttpURLConnection|${NET_VALUE_TYPES}|http/[A-Za-z$][\\w$]*)|javax/net/ssl/HttpsURLConnection)$`);
const NET_TOKEN = /(?:java|javax|jdk)\/net\/[A-Za-z0-9_$/]+/g;
const httpOnly = (evidence) => { const t = evidence.match(NET_TOKEN) || []; return t.length > 0 && t.every((x) => HTTP_TYPE.test(x.replace(/\/$/, ""))); };
const REFLECT_DYNAMIC = /java\/lang\/invoke\/MethodHandles\.(lookup|privateLookupIn)|MethodHandles\$Lookup\.(find\w+|unreflect\w*|in|lookupClass)\b|java\/lang\/invoke\/MethodHandle\.invoke|java\/lang\/invoke\/(VarHandle|MethodHandleInfo)/;
/** rule -> { when(finding) : downgrade?, rule, message, why }. `why` is the documented reason (docs "Cyrus import"). */
const ATTESTED_DOWNGRADES = {
  network: { when: (f) => httpOnly(f.evidence), rule: "network-http", message: "makes HTTP(S) requests (for example an update checker or usage metrics)", why: "update checkers and bStats-style metrics use URL/HttpURLConnection/HttpClient; raw sockets, server sockets, datagrams and socket channels stay blocked" },
  reflection: { when: (f) => !REFLECT_DYNAMIC.test(f.evidence), rule: "reflection-lookup", message: "uses reflection to find classes, fields or methods (often a version or Folia check)", why: "Class.forName / getDeclared* / Method.invoke are common for version checks and command maps; MethodHandles lookups, private lookups and VarHandles stay blocked, and strings that name dangerous classes stay b
