export type TestLane = {
  compile: boolean;
  scan: boolean;
  /** Boot the real game server with the artifact. */
  boot: "none" | "planned" | "available";
  /** Scripted functional checks (bot, RCON...). */
  functional: "none" | "planned" | "available";
  notes: string;
};

/**
 * One deterministic routing rule. The core router matches `keywords` (lower-case regex sources) against the spec text
 * and prompt; on a match it adds `route` and the honest limit, and checks `requiresCapability` on the target version.
 */
export type RouteRule = {
  id: string;
  keywords: string[];
  /** Asset kinds that trigger this rule without any keyword. */
  assetKinds?: AssetKind[];
  route?: ArtifactRoute;
  requiresCapability?: { capability: string; message: string; /** true = a missing capability is a downgrade (warn), not a block */ downgrade?: boolean;
    /** a weaker capability that still serves the rule (e.g. 1.21.1 legacy custom model data): present = a warn with this message instead of the block */
    fallback?: { capability: string; message: string } };
  /** Build-asset kinds (lib/cyrus/assets/kinds.ts) this rule asks for, when they differ from the spec kinds in assetKinds. */
  buildAssetKinds?: string[];
  /** Shown whenever the rule matches (a fact the user must know: a restart, a client-side limit...). */
  limit?: { severity: "info" | "warn"; message: string };
};

export interface GameAdapter {
  game: string;
  name: string;
  maturity: AdapterMaturity;
  artifacts: readonly ArtifactType[];
  /** The route a request lands on when nothing else is asked for. */
  defaultRoute: ArtifactRoute;
  toolchain: ToolchainProfile;
  /** Where the model's API knowledge for this game lives (two systems exist today, see G-gaps.md (b)). */
  knowledge: { kind: "version-sheets" | "knowledge-pack" | "none"; ref: string };
  versions: {
    list: () => readonly AdapterVersion[];
    get: (id: string) => AdapterVersion | null;
    hasCapability: (id: string, capability: string) => boolean;
  };
  assetDelivery: Readonly<Record<AssetKind, AssetDelivery>>;
  install: InstallRules;
  testLane: TestLane;
  routeRules: readonly RouteRule[];
  /** Design file kinds this game's designers compile (lib/cyrus/designer). Absent = no designers (code only). Read by the capability manifest. */
  designers?: readonly ("item" | "menu" | "quest" | "boss" | "encounter" | "hud" | "motion")[];
  /** 3D/texture asset facts (formats, channels, delivery, worker class, legal). Optional: a game without one is text/code only. */
  assetProfile?: AssetProfile;
}

// Cyrus CAPABILITY CATALOGUE (live-test fix F): ONE per-game, per-version answer to "can this game/version produce
// lane X, and if not, why and what instead". Every GameAdapter provides one (GameAdapter.capabilities); the planner's
// plan screen, the pre-build warning, the version selector's "what this version supports" panel and the project page
// all read it through resolveCapabilities(). No game-specific code outside the adapter's catalogue.
//
// SCHEMA (cyrus.capabilities.v1), also the shape of a JSON catalogue file (e.g. lib/cyrus/adapters/minecraft-coverage.json):
//   { schema: "cyrus.capabilities.v1", game, lanes: { <lane>: LaneRule }, archetypes?: Archetype[] }
//   LaneRule = { base, reason, substitute?, minVersion?, requires?: { capability, reason, fallback?: { capability, reason } }, flag? }
//     base        availability when every requirement holds: available | limited | unavailable
//     reason      plain words: why it is limited / unavailable (or what "available" means), {version} and {game} expand
//     substitute  what Cyrus builds instead when the lane cannot be produced
//     minVersion  the oldest version id that supports it (for "Pick <minVersion> or newer")
//     requires    a version capability (AdapterVersion.capabilities) the lane needs; missing -> unavailable with its reason,
//                 unless `fallback.capability` is present -> limited with the fallback reason
//     flag        a host switch name (e.g. CYRUS_DESIGNER) the lane also needs; off -> unavailable ("not switched on yet")
//   Archetype = { id, label, lanes: Lane[], limits: string[] }   (optional, e.g. "boss mob", "custom weapon")
// Pure + client-safe. A game adapter without a COMPLETE catalogue (every lane) cannot reach maturity "beta"
// (lib/cyrus/onboarding/health.ts checks it).
import { z } from "zod";
import { LANES, type Lane } from "../planner/lanes";

export const CAPABILITY_SCHEMA = "cyrus.capabilities.v1";
export const LANE_AVAILABILITY = ["available", "limited", "unavailable"] as const;
export type LaneAvailability = (typeof LANE_AVAILABILITY)[number];

const Requires = z.object({
  capability: z.string().min(1).max(60),
  reason: z.string().min(1).max(400),
  fallback: z.object({ capability: z.string().min(1).max(60), reason: z.string().min(1).max(400) }).optional(),
});
export const LaneRuleSchema = z.object({
  base: z.enum(LANE_AVAILABILITY),
  reason: z.string().min(1).max(400),
  substitute: z.string().max(300).optional(),
  minVersion: z.string().max(20).optional(),
  requires: Requires.optional(),
  flag: z.string().regex(/^[A-Z][A-Z0-9_]{2,60}$/).optional(),
});
export type LaneRule = z.infer<typeof LaneRuleSchema>;
export const ArchetypeSchema = z.object({ id: z.string().regex(/^[a-z][a-z0-9_-]{1,40}$/), label: z.string().min(1).max(80), lanes: z.array(z.enum(LANES)), limits: z.array(z.string().max(400)) });
export const CatalogueSchema = z.object({
  schema: z.literal(CAPABILITY_SCHEMA),
  game: z.string().min(1).max(40),
  lanes: z.record(z.string(), LaneRuleSchema),
  archetypes: z.array(ArchetypeSchema).optional(),
});
export type CapabilityCatalogue = z.infer<typeof CatalogueSchema>;

/** Every lane present? (maturity "beta" needs this; the health test reports what is missing.) */
export function missingLanes(c: CapabilityCatalogue | null | undefined): Lane[] {
  if (!c) return [...LANES];
  return LANES.filter((l) => !c.lanes[l]);
}

export type LaneCapability = {
  lane: Lane;
  availability: LaneAvailability;
  /** Plain words for this version (expanded). */
  reason: string;
  substitute: string | null;
  minVersion: string | null;
  /** Which part said no: the version, a host switch, or the game itself. */
  cause: "ok" | "version" | "flag" | "game";
};

/** The host side of resolution: which version capabilities exist, which switches are on. */
export type CapabilityContext = {
  game: string;
  gameName: string;
  version: string;
  hasCapability: (capability: string) => boolean;
  /** Host switches (flag name -> on). Unknown flags count as off (fail closed). */
  flags?: Readonly<Record<string, boolean>>;
};

const fill = (s: string, ctx: CapabilityContext) => s.replaceAll("{version}", ctx.version).replaceAll("{game}", ctx.gameName);

export function resolveLane(c: CapabilityCatalogue | null | undefined, lane: Lane, ctx: CapabilityContext): LaneCapability {
  const rule = c?.lanes[lane];
  if (!rule) return { lane, availability: "unavailable", reason: `${ctx.gameName} has no capability entry for this yet, so Cyrus does not offer it.`, substitute: null, minVersion: null, cause: "game" };
  const base = { lane, substitute: rule.substitute ? fill(rule.substitute, ctx) : null, minVersion: rule.minVersion ?? null };
  if (rule.base === "unavailable") return { ...base, availability: "unavailable", reason: fill(rule.reason, ctx), cause: "game" };
  if (rule.requires && !ctx.hasCapability(rule.requires.capability)) {
    const fb = rule.requires.fallback;
    if (fb && ctx.hasCapability(fb.capability)) return { ...base, availability: "limited", reason: fill(fb.reason, ctx), cause: "version" };
    return { ...base, availability: "unavailable", reason: fill(rule.requires.reason, ctx), cause: "version" };
  }
  if (rule.flag && !ctx.flags?.[rule.flag]) return { ...base, availability: "unavailable", reason: `${fill(rule.reason, ctx).replace(/\.$/, "")}, but it is not switched on in Cyrus yet.`, cause: "flag" };
  return { ...base, availability: rule.base, reason: fill(rule.reason, ctx), cause: "ok" };
}

/** The whole "what this version supports" panel, in lane order. */
export function resolveCapabilities(c: CapabilityCatalogue | null | undefined, ctx: CapabilityContext): LaneCapability[] {
  return LANES.map((l) => resolveLane(c, l, ctx));
}

/** The pre-build warning for one lane the prompt needs but this game/version cannot produce. */
export function laneWarning(cap: LaneCapability, label: string, ctx: Pick<CapabilityContext, "gameName" | "version">): string {
  const sub = cap.substitute ? ` Cyrus will build ${cap.substitute.replace(/\.$/, "")} instead.` : "";
  const pick = cap.cause === "version" && cap.minVersion ? ` Pick ${cap.minVersion} or newer to get them.` : "";
  return `${label} ${cap.availability === "limited" ? "are limited" : "are not available"} on ${ctx.gameName} ${ctx.version}: ${cap.reason.replace(/\.$/, "")}.${sub}${pick}`;
}
