import type { DataPackFeatures } from "../versions";
import type { DpEnchantment } from "../spec";
import { textComponent, type Json } from "./common";

const cost = (c: { base: number; perLevelAboveFirst: number }): Json => ({ base: c.base, per_level_above_first: c.perLevelAboveFirst });
const levelValue = (base: number, per?: number): Json => (per === undefined ? base : { type: "minecraft:linear", base, per_level_above_first: per });

/** The enchantment format of this subset is identical on 1.21.1 .. 26.2 (vanilla sharpness/unbreaking compared on every jar). */
export function emitEnchantment(e: DpEnchantment, _fe: DataPackFeatures): Json {
  const out: { [k: string]: Json } = { description: textComponent(e.description) };
  if (e.exclusiveSet) out.exclusive_set = e.exclusiveSet;
  out.supported_items = e.supportedItems;
  if (e.primaryItems) out.primary_items = e.primaryItems;
  Object.assign(out, { weight: e.weight, max_level: e.maxLevel, min_cost: cost(e.minCost), max_cost: cost(e.maxCost), anvil_cost: e.anvilCost, slots: e.slots });
  if (e.effects?.length) {
    const fx: { [k: string]: Json[] } = {};
    for (const x of e.effects) {
      const v = levelValue(x.base, x.perLevelAboveFirst);
      const effect = x.op === "multiply" ? { type: "minecraft:multiply", factor: v } : { type: `minecraft:${x.op}`, value: v };
      (fx[`minecraft:${x.component}`] ??= []).push({ effect });
    }
    out.effects = fx;
  }
  return out;
}
// Spec -> data pack, per version. validate (fail closed) -> emit every resource through the per-version adapters ->
// pack.mcmeta from the registry's format -> static file check (mcdoc fields + value shapes + ids + function allowlist)
// -> deterministic zip (sorted entries, fixed timestamps; lib/cyrus/textures/zip.ts). Same spec + version = same bytes.
import { createHash } from "node:crypto";
import { zip } from "../../textures/zip";
import { canonicalJson, needsRestart, validateDataPackSpec, type DataPackSpec, type DpCheck, type DpIssue } from "../spec";
import { validatePackFiles, type FileReport } from "../validate";
import type { DataPackFeatures } from "../versions";
import { emitAdvancement } from "./advancement";
import { jsonText, type Json } from "./common";
import { emitEnchantment } from "./enchantment";
import { emitLootTable } from "./loot";
import { emitRecipe } from "./recipe";
import { emitWorldgenFiles } from "../worldgen/emit";
import { hasWorldgen, type WorldgenSummary } from "../worldgen/check";
import { worldgenFeatures } from "../worldgen/versions";

/** dp-emit-1: unchanged for packs without world generation (same bytes); worldgen files are emitted by ../worldgen/emit.ts (wg-emit-1). */
export const EMITTER_VERSION = "dp-emit-1";
export const WORLDGEN_EMITTER_VERSION = "wg-emit-1";

/** `data` = binary content (structure templates, gzipped NBT); `text` is "" then. */
export type EmittedFile = { path: string; text: string; data?: Buffer };
export type BuiltDataPack = {
  name: string; version: string; namespace: string; spec: DataPackSpec; files: EmittedFile[]; zip: Buffer; sha1: string; sha256: string; bytes: number;
  format: { major: number; minor: number }; specSha256: string; counts: Record<string, number>;
  /** Enchantments and world generation are registry content: a server restart is needed; everything else loads with /reload. */
  apply: "reload" | "restart";
  /** World generation summary (dimensions, biomes, structures, templates, cost estimate) when the pack has any. */
  worldgen?: WorldgenSummary & { emitter: string };
  checks: DpCheck[]; warnings: string[]; emitter: string;
};
export type BuildResult = { ok: true; pack: BuiltDataPack } | { ok: false; errors: string[]; issues: DpIssue[]; checks: DpCheck[]; fileReport?: FileReport };
export type BuildContext = { version: string; namespace: string; worldgen?: boolean };

export function mcmetaJson(description: string, fe: DataPackFeatures): Json {
  const { major, minor } = fe.format;
  return fe.mcmeta === "pack_format" ? { pack: { pack_format: major, description } } : { pack: { description, min_format: [major, minor], max_format: [major, minor] } };
}

/** The data pack files (no zip, no file check) of an ALREADY VALIDATED spec. */
export function emitFiles(spec: DataPackSpec, namespace: string, fe: DataPackFeatures): EmittedFile[] {
  const out: EmittedFile[] = [{ path: "pack.mcmeta", text: jsonText(mcmetaJson(spec.description, fe)) }];
  const tags = new Map<string, { replace: boolean; values: string[] }>();
  const tag = (path: string, values: string[], replace = false) => {
    const t = tags.get(path) ?? { replace: false, values: [] };
    t.replace = t.replace || replace;
    for (const v of values) if (!t.values.includes(v)) t.values.push(v);
    tags.set(path, t);
  };
  for (const r of spec.resources) {
    const base = `data/${namespace}`;
    switch (r.type) {
      case "recipe": out.push({ path: `${base}/recipe/${r.id}.json`, text: jsonText(emitRecipe(r.recipe, fe)) }); break;
      case "loot_table": out.push({ path: `${base}/loot_table/${r.id}.json`, text: jsonText(emitLootTable(r.table, fe, `${namespace}:${r.id}`)) }); break;
      case "advancement": out.push({ path: `${base}/advancement/${r.id}.json`, text: jsonText(emitAdvancement(r.advancement, fe)) }); break;
      case "enchantment": out.push({ path: `${base}/enchantment/${r.id}.json`, text: jsonText(emitEnchantment(r.enchantment, fe)) }); break;
      case "function":
        out.push({ path: `${base}/function/${r.id}.mcfunction`, text: [`# ${namespace}:${r.id} (generated by Cyrus from the "${spec.name}" data pack spec)`, ...r.commands.map((c) => c.trim())].join("\n") + "\n" });
        if (r.runOn) tag(`data/minecraft/tags/function/${r.runOn}.json`, [`${namespace}:${r.id}`]);
        break;
      case "tag": {
        const [tns, tpath] = r.id.startsWith("minecraft:") ? ["minecraft", r.id.slice(10)] : [namespace, r.id];
        tag(`data/${tns}/tags/${r.registry}/${tpath}.json`, r.values, r.replace === true && tns !== "minecraft");
        break;
      }
    }
  }
  for (const [path, t] of [...tags].sort((a, b) => (a[0] < b[0] ? -1 : 1))) out.push({ path, text: jsonText({ replace: t.replace, values: t.values }) });
  if (hasWorldgen(spec)) {
    const wf = worldgenFeatures(fe.version);
    if (!wf.ok) throw new Error(wf.error); // validated specs never get here without worldgen data
    out.push(...emitWorldgenFiles(spec, namespace, wf.features));
  }
  return out.sort((a, b) => (a.path < b.path ? -1 : 1));
}

const hash = (alg: "sha1" | "sha256", b: Buffer | string) => createHash(alg).update(b).digest("hex");

export function buildDataPack(input: unknown, ctx: BuildContext): BuildResult {
  const v = validateDataPackSpec(input, ctx);
  if (!v.ok) return { ok: false, errors: v.errors.map((e) => `${e.path}: ${e.message}`), issues: v.errors, checks: v.checks };
  const files = emitFiles(v.spec, ctx.namespace, v.features);
  const fileReport = validatePackFiles(files, ctx.version, v.worldgen ? { worldgen: true } : {});
  const checks = [...v.checks, ...fileReport.checks.map((c) => ({ ...c, id: c.id === "vanilla_ids" ? "emitted_ids" : c.id === "function_safety" ? "emitted_functions" : c.id }))];
  if (!fileReport.ok) return { ok: false, errors: fileReport.errors.map((e) => `emitted: ${e}`), issues: [], checks, fileReport };
  const z = zip(files.map((f) => ({ path: f.path, data: f.data ?? Buffer.from(f.text, "utf8") })));
  const counts: Record<string, number> = {};
  for (const r of v.spec.resources) counts[r.type] = (counts[r.type] ?? 0) + 1;
  if (z.length > 1024 * 1024) return { ok: false, errors: [`the data pack is ${z.length} bytes; the limit is 1 MB`], issues: [], checks, fileReport };
  return {
    ok: true,
    pack: {
      name: v.spec.name, version: ctx.version, namespace: ctx.namespace, spec: v.spec, files, zip: z, sha1: hash("sha1", z), sha256: hash("sha256", z), bytes: z.length,
      format: v.features.format, specSha256: hash("sha256", canonicalJson(v.spec)), counts, apply: needsRestart(v.spec) ? "restart" : "reload",
      checks, warnings: [...v.warnings.map((w) => `${w.path}: ${w.message}`), ...fileReport.warnings], emitter: EMITTER_VERSION,
      ...(v.worldgen ? { worldgen: { ...v.worldgen, emitter: WORLDGEN_EMITTER_VERSION } } : {}),
    },
  };
}

