#!/usr/bin/env tsx
// Minecraft coverage matrix renderer (bundle mc-coverage): lib/cyrus/adapters/minecraft-coverage.json (the source of
// truth, machine-readable for the planner) + services/modbuilder/golden/results.json (golden corpus pass matrix) ->
// docs/cyrus/minecraft-coverage.md. Deterministic, no network, no model.
//
//   npx tsx scripts/cyrus/mc-coverage.ts           write docs/cyrus/minecraft-coverage.md
//   npx tsx scripts/cyrus/mc-coverage.ts --check   exit 1 when the committed page is stale (test/cyrus-mc-coverage.test.ts)
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

export type VersionLane = { availability: "available" | "limited" | "unavailable"; reason: string; substitute: string | null; minVersion: string | null };
export type VersionNote = VersionLane & { lane: string };
export type Archetype = {
  id: string; label: string; category: string; plugin: boolean; lanes: string[];
  vanillaClient: "full" | "pack" | "partial" | "impossible";
  coverage: { status: "covered" | "partial" | "gap" | "impossible"; note: string };
  limits: string[]; versionNotes: Record<string, VersionNote[]>; failureModes: string[]; golden: string | null; example: string;
};
export type Coverage = {
  schema: string; coverageSchema: number; game: string; about: string; laneVocabulary: string[]; versions: string[];
  lanes: Record<string, unknown>;
  versionLanes: Record<string, Record<string, VersionLane>>;
  apiFacts: Record<string, string>[];
  archetypes: Archetype[];
};
export type GoldenResults = {
  schema: 1; versions: string[]; flights: { version: string; runId: string; overall: string; bootMs: number | null; plugins: number }[];
  rows: { id: string; archetype: string; compile: Record<string, string>; scan: Record<string, string>; boot: Record<string, string>; notes?: string[] }[];
};

const ROOT = path.resolve(__dirname, "../..");
export const COVERAGE_FILE = "lib/cyrus/adapters/minecraft-coverage.json";
export const RESULTS_FILE = "services/modbuilder/golden/results.json";
export const DOC_FILE = "docs/cyrus/minecraft-coverage.md";

export function loadCoverage(root = ROOT): Coverage { return JSON.parse(readFileSync(path.join(root, COVERAGE_FILE), "utf8")); }
export function loadResults(root = ROOT): GoldenResults | null {
  const f = path.join(root, RESULTS_FILE);
  return existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null;
}

const esc = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");
const AV: Record<string, string> = { available: "yes", limited: "limited", unavailable: "no" };

export function render(c: Coverage, r: GoldenResults | null): string {
  const L: string[] = [];
  const p = (s = "") => L.push(s);
  p("# Minecraft coverage matrix");
  p();
  p(`> GENERATED by \`scripts/cyrus/mc-coverage.ts\` from \`${COVERAGE_FILE}\`${r ? ` and \`${RESULTS_FILE}\`` : ""}. Edit the JSON, then re-run the script.`);
  p();
  p("Which Cyrus lane serves each kind of Minecraft mod people ask for, how well it is covered today, what each version can do, and the limits Cyrus must tell the user **before** any credits are spent. The JSON is the machine-readable form the planner reads (capability catalogue v1: per-version `{lane, availability, reason, substitute, minVersion}`).");
  p();
  p("Lanes: `plugin` is the Paper plugin every build has; the others are the planner lanes (`lib/cyrus/planner/lanes.ts`). Vanilla client: `full` = nothing to install, `pack` = players accept the server resource pack, `partial` = works with visible compromises, `impossible` = needs a client mod.");
  p();
  p("## Lanes per version");
  p();
  p(`| Lane | ${c.versions.join(" | ")} |`);
  p(`|---|${c.versions.map(() => "---").join("|")}|`);
  for (const lane of c.laneVocabulary) {
    const row = c.versionLanes[lane] ?? {};
    p(`| \`${lane}\` | ${c.versions.map((v) => (row[v] ? AV[row[v].availability] : "?")).join(" | ")} |`);
  }
  p();
  p("Why (per lane, per version; substitute in brackets):");
  p();
  for (const lane of c.laneVocabulary) {
    const row = c.versionLanes[lane] ?? {};
    const groups = new Map<string, string[]>();
    for (const v of c.versions) {
      const x = row[v];
      if (!x) continue;
      const k = `${AV[x.availability]}: ${x.reason}${x.substitute && x.availability !== "available" ? ` [instead: ${x.substitute}]` : ""}`;
      groups.set(k, [...(groups.get(k) ?? []), v]);
    }
    p(`- **${lane}**: ${[...groups].map(([k, vs]) => `${vs.join(", ")} ${k}`).join("; ")}.`);
  }
  p();
  p("## Paper API facts that change the code per version");
  p();
  p("Checked with `javap` against each version's `paper-api` jar on the build host (2026-10-11).");
  p();
  for (const f of c.apiFacts) p(`- **${f.feature}**: ${Object.entries(f).filter(([k]) => k !== "feature").map(([k, v]) => `${k}: ${v}`).join("; ")}.`);
  p();
  p("## Archetypes");
  p();
  const counts: Record<string, number> = {};
  for (const a of c.archetypes) counts[a.coverage.status] = (counts[a.coverage.status] ?? 0) + 1;
  p(`${c.archetypes.length} archetypes: ${Object.entries(counts).sort().map(([k, n]) => `${n} ${k}`).join(", ")}.`);
  p();
  p("| Archetype | Category | Lanes | Vanilla client | Coverage | Golden |");
  p("|---|---|---|---|---|---|");
  for (const a of c.archetypes) p(`| ${esc(a.label)} (\`${a.id}\`) | ${a.category} | ${[a.plugin ? "plugin" : null, ...a.lanes].filter(Boolean).join(", ") || "none"} | ${a.vanillaClient} | ${a.coverage.status} | ${a.golden ? `\`${a.golden}\`` : "-"} |`);
  p();
  if (r) {
    p("## Golden corpus pass matrix");
    p();
    p(`Hand-written reference plugins in \`services/modbuilder/golden/\`, compiled with \`javac --release 21 -Xlint:deprecation,removal\` against each version's real Paper API classpath, run through the build service's precheck rules, warning rules and strict scan, then booted together in one Test Flight per version (RCON checks per plugin). Cell = compile/scan/boot; \`-\` = not run.`);
    p();
    p(`| Plugin | Archetype | ${r.versions.join(" | ")} |`);
    p(`|---|---|${r.versions.map(() => "---").join("|")}|`);
    for (const row of r.rows) p(`| \`${row.id}\` | ${row.archetype} | ${r.versions.map((v) => `${row.compile[v] ?? "-"}/${row.scan[v] ?? "-"}/${row.boot[v] ?? "-"}`).join(" | ")} |`);
    p();
    p(`Flights: ${r.flights.map((f) => `${f.version} ${f.overall} (${f.plugins} plugins${f.bootMs ? `, boot ${Math.round(f.bootMs / 100) / 10} s` : ""}, ${f.runId})`).join("; ")}.`);
    const notes = r.rows.flatMap((x) => (x.notes ?? []).map((n) => `\`${x.id}\`: ${n}`));
    if (notes.length) { p(); p("Findings fixed in the knowledge (sheets, failure rules, autofix):"); p(); for (const n of notes) p(`- ${esc(n)}`); }
    p();
  }
  p("## Details per archetype");
  p();
  for (const a of c.archetypes) {
    p(`### ${a.label}`);
    p();
    p(`\`${a.id}\`, ${a.category}. Coverage **${a.coverage.status}**: ${a.coverage.note}.${a.example ? ` Example: "${a.example}".` : ""}`);
    for (const l of a.limits) p(`- Limit: ${l}`);
    for (const [v, ns] of Object.entries(a.versionNotes)) for (const n of ns) p(`- ${v} (${n.lane}, ${n.availability}): ${n.reason}${n.substitute ? `; instead: ${n.substitute}` : ""}${n.minVersion ? `; needs ${n.minVersion}+` : ""}.`);
    for (const f of a.failureModes) p(`- Known failure: ${f}`);
    p();
  }
  p("## Impossible without a client mod (say so, then build the closest thing)");
  p();
  for (const a of c.archetypes.filter((x) => x.coverage.status === "impossible" || x.vanillaClient === "impossible")) p(`- **${a.label}**: ${a.limits[0] ?? a.coverage.note}`);
  p("- **New item types**: custom items are vanilla items with a custom look, name, lore and behaviour.");
  p("- **New status effect types, new mob types with their own client model on 1.21.x, real vehicles**: built on vanilla effects, mobs (or 26.x creatures) and rideable mobs instead.");
  p();
  return L.join("\n");
}

if (require.main === module) {
  const out = render(loadCoverage(), loadResults());
  const target = path.join(ROOT, DOC_FILE);
  if (process.argv.includes("--check")) {
    const cur = existsSync(target) ? readFileSync(target, "utf8") : "";
    if (cur !== out) { console.error(`${DOC_FILE} is stale: run npx tsx scripts/cyrus/mc-coverage.ts`); process.exit(1); }
    console.log(`${DOC_FILE} is up to date`);
  } else {
    writeFileSync(target, out);
    console.log(`wrote ${DOC_FILE}`);
  }
}

