// Cyrus Minecraft coverage matrix (bundle mc-coverage): lib/cyrus/adapters/minecraft-coverage.json is well-formed, uses the
// planner lane vocabulary and the capability-catalogue v1 shape, agrees with the version registry and the golden corpus,
// and docs/cyrus/minecraft-coverage.md is fresh. Pure data checks. Run: tsx --test test/cyrus-mc-coverage.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { loadCoverage, loadResults, render, DOC_FILE } from "../scripts/cyrus/mc-coverage";

const ROOT = path.join(__dirname, "..");
const cov = loadCoverage(ROOT);
const results = loadResults(ROOT);
const registry = JSON.parse(fs.readFileSync(path.join(ROOT, "lib/cyrus/versions/registry.json"), "utf8"));
const AVAIL = ["available", "limited", "unavailable"];
const GOLDEN = path.join(ROOT, "services/modbuilder/golden");

describe("minecraft coverage matrix", () => {
  it("is a capability catalogue v1 for minecraft with every lane", () => {
    assert.equal(cov.schema, "cyrus.capabilities.v1");
    assert.equal(cov.game, "minecraft");
    const planner = cov.laneVocabulary.filter((l) => l !== "plugin");
    for (const l of planner) assert.ok(cov.lanes[l], `catalogue lane ${l}`);
    for (const [l, rule] of Object.entries(cov.lanes) as [string, { base: string; reason: string }][]) {
      assert.ok(planner.includes(l), `unknown lane ${l}`);
      assert.ok(AVAIL.includes(rule.base) && rule.reason.length > 10, l);
    }
  });

  it("has a per-version entry for every lane and version, with reasons and substitutes", () => {
    for (const lane of cov.laneVocabulary) for (const v of cov.versions) {
      const x = cov.versionLanes[lane]?.[v];
      assert.ok(x, `${lane} ${v}`);
      assert.ok(AVAIL.includes(x.availability), `${lane} ${v} availability`);
      assert.ok(x.reason.length > 10, `${lane} ${v} reason`);
      if (x.availability === "unavailable") assert.ok(x.substitute, `${lane} ${v}: unavailable needs a substitute`);
    }
  });

  it("matches the registry: buildable versions build plugins, 26.x does not, item-model lanes follow itemModelDefinitions", () => {
    const reg = new Map<string, { buildable: boolean; capabilities: string[] }>(registry.versions.map((r: { id: string }) => [r.id, r]));
    for (const v of cov.versions.filter((x) => x !== "26.x")) {
      const r = reg.get(v);
      assert.ok(r, `registry has ${v}`);
      assert.equal(cov.versionLanes.plugin[v].availability === "available", r!.buildable, `plugin lane ${v}`);
      const im = r!.capabilities.includes("itemModelDefinitions");
      for (const lane of ["itemStates", "model3d", "motion"]) assert.equal(cov.versionLanes[lane][v].availability !== "unavailable", im, `${lane} ${v}`);
    }
    assert.ok(!registry.versions.some((r: { id: string; buildable: boolean }) => r.id.startsWith("26.") && r.buildable) || cov.versionLanes.plugin["26.x"].availability !== "unavailable", "26.x became buildable: update the matrix");
  });

  it("archetypes: ~60+, unique ids, known lanes, limits for every non-covered one", () => {
    assert.ok(cov.archetypes.length >= 60, `${cov.archetypes.length} archetypes`);
    const ids = new Set<string>();
    for (const a of cov.archetypes) {
      assert.match(a.id, /^[a-z][a-z0-9_-]{1,40}$/);
      assert.ok(!ids.has(a.id), `duplicate ${a.id}`);
      ids.add(a.id);
      for (const l of a.lanes) assert.ok(cov.laneVocabulary.includes(l) && l !== "plugin", `${a.id}: lane ${l}`);
      assert.ok(["covered", "partial", "gap", "impossible"].includes(a.coverage.status), a.id);
      assert.ok(["full", "pack", "partial", "impossible"].includes(a.vanillaClient), a.id);
      if (a.coverage.status !== "covered") assert.ok(a.limits.length > 0, `${a.id}: ${a.coverage.status} needs a limit for the planner`);
      for (const [v, ns] of Object.entries(a.versionNotes)) {
        assert.ok(cov.versions.includes(v), `${a.id}: version ${v}`);
        for (const n of ns) assert.ok(cov.laneVocabulary.includes(n.lane) && AVAIL.includes(n.availability), `${a.id} ${v}`);
      }
    }
  });

  it("every golden id named by an archetype exists in the corpus", () => {
    for (const a of cov.archetypes.filter((x) => x.golden)) assert.ok(fs.existsSync(path.join(GOLDEN, "plugins", a.golden!, "plugin.yml")), `${a.id}: golden ${a.golden}`);
  });

  it("the golden results cover every corpus plugin on every buildable version", { skip: !results }, () => {
    const dirs = fs.readdirSync(path.join(GOLDEN, "plugins")).filter((d) => fs.existsSync(path.join(GOLDEN, "plugins", d, "plugin.yml"))).sort();
    assert.deepEqual(results!.rows.map((r) => r.id).sort(), dirs);
    for (const r of results!.rows) for (const v of results!.versions) assert.ok(r.compile[v], `${r.id} ${v} compile result`);
  });

  it(`${DOC_FILE} is fresh`, () => {
    assert.equal(fs.readFileSync(path.join(ROOT, DOC_FILE), "utf8"), render(cov, results), "run: npx tsx scripts/cyrus/mc-coverage.ts");
  });
});

