import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.command.TabCompleter;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden homes: /sethome [name], /home [name], /delhome name, /homes; limit per permission; saved in homes.yml. */
public class Homes extends JavaPlugin implements TabCompleter {
    private File file;
    private YamlConfiguration data;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "homes.yml");
        data = YamlConfiguration.loadConfiguration(file);
        for (String c : List.of("sethome", "home", "delhome", "homes")) {
            getCommand(c).setExecutor(this);
            getCommand(c).setTabCompleter(this);
        }
    }

    @Override
    public void onDisable() {
        save();
    }

    private void save() {
        try {
            data.save(file);
        } catch (IOException e) {
            getLogger().warning("Could not save homes.yml: " + e.getMessage());
        }
    }

    private int limitFor(Player p) {
        int limit = getConfig().getInt("default-limit", 3);
        ConfigurationSection extra = getConfig().getConfigurationSection("limits");
        if (extra != null) for (String key : extra.getKeys(false)) if (p.hasPermission("goldenhomes.limit." + key)) limit = Math.max(limit, extra.getInt(key));
        return limit;
    }

    private ConfigurationSection homesOf(Player p, boolean create) {
        String path = p.getUniqueId().toString();
        ConfigurationSection s = data.getConfigurationSection(path);
        return s == null && create ? data.createSection(path) : s;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmd = command.getName().toLowerCase();
        if (cmd.equals("homes") && args.length == 1 && args[0].equalsIgnoreCase("reload")) {
            if (!sender.hasPermission("goldenhomes.admin")) { sender.sendMessage(Component.text("No permission.", NamedTextColor.RED)); return true; }
            reloadConfig();
            sender.sendMessage(Component.text("GoldenHomes reloaded (default limit " + getConfig().getInt("default-limit", 3) + ").", NamedTextColor.GREEN));
            return true;
        }
        if (!(sender instanceof Player player)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        String name = args.length > 0 ? args[0].toLowerCase() : "home";
        if (!name.matches("[a-z0-9_]{1,16}")) { player.sendMessage(Component.text("Home names: 1-16 letters, digits or _.", NamedTextColor.RED)); return true; }
        ConfigurationSection homes = homesOf(player, cmd.equals("sethome"));
        switch (cmd) {
            case "sethome" -> {
                if (!homes.contains(name) && homes.getKeys(false).size() >= limitFor(player)) { player.sendMessage(Component.text("You reached your home limit (" + limitFor(player) + ").", NamedTextColor.RED)); return true; }
                homes.set(name, player.getLocation());
                save();
                player.sendMessage(Component.text("Home '" + name + "' set.", NamedTextColor.GREEN));
            }
            case "home" -> {
                Location loc = homes == null ? null : homes.getLocation(name);
                if (loc == null || loc.getWorld() == null) { player.sendMessage(Component.text("No home called '" + name + "'.", NamedTextColor.RED)); return true; }
                player.teleportAsync(loc).thenAccept(ok -> { if (ok) player.sendMessage(Component.text("Welcome home.", NamedTextColor.GREEN)); });
            }
            case "delhome" -> {
                if (homes == null || !homes.contains(name)) { player.sendMessage(Component.text("No home called '" + name + "'.", NamedTextColor.RED)); return true; }
                homes.set(name, null);
                save();
                player.sendMessage(Component.text("Home '" + name + "' deleted.", NamedTextColor.YELLOW));
            }
            default -> player.sendMessage(Component.text("Homes: " + (homes == null ? "none" : String.join(", ", homes.getKeys(false))), NamedTextColor.AQUA));
        }
        return true;
    }

    @Override
    public List<String> onTabComplete(CommandSender sender, Command command, String alias, String[] args) {
        if (!(sender instanceof Player p) || args.length != 1) return List.of();
        ConfigurationSection homes = homesOf(p, false);
        return homes == null ? List.of() : new ArrayList<>(homes.getKeys(false));
    }
}
