/**
 * Golden maintenance mode / login gate: AsyncPlayerPreLoginEvent runs OFF the main thread before the player exists,
 * so it only reads a concurrent set of allowed names copied from config on the main thread.
 */
public class LoginGate extends JavaPlugin implements Listener {
    private volatile boolean maintenance;
