        saveDefaultConfig();
        load();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("maintenance").setExecutor(this);
    }

    private void load() {
        maintenance = getConfig().getBoolean("maintenance", false);
        allowed.clear();
        getConfig().getStringList("allowed").forEach(n -> allowed.add(n.toLowerCase()));
