package dev.nxeon.golden.chatfilter;

import io.papermc.paper.event.player.AsyncChatEvent;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextReplacementConfig;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden chat filter: blocked words masked (Pattern.quote), spam cooldown, caps limit. Thread-safe state. */
public class ChatFilter extends JavaPlugin implements Listener {
    private volatile List<Pattern> words = List.of();
    private final Map<UUID, Long> last = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("chatfilter").setExecutor(this);
    }

    private void load() {
        words = getConfig().getStringList("blocked-words").stream().map(w -> Pattern.compile("(?i)\\b" + Pattern.quote(w) + "\\b")).toList();
    }

    String clean(String text) {
        String out = text;
        for (Pattern p : words) out = p.matcher(out).replaceAll("***");
        return out;
    }

    @EventHandler(priority = EventPriority.LOWEST, ignoreCancelled = true)
    public void onChat(AsyncChatEvent event) {
        long now = System.currentTimeMillis();
        long cooldown = getConfig().getLong("cooldown-ms", 1500);
        Long prev = last.put(event.getPlayer().getUniqueId(), now);
        if (prev != null && now - prev < cooldown && !event.getPlayer().hasPermission("goldenfilter.bypass")) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(Component.text("Slow down a little.", NamedTextColor.RED));
            return;
        }
        String plain = PlainTextComponentSerializer.plainText().serialize(event.message());
        long upper = plain.chars().filter(Character::isUpperCase).count();
        if (plain.length() >= 8 && upper * 100 / plain.length() > getConfig().getInt("max-caps-percent", 70)) event.message(Component.text(plain.toLowerCase()));
        for (Pattern p : words) event.message(event.message().replaceText(TextReplacementConfig.builder().match(p).replacement("***").build()));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent event) {
        last.remove(event.getPlayer().getUniqueId());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length >= 1 && args[0].equalsIgnoreCase("reload")) { reloadConfig(); load(); sender.sendMessage(Component.text("GoldenChatFilter reloaded: " + words.size() + " words.", NamedTextColor.GREEN)); return true; }
        if (args.length >= 2 && args[0].equalsIgnoreCase("test")) { sender.sendMessage(Component.text("Filtered: " + clean(String.join(" ", List.of(args).subList(1, args.length))))); return true; }
        sender.sendMessage(Component.text("/chatfilter reload | test <text>", NamedTextColor.GRAY));
        return true;
    }
}
