package dev.nxeon.golden.channels;

import io.papermc.paper.event.player.AsyncChatEvent;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.audience.Audience;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden chat channels: global (default), local (radius), staff. /ch <global|local|staff>. Uses event.viewers(). */
public class Channels extends JavaPlugin implements Listener {
    enum Ch { GLOBAL, LOCAL, STAFF }
    private final Map<UUID, Ch> current = new ConcurrentHashMap<>();
    private final Map<UUID, Location> lastLoc = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("ch").setExecutor(this);
        // Locations are read on the main thread every second so the async chat thread never touches entities.
        getServer().getScheduler().runTaskTimer(this, () -> getServer().getOnlinePlayers().forEach(p -> lastLoc.put(p.getUniqueId(), p.getLocation())), 20L, 20L);
    }

    @EventHandler(ignoreCancelled = true)
    public void onChat(AsyncChatEvent event) {
        Player sender = event.getPlayer();
        Ch ch = current.getOrDefault(sender.getUniqueId(), Ch.GLOBAL);
        if (ch == Ch.GLOBAL) return;
        double r = getConfig().getDouble("local-radius", 100);
        Location from = lastLoc.get(sender.getUniqueId());
        event.viewers().removeIf(a -> {
            if (!(a instanceof Player v)) return false; // keep the console
            if (ch == Ch.STAFF) return !v.hasPermission("goldenchannels.staff");
            Location at = lastLoc.get(v.getUniqueId());
            return from == null || at == null || at.getWorld() != from.getWorld() || at.distanceSquared(from) > r * r;
        });
        Component tag = Component.text(ch == Ch.STAFF ? "[Staff] " : "[Local] ", ch == Ch.STAFF ? NamedTextColor.RED : NamedTextColor.YELLOW);
        event.message(tag.append(event.message()));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent event) {
        current.remove(event.getPlayer().getUniqueId());
        lastLoc.remove(event.getPlayer().getUniqueId());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("list")) { sender.sendMessage(Component.text("Channels: global, local, staff", NamedTextColor.AQUA)); return true; }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        Ch ch;
        try { ch = Ch.valueOf(args.length == 1 ? args[0].toUpperCase() : "GLOBAL"); } catch (IllegalArgumentException e) { p.sendMessage(Component.text("Unknown channel.", NamedTextColor.RED)); return true; }
        if (ch == Ch.STAFF && !p.hasPermission("goldenchannels.staff")) { p.sendMessage(Component.text("Staff only.", NamedTextColor.RED)); return true; }
        current.put(p.getUniqueId(), ch);
        p.sendMessage(Component.text("You now talk in " + ch.name().toLowerCase() + ".", NamedTextColor.GREEN));
        return true;
    }
}
