public class Mail extends JavaPlugin implements Listener {
    private final Map<UUID, UUID> lastFrom = new ConcurrentHashMap<>();
    private File file;
    private YamlConfiguration data;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "mail.yml");
        data = YamlConfiguration.loadConfiguration(file);
        for (String c : new String[] {"pm", "r", "mail"}) getCommand(c).setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        try { data.save(file); } catch (IOException e) { getLogger().warning("mail.yml: " + e.getMessage()); }
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent event) {
        int n = data.getStringList(event.getPlayer().getUniqueId() + ".inbox").size();
        if (n > 0) event.getPlayer().sendMessage(Component.text("You have " + n + " mail. /mail read", NamedTextColor.GOLD));
    }

    private void pm(CommandSender from, Player to, String text) {
        Component line = Component.text("[" + from.getName() + " -> " + to.getName() + "] ", NamedTextColor.LIGHT_PURPLE).append(Component.text(text, NamedTextColor.WHITE));
        from.sendMessage(line);
        to.sendMessage(line);
        if (from instanceof Player p) lastFrom.put(to.getUniqueId(), p.getUniqueId());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        switch (command.getName().toLowerCase()) {
            case "pm" -> {
                if (args.length < 2) return false;
                Player to = Bukkit.getPlayerExact(args[0]);
                if (to == null) { sender.sendMessage(Component.text(args[0] + " is offline. Use /mail send.", NamedTextColor.RED)); return true; }
                pm(sender, to, String.join(" ", List.of(args).subList(1, args.length)));
            }
            case "r" -> {
                if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
                UUID id = lastFrom.get(p.getUniqueId());
                Player to = id == null ? null : Bukkit.getPlayer(id);
                if (to == null || args.length == 0) { p.sendMessage(Component.text("Nobody to reply to.", NamedTextColor.RED)); return true; }
                pm(p, to, String.join(" ", args));
            }
            default -> {
                if (args.length >= 3 && args[0].equalsIgnoreCase("send")) {
                    OfflinePlayer to = Bukkit.getOfflinePlayerIfCached(args[1]);
                    if (to == null) { sender.sendMessage(Component.text("Unknown player " + args[1] + " (they must have joined before).", NamedTextColor.RED)); return true; }
                    List<String> inbox = new ArrayList<>(data.getStringList(to.getUniqueId() + ".inbox"));
                    if (inbox.size() >= getConfig().getInt("max-inbox", 50)) { sender.sendMessage(Component.text("Their inbox is full.", NamedTextColor.RED)); return true; }
                    inbox.add(sender.getName() + ": " + String.join(" ", List.of(args).subList(2, args.length)));
                    data.set(to.getUniqueId() + ".inbox", inbox);
                    save();
                    sender.sendMessage(Component.text("Mail sent.", NamedTextColor.GREEN));
                    return true;
                }
                if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Console can only /mail send.", NamedTextColor.RED)); return true; }
                String path = p.getUniqueId() + ".inbox";
                if (args.length == 1 && args[0].equalsIgnoreCase("clear")) { data.set(path, null); save(); p.sendMessage(Component.text("Inbox cleared.", NamedTextColor.YELLOW)); return true; }
                List<String> inbox = data.getStringList(path);
                p.sendMessage(Component.text(inbox.isEmpty() ? "No mail." : "Mail (" + inbox.size() + "):", NamedTextColor.GOLD));
                inbox.forEach(m -> p.sendMessage(Component.text(" - " + m)));
            }
        }
        return true;
    }
}
