import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerCommandPreprocessEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden custom text commands + blocked commands via PlayerCommandPreprocessEvent: /rules, /discord style info
 * commands from config (no plugin.yml entry needed for them), and a blocked-command list (e.g. /pl for players).
 * Never dispatches console commands built from player text.
 */
public class CustomCommands extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("customcmds").setExecutor(this);
    }

    @EventHandler(priority = EventPriority.LOWEST, ignoreCancelled = true)
    public void onCommand(PlayerCommandPreprocessEvent event) {
        String root = event.getMessage().substring(1).split(" ", 2)[0].toLowerCase(Locale.ROOT);
        if (getConfig().getStringList("blocked").contains(root) && !event.getPlayer().hasPermission("goldencmds.bypass")) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(Component.text("That command is disabled here.", NamedTextColor.RED));
            return;
        }
        ConfigurationSection text = getConfig().getConfigurationSection("text-commands");
        if (text != null && text.isList(root)) {
            event.setCancelled(true);
            for (String line : text.getStringList(root)) event.getPlayer().sendMessage(MiniMessage.miniMessage().deserialize(line));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        reloadConfig();
        ConfigurationSection text = getConfig().getConfigurationSection("text-commands");
        sender.sendMessage(Component.text("GoldenCustomCommands: " + (text == null ? 0 : text.getKeys(false).size()) + " text commands, " + getConfig().getStringList("blocked").size() + " blocked.", NamedTextColor.GREEN));
        return true;
    }
}
