package dev.nxeon.golden.logingate;

import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.AsyncPlayerPreLoginEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden maintenance mode / login gate: AsyncPlayerPreLoginEvent runs OFF the main thread before the player exists,
 * so it only reads a concurrent set of allowed names copied from config on the main thread.
 */
public class LoginGate extends JavaPlugin implements Listener {
    private volatile boolean maintenance;
    private final Set<String> allowed = ConcurrentHashMap.newKeySet();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("maintenance").setExecutor(this);
    }

    private void load() {
        maintenance = getConfig().getBoolean("maintenance", false);
        allowed.clear();
        getConfig().getStringList("allowed").forEach(n -> allowed.add(n.toLowerCase()));
    }

    @EventHandler
    public void onPreLogin(AsyncPlayerPreLoginEvent event) {
        if (maintenance && !allowed.contains(event.getName().toLowerCase())) {
            event.disallow(AsyncPlayerPreLoginEvent.Result.KICK_OTHER, Component.text(getConfig().getString("kick-message", "Maintenance, back soon."), NamedTextColor.GOLD));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && (args[0].equalsIgnoreCase("on") || args[0].equalsIgnoreCase("off"))) {
            getConfig().set("maintenance", args[0].equalsIgnoreCase("on"));
            saveConfig();
        } else reloadConfig();
        load();
        sender.sendMessage(Component.text("Maintenance is " + (maintenance ? "ON" : "OFF") + " (" + allowed.size() + " allowed).", NamedTextColor.YELLOW));
        return true;
    }
}
