mk("mc-warps", "warps", "Warps", r'''
package dev.nxeon.golden.warps;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.event.inventory.InventoryOpenEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden warps: /setwarp, /delwarp, /warp [name] opens a chest menu (InventoryHolder, click + drag cancelled). */
public class Warps extends JavaPlugin implements Listener {
    static final class Menu implements InventoryHolder {
        final Inventory inv;
        final List<String> names = new ArrayList<>();
        Menu(int size) { inv = Bukkit.createInventory(this, size, Component.text("Warps")); }
        @Override public Inventory getInventory() { return inv; }
    }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String c : new String[] {"warp", "setwarp", "delwarp"}) getCommand(c).setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private ConfigurationSection warps() {
        ConfigurationSection s = getConfig().getConfigurationSection("warps");
        return s != null ? s : getConfig().createSection("warps");
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmd = command.getName().toLowerCase();
        if (cmd.equals("warp") && args.length == 1 && args[0].equalsIgnoreCase("list")) { sender.sendMessage(Component.text("Warps: " + String.join(", ", warps().getKeys(false)), NamedTextColor.AQUA)); return true; }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        if (cmd.equals("setwarp") || cmd.equals("delwarp")) {
            if (args.length != 1 || !args[0].matches("[a-z0-9_]{1,16}")) return false;
            warps().set(args[0], cmd.equals("setwarp") ? p.getLocation() : null);
            saveConfig();
            p.sendMessage(Component.text("Warp " + args[0] + (cmd.equals("setwarp") ? " set." : " deleted."), NamedTextColor.GREEN));
            return true;
        }
        if (args.length == 1) { go(p, args[0]); return true; }
        List<String> names = new ArrayList<>(warps().getKeys(false));
        Menu menu = new Menu(Math.min(54, Math.max(9, (names.size() + 8) / 9 * 9)));
        for (String n : names) {
            if (menu.names.size() >= menu.inv.getSize()) break;
            ItemStack icon = new ItemStack(Material.ENDER_PEARL);
            icon.editMeta(m -> m.displayName(Component.text(n, NamedTextColor.AQUA).decoration(TextDecoration.ITALIC, false)));
            menu.inv.setItem(menu.names.size(), icon);
            menu.names.add(n);
        }
        p.openInventory(menu.getInventory());
        return true;
    }

    private void go(Player p, String name) {
        Location loc = warps().getLocation(name);
        if (loc == null || loc.getWorld() == null) { p.sendMessage(Component.text("No warp " + name + ".", NamedTextColor.RED)); return; }
        p.teleportAsync(loc);
    }

    @EventHandler
    public void onOpen(InventoryOpenEvent event) {
        if (event.getInventory().getHolder(false) instanceof Menu menu && menu.names.isEmpty()) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(Component.text("There are no warps yet.", NamedTextColor.GRAY));
        }
    }

    @EventHandler
    public void onClick(InventoryClickEvent event) {
        if (!(event.getInventory().getHolder(false) instanceof Menu menu)) return;
        event.setCancelled(true);
        int slot = event.getRawSlot();
        if (slot < 0 || slot >= menu.names.size() || !(event.getWhoClicked() instanceof Player p)) return;
        String name = menu.names.get(slot);
        getServer().getScheduler().runTask(this, () -> { p.closeInventory(); go(p, name); });
    }

    @EventHandler
    public void onDrag(InventoryDragEvent event) {
        if (event.getInventory().getHolder(false) instanceof Menu) event.setCancelled(true);
    }
}
''', yml("GoldenWarps", "dev.nxeon.golden.warps.Warps", "Golden reference - warps with a menu",
