"warmup-seconds: 3\ncooldown-seconds: 30\nrequest-timeout-seconds: 60\n")

mk("mc-rtp", "rtp", "Rtp", r'''
package dev.nxeon.golden.rtp;

import java.util.Map;
import java.util.Random;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden /rtp (async chunk load, safe-spot checks, cooldown) + /back (last teleport-from location). */
public class Rtp extends JavaPlugin implements Listener {
    private final Random random = new Random();
    private final Map<UUID, Location> back = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("rtp").setExecutor(this);
        getCommand("back").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler(ignoreCancelled = true)
    public void onTeleport(PlayerTeleportEvent event) {
        back.put(event.getPlayer().getUniqueId(), event.getFrom());
    }

    static boolean safe(Block feet) {
        Block ground = feet.getRelative(BlockFace.DOWN);
        return ground.getType().isSolid() && ground.getType() != Material.MAGMA_BLOCK && !feet.getType().isSolid() && !feet.isLiquid()
            && !feet.getRelative(BlockFace.UP).getType().isSolid() && !ground.isLiquid();
    }

    private void attempt(Player p, World w, int tries) {
        if (tries <= 0) { p.sendMessage(Component.text("No safe spot found, try again.", NamedTextColor.RED)); return; }
        int r = getConfig().getInt("radius", 2000);
        int x = random.nextInt(r * 2) - r, z = random.nextInt(r * 2) - r;
        w.getChunkAtAsync(x >> 4, z >> 4).thenAccept(chunk -> {
            Block feet = w.getHighestBlockAt(x, z).getRelative(BlockFace.UP);
            if (w.getEnvironment() == World.Environment.NETHER || !safe(feet)) { attempt(p, w, tries - 1); return; }
            p.teleportAsync(feet.getLocation().add(0.5, 0, 0.5));
        });
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only (radius " + getConfig().getInt("radius", 2000) + ").", NamedTextColor.RED)); return true; }
        if (command.getName().equalsIgnoreCase("back")) {
            Location l = back.get(p.getUniqueId());
            if (l == null) p.sendMessage(Component.text("Nowhere to go back to.", NamedTextColor.RED));
            else p.teleportAsync(l);
            return true;
        }
        attempt(p, p.getWorld(), getConfig().getInt("max-tries", 8));
        return true;
    }
}
''', yml("GoldenRtp", "dev.nxeon.golden.rtp.Rtp", "Golden reference - random teleport and back",
 {"rtp": ("Random teleport", "/rtp", "goldenrtp.use"), "back": ("Go back", "/back", "goldenrtp.back")},
 {"goldenrtp.use": ("Use /rtp", "true"), "goldenrtp.back": ("Use /back", "op")}),
 {"archetype": "back_rtp", "rcon": [R("rtp", "Players only (radius 2000).")]},
"radius: 2000\nmax-tries: 8\n")

mk("mc-economy", "economy", "Economy", r'''
package dev.nxeon.golden.economy;

import java.io.File;
import java.io.IOException;
import java.util.Comparator;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.plugin.ServicePriority;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden economy: balances in cents (long, never double), /bal, /pay, /baltop, /eco give|take (console). The mod's own
 * API is offered to other Cyrus mods through the Bukkit ServicesManager (no Vault).
 */
public class Economy extends JavaPlugin {
    /** What other plugins can look up with getServer().getServicesManager().load(Economy.Bank.class). */
    public interface Bank { long balanceCents(UUID player); boolean withdraw(UUID player, long cents); void deposit(UUID player, long cents); }

    private final Map<UUID, Long> balances = new ConcurrentHashMap<>();
    private File file;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "balances.yml");
        YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
        for (String k : y.getKeys(false)) balances.put(UUID.fromString(k), y.getLong(k));
        for (String c : new String[] {"bal", "pay", "baltop", "eco"}) getCommand(c).setExecutor(this);
        getServer().getServicesManager().register(Bank.class, new Bank() {
            public long balanceCents(UUID p) { return bal(p); }
            public boolean withdraw(UUID p, long c) { if (c < 0 || bal(p) < c) return false; balances.merge(p, -c, Long::sum); return true; }
            public void deposit(UUID p, long c) { if (c > 0) balances.merge(p, c, Long::sum); }
        }, this, ServicePriority.Normal);
        getServer().getScheduler().runTaskTimer(this, this::save, 6000L, 6000L);
    }

    @Override
    public void onDisable() {
        getServer().getServicesManager().unregisterAll(this);
        save();
    }

    private long bal(UUID p) { return balances.getOrDefault(p, getConfig().getLong("starting-cents", 10000)); }

    private void save() {
        YamlConfiguration y = new YamlConfiguration();
        balances.forEach((k, v) -> y.set(k.toString(), v));
        try { y.save(file); } catch (IOException e) { getLogger().warning("balances.yml: " + e.getMessage()); }
    }

    private String fmt(long cents) { return getConfig().getString("symbol", "$") + String.format("%d.%02d", cents / 100, Math.abs(cents % 100)); }

    static long parseCents(String s) {
        java.math.BigDecimal d = new java.math.BigDecimal(s);
        if (d.signum() <= 0 || d.scale() > 2) throw new NumberFormatException("amount");
        return d.movePointRight(2).longValueExact();
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String cmd = command.getName().toLowerCase();
        if (cmd.equals("baltop")) {
            sender.sendMessage(Component.text("Top balances:", NamedTextColor.GOLD));
            balances.entrySet().stream().sorted(Map.Entry.<UUID, Long>comparingByValue(Comparator.reverseOrder())).limit(10).forEach(e -> {
                OfflinePlayer op = Bukkit.getOfflinePlayer(e.getKey());
                sender.sendMessage(Component.text(" " + (op.getName() == null ? e.getKey().toString().substring(0, 8) : op.getName()) + ": " + fmt(e.getValue())));
            });
            return true;
        }
        if (cmd.equals("eco")) {
            if (args.length != 3) { sender.sendMessage(Component.text("/eco <give|take> <player> <amount>", NamedTextColor.GRAY)); return true; }
            OfflinePlayer target = Bukkit.getOfflinePlayerIfCached(args[1]);
            if (target == null) { sender.sendMessage(Component.text("Unknown player " + args[1] + ".", NamedTextColor.RED)); return true; }
            long c;
            try { c = parseCents(args[2]); } catch (RuntimeException e) { sender.sendMessage(Component.text("Bad amount.", NamedTextColor.RED)); return true; }
            balances.put(target.getUniqueId(), Math.max(0, bal(target.getUniqueId()) + (args[0].equalsIgnoreCase("take") ? -c : c)));
            sender.sendMessage(Component.text(args[1] + " now has " + fmt(bal(target.getUniqueId())) + ".", NamedTextColor.GREEN));
            return true;
        }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only. Starting balance " + fmt(getConfig().getLong("starting-cents", 10000)) + ".", NamedTextColor.RED)); return true; }
        if (cmd.equals("bal")) { p.sendMessage(Component.text("Balance: " + fmt(bal(p.getUniqueId())), NamedTextColor.GREEN)); return true; }
        Player to = args.length == 2 ? Bukkit.getPlayerExact(args[0]) : null;
        if (to == null || to == p) { p.sendMessage(Component.text("Usage: /pay <online player> <amount>", NamedTextColor.RED)); return true; }
        long c;
        try { c = parseCents(args[1]); } catch (RuntimeException e) { p.sendMessage(Component.text("Bad amount.", NamedTextColor.RED)); return true; }
        if (bal(p.getUniqueId()) < c) { p.sendMessage(Component.text("Not enough money.", NamedTextColor.RED)); return true; }
        balances.put(p.getUniqueId(), bal(p.getUniqueId()) - c);
        balances.put(to.getUniqueId(), bal(to.getUniqueId()) + c);
        p.sendMessage(Component.text("Paid " + fmt(c) + " to " + to.getName() + ".", NamedTextColor.GREEN));
        to.sendMessage(Component.text(p.getName() + " paid you " + fmt(c) + ".", NamedTextColor.GREEN));
        return true;
    }
}
''', yml("GoldenEconomy", "dev.nxeon.golden.economy.Economy", "Golden reference - economy",
 {"bal": ("Your balance", "/bal", "goldeneco.use"), "pay": ("Pay a player", "/pay <player> <amount>", "goldeneco.use"), "baltop": ("Richest players", "/baltop", "goldeneco.use"), "eco": ("Admin money", "/eco <give|take> <player> <amount>", "goldeneco.admin")},
 {"goldeneco.use": ("Use money commands", "true"), "goldeneco.admin": ("Give and take money", "op")}),
 {"archetype": "economy", "rcon": [R("bal", "Players only. Starting balance $100.00."), R("eco give Nobody 5", "Unknown player Nobody."), R("baltop", "Top balances:")]},
'symbol: "$"\n# 10000 cents = 100.00\nstarting-cents: 10000\n')

mk("mc-shop", "shop", "Shop", r'''
package dev.nxeon.golden.shop;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryDragEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden admin shop: chest menu priced in XP levels or an item currency (emeralds); left = buy, right = sell 1. */
public class Shop extends JavaPlugin implements Listener {
    record Offer(Material item, int amount, int buy, int sell) {}
    private final List<Offer> offers = new ArrayList<>();
    static final class Menu implements InventoryHolder {
        final Inventory inv = Bukkit.createInventory(this, 27, Component.text("Shop"));
        @Override public Inventory getInventory() { return inv; }
    }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getCommand("shop").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void load() {
        offers.clear();
        for (Map<?, ?> m : getConfig().getMapList("offers")) {
            Material mat = Material.matchMaterial(String.valueOf(m.get("item")));
            if (mat == null || !mat.isItem()) { getLogger().warning("Unknown shop item " + m.get("item")); continue; }
            offers.add(new Offer(mat, ((Number) m.get("amount")).intValue(), ((Number) m.get("buy")).intValue(), ((Number) m.get("sell")).intValue()));
        }
    }

    private Material currency() { Material m = Material.matchMaterial(getConfig().getString("currency", "emerald")); return m == null ? Material.EMERALD : m; }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) { reloadConfig(); load(); sender.sendMessage(Component.text("GoldenShop: " + offers.size() + " offers, currency " + currency().getKey().getKey() + ".", NamedTextColor.GREEN)); return true; }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        Menu menu = new Menu();
        for (int i = 0; i < offers.size() && i < 27; i++) {
            Offer o = offers.get(i);
            ItemStack icon = new ItemStack(o.item(), o.amount());
            icon.editMeta(meta -> meta.lore(List.of(
                Component.text("Buy: " + o.buy() + " " + currency().getKey().getKey(), NamedTextColor.GREEN).decoration(TextDecoration.ITALIC, false),
                Component.text("Sell: " + o.sell(), NamedTextColor.YELLOW).decoration(TextDecoration.ITALIC, false))));
            menu.inv.setItem(i, icon);
        }
        p.openInventory(menu.getInventory());
        return true;
    }

    @EventHandler
    public void onClick(InventoryClickEvent event) {
        if (!(event.getInventory().getHolder(false) instanceof Menu)) return;
        event.setCancelled(true); // blocks shift-clicks, number keys and double-clicks into or out of the menu too
        int slot = event.getRawSlot();
        if (slot < 0 || slot >= offers.size() || slot >= 27 || !(event.getWhoClicked() instanceof Player p)) return;
        Offer o = offers.get(slot);
        Material cur = currency();
        if (event.isLeftClick()) {
