package dev.nxeon.golden.tpa;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.event.ClickEvent;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

/** Golden /spawn + /tpa: requests expire, warmup cancelled on move (block change) or damage, cooldown. */
public class Tpa extends JavaPlugin implements Listener {
    record Request(UUID from, long at) {}
    private final Map<UUID, Request> requests = new ConcurrentHashMap<>();
    private final Map<UUID, BukkitTask> warmups = new ConcurrentHashMap<>();
    private final Map<UUID, Long> cooldown = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String c : new String[] {"tpa", "tpaccept", "spawn"}) getCommand(c).setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void warmup(Player p, Location to) {
        long left = cooldown.getOrDefault(p.getUniqueId(), 0L) - System.currentTimeMillis();
        if (left > 0 && !p.hasPermission("goldentpa.bypass")) { p.sendMessage(Component.text("Wait " + (left / 1000 + 1) + " s.", NamedTextColor.RED)); return; }
        int secs = getConfig().getInt("warmup-seconds", 3);
        p.sendMessage(Component.text("Teleporting in " + secs + " s, do not move.", NamedTextColor.YELLOW));
        BukkitTask old = warmups.put(p.getUniqueId(), getServer().getScheduler().runTaskLater(this, () -> {
            warmups.remove(p.getUniqueId());
            cooldown.put(p.getUniqueId(), System.currentTimeMillis() + getConfig().getLong("cooldown-seconds", 30) * 1000);
            p.teleportAsync(to);
        }, secs * 20L));
        if (old != null) old.cancel();
    }

    private void cancel(Player p, String why) {
        BukkitTask t = warmups.remove(p.getUniqueId());
        if (t != null) { t.cancel(); p.sendMessage(Component.text("Teleport cancelled: " + why + ".", NamedTextColor.RED)); }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent event) {
        if (event.hasChangedBlock() && warmups.containsKey(event.getPlayer().getUniqueId())) cancel(event.getPlayer(), "you moved");
    }

    @EventHandler(ignoreCancelled = true)
    public void onDamage(EntityDamageEvent event) {
        if (event.getEntity() instanceof Player p && warmups.containsKey(p.getUniqueId())) cancel(p, "you took damage");
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        switch (command.getName().toLowerCase()) {
            case "spawn" -> warmup(p, p.getWorld().getSpawnLocation());
            case "tpa" -> {
                Player to = args.length == 1 ? Bukkit.getPlayerExact(args[0]) : null;
                if (to == null || to == p) { p.sendMessage(Component.text("Usage: /tpa <online player>", NamedTextColor.RED)); return true; }
                requests.put(to.getUniqueId(), new Request(p.getUniqueId(), System.currentTimeMillis()));
                to.sendMessage(Component.text(p.getName() + " wants to teleport to you. ", NamedTextColor.GOLD).append(Component.text("[Accept]", NamedTextColor.GREEN).clickEvent(ClickEvent.runCommand("/tpaccept"))));
                p.sendMessage(Component.text("Request sent.", NamedTextColor.GREEN));
            }
            default -> {
                Request r = requests.remove(p.getUniqueId());
                Player from = r == null ? null : Bukkit.getPlayer(r.from());
                if (from == null || System.currentTimeMillis() - r.at() > getConfig().getLong("request-timeout-seconds", 60) * 1000) { p.sendMessage(Component.text("No pending request.", NamedTextColor.RED)); return true; }
                warmup(from, p.getLocation());
            }
        }
        return true;
    }
}
