package dev.nxeon.golden.kits;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import io.papermc.paper.registry.RegistryAccess;
import io.papermc.paper.registry.RegistryKey;

/** Golden kits: kits from config (items + enchantments by key), per-kit permission and cooldown saved to disk. */
public class Kits extends JavaPlugin {
    private File file;
    private YamlConfiguration used;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "cooldowns.yml");
        used = YamlConfiguration.loadConfiguration(file);
        getCommand("kit").setExecutor(this);
    }

    @Override
    public void onDisable() { try { used.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); } }

    List<ItemStack> items(ConfigurationSection kit) {
        List<ItemStack> out = new ArrayList<>();
        for (Map<?, ?> m : kit.getMapList("items")) {
            Material mat = Material.matchMaterial(String.valueOf(m.get("item")));
            if (mat == null) continue;
            ItemStack it = new ItemStack(mat, m.get("amount") instanceof Number n ? n.intValue() : 1);
            if (m.get("enchantments") instanceof Map<?, ?> en) for (Map.Entry<?, ?> e : en.entrySet()) {
                NamespacedKey key = NamespacedKey.fromString(String.valueOf(e.getKey()));
                Enchantment ench = key == null ? null : RegistryAccess.registryAccess().getRegistry(RegistryKey.ENCHANTMENT).get(key);
                if (ench != null) it.addUnsafeEnchantment(ench, ((Number) e.getValue()).intValue());
            }
            out.add(it);
        }
        return out;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        ConfigurationSection kits = getConfig().getConfigurationSection("kits");
        if (kits == null) { sender.sendMessage(Component.text("No kits configured.", NamedTextColor.RED)); return true; }
        if (args.length == 0 || args[0].equalsIgnoreCase("list")) {
            StringBuilder sb = new StringBuilder("Kits:");
            for (String k : kits.getKeys(false)) sb.append(' ').append(k).append('(').append(items(kits.getConfigurationSection(k)).size()).append(')');
            sender.sendMessage(Component.text(sb.toString(), NamedTextColor.AQUA));
            return true;
        }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        ConfigurationSection kit = kits.getConfigurationSection(args[0].toLowerCase());
        if (kit == null) { p.sendMessage(Component.text("No such kit.", NamedTextColor.RED)); return true; }
        if (!p.hasPermission("goldenkits.kit." + args[0].toLowerCase())) { p.sendMessage(Component.text("You cannot use this kit.", NamedTextColor.RED)); return true; }
        String path = p.getUniqueId() + "." + args[0].toLowerCase();
        long next = used.getLong(path) + kit.getLong("cooldown-seconds", 86400) * 1000;
        if (System.currentTimeMillis() < next) { p.sendMessage(Component.text("Ready in " + ((next - System.currentTimeMillis()) / 60000 + 1) + " min.", NamedTextColor.RED)); return true; }
        used.set(path, System.currentTimeMillis());
        p.getInventory().addItem(items(kit).toArray(new ItemStack[0])).values().forEach(left -> p.getWorld().dropItemNaturally(p.getLocation(), left));
        p.sendMessage(Component.text("Kit " + args[0] + " received.", NamedTextColor.GREEN));
        return true;
    }
}
