import org.bukkit.inventory.MerchantRecipe;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden villager trades: extra trades added when a villager of a configured profession (looked up in the registry:
 * Villager.Profession is an interface on every 1.21.x, so no switch) acquires a trade; wandering traders get a fixed
 * extra trade; /tradeshop opens a custom merchant menu.
 */
public class Trades extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("tradeshop").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    List<MerchantRecipe> recipes(String section) {
        List<MerchantRecipe> out = new ArrayList<>();
        for (Map<?, ?> m : getConfig().getMapList(section)) {
            Material give = Material.matchMaterial(String.valueOf(m.get("give"))), cost = Material.matchMaterial(String.valueOf(m.get("cost")));
            if (give == null || cost == null) continue;
            MerchantRecipe r = new MerchantRecipe(new ItemStack(give, ((Number) m.get("give-amount")).intValue()), ((Number) m.get("max-uses")).intValue());
            r.addIngredient(new ItemStack(cost, ((Number) m.get("cost-amount")).intValue()));
            out.add(r);
        }
        return out;
    }

    @EventHandler(ignoreCancelled = true)
