    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        List<MerchantRecipe> shop = recipes("shop-trades");
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenTrades: " + shop.size() + " shop trades, profession " + getConfig().getString("profession") + (Registry.VILLAGER_PROFESSION.get(NamespacedKey.minecraft(getConfig().getString("profession", "librarian"))) != null ? " ok" : " UNKNOWN") + ".", NamedTextColor.GREEN)); return true; }
        Merchant m = Bukkit.createMerchant(Component.text("Trader"));
        m.setRecipes(shop);
        p.openMerchant(m, true);
        return true;
    }
}
