    @EventHandler(ignoreCancelled = true)
    public void onSign(SignChangeEvent event) {
        if (!event.getPlayer().hasPermission("goldensigns.color")) return;
        for (int i = 0; i < event.lines().size(); i++) {
            Component line = event.line(i);
            if (line == null) continue;
            String raw = PlainTextComponentSerializer.plainText().serialize(line);
            event.line(i, LegacyComponentSerializer.legacyAmpersand().deserialize(raw));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onClick(PlayerInteractEvent event) {
        if (event.getAction() != Action.RIGHT_CLICK_BLOCK || event.getHand() != EquipmentSlot.HAND) return;
        Block b = event.getClickedBlock();
        if (b == null) return;
        BlockState state = b.getState(false);
        if (!(state instanceof Sign sign)) return;
        String first = PlainTextComponentSerializer.plainText().serialize(sign.getSide(Side.FRONT).line(0));
        if (first.equalsIgnoreCase(getConfig().getString("spawn-tag", "[Spawn]"))) {
            event.setCancelled(true); // do not open the sign editor
            event.getPlayer().teleportAsync(event.getPlayer().getWorld().getSpawnLocation());
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(LegacyComponentSerializer.legacyAmpersand().deserialize("&aGoldenSigns &7tag " + getConfig().getString("spawn-tag", "[Spawn]")));
        return true;
    }
}
