from mk import mk, yml, R

mk("mc-ranks", "ranks", "Ranks", r'''
package dev.nxeon.golden.ranks;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.Bukkit;
import org.bukkit.OfflinePlayer;
import org.bukkit.Statistic;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.permissions.PermissionAttachment;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden ranks + rankup by playtime: groups with a prefix and permission nodes from config, applied with one
 * PermissionAttachment per online player (removed on quit). The scan reports runtime permission grants as a warning.
 */
public class Ranks extends JavaPlugin implements Listener {
    private final Map<UUID, PermissionAttachment> attachments = new HashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("rank").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getOnlinePlayers().forEach(this::apply);
    }

    @Override
    public void onDisable() {
        attachments.values().forEach(PermissionAttachment::remove);
        attachments.clear();
    }

    private String rankOf(UUID id) { return getConfig().getString("players." + id, getConfig().getString("default-rank", "member")); }

    void apply(Player p) {
        PermissionAttachment old = attachments.remove(p.getUniqueId());
        if (old != null) old.remove();
        ConfigurationSection r = getConfig().getConfigurationSection("ranks." + rankOf(p.getUniqueId()));
        if (r == null) return;
        PermissionAttachment a = p.addAttachment(this);
        for (String node : r.getStringList("permissions")) a.setPermission(node, true);
        attachments.put(p.getUniqueId(), a);
        p.playerListName(MiniMessage.miniMessage().deserialize(r.getString("prefix", "")).append(Component.text(p.getName())));
    }

    @EventHandler public void onJoin(PlayerJoinEvent e) { apply(e.getPlayer()); }
    @EventHandler public void onQuit(PlayerQuitEvent e) { PermissionAttachment a = attachments.remove(e.getPlayer().getUniqueId()); if (a != null) a.remove(); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 3 && args[0].equalsIgnoreCase("set") && sender.hasPermission("goldenranks.admin")) {
            if (getConfig().getConfigurationSection("ranks." + args[2]) == null) { sender.sendMessage(Component.text("No rank " + args[2] + ".", NamedTextColor.RED)); return true; }
            OfflinePlayer op = Bukkit.getOfflinePlayerIfCached(args[1]);
            if (op == null) { sender.sendMessage(Component.text("Unknown player " + args[1] + ".", NamedTextColor.RED)); return true; }
            getConfig().set("players." + op.getUniqueId(), args[2]);
            saveConfig();
            if (op.getPlayer() != null) apply(op.getPlayer());
            sender.sendMessage(Component.text(args[1] + " is now " + args[2] + ".", NamedTextColor.GREEN));
            return true;
        }
        if (args.length == 1 && args[0].equalsIgnoreCase("list")) {
            ConfigurationSection rs = getConfig().getConfigurationSection("ranks");
            sender.sendMessage(Component.text("Ranks: " + (rs == null ? "none" : String.join(", ", rs.getKeys(false))), NamedTextColor.AQUA));
            return true;
        }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("/rank list | set <player> <rank>", NamedTextColor.GRAY)); return true; }
        // rankup: PLAY_ONE_MINUTE counts TICKS despite its name (20 per second).
        long minutes = p.getStatistic(Statistic.PLAY_ONE_MINUTE) / 20 / 60;
        String next = getConfig().getString("ranks." + rankOf(p.getUniqueId()) + ".next", "");
        long need = getConfig().getLong("ranks." + next + ".minutes", Long.MAX_VALUE);
        if (next.isEmpty() || minutes < need) { p.sendMessage(Component.text("Rank " + rankOf(p.getUniqueId()) + ", " + minutes + " min played" + (next.isEmpty() ? "." : "; " + next + " at " + need + " min."), NamedTextColor.YELLOW)); return true; }
        getConfig().set("players." + p.getUniqueId(), next);
        saveConfig();
        apply(p);
        p.sendMessage(Component.text("Ranked up to " + next + "!", NamedTextColor.GOLD));
        return true;
    }
}
''', yml("GoldenRanks", "dev.nxeon.golden.ranks.Ranks", "Golden reference - ranks and rankup",
