import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPistonExtendEvent;
import org.bukkit.event.block.BlockPistonRetractEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.event.player.PlayerBucketEmptyEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden chunk claims: /claim, /unclaim, /trust <player>. Protects break, place, buckets, container use, explosions and
 * pistons pushing/pulling across a claim border (the usual holes). Claims keyed by world + chunk key.
 */
public class Claims extends JavaPlugin implements Listener {
    record Claim(UUID owner, List<UUID> trusted) {}
    private final Map<String, Claim> claims = new ConcurrentHashMap<>();
    private File file;

    static String key(Chunk c) { return c.getWorld().getName() + ":" + c.getChunkKey(); }
    static String key(Block b) { return key(b.getChunk()); }

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "claims.yml");
        YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
        for (String k : y.getKeys(false)) claims.put(k.replace('|', ':'), new Claim(UUID.fromString(y.getString(k + ".owner")), new ArrayList<>(y.getStringList(k + ".trusted").stream().map(UUID::fromString).toList())));
        for (String c : new String[] {"claim", "unclaim", "trust"}) getCommand(c).setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() { save(); }

    private void save() {
        YamlConfiguration y = new YamlConfiguration();
        claims.forEach((k, c) -> { String s = k.replace(':', '|'); y.set(s + ".owner", c.owner().toString()); y.set(s + ".trusted", c.trusted().stream().map(UUID::toString).toList()); });
        try { y.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); }
    }

    boolean may(Player p, Block b) {
        Claim c = claims.get(key(b));
        return c == null || c.owner().equals(p.getUniqueId()) || c.trusted().contains(p.getUniqueId()) || p.hasPermission("goldenclaims.bypass");
    }

    private void deny(org.bukkit.event.Cancellable e, Player p) { e.setCancelled(true); p.sendActionBar(Component.text("This land is claimed.", NamedTextColor.RED)); }

    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true) public void onBreak(BlockBreakEvent e) { if (!may(e.getPlayer(), e.getBlock())) deny(e, e.getPlayer()); }
    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true) public void onPlace(BlockPlaceEvent e) { if (!may(e.getPlayer(), e.getBlock())) deny(e, e.getPlayer()); }
    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true) public void onBucket(PlayerBucketEmptyEvent e) { if (!may(e.getPlayer(), e.getBlock())) deny(e, e.getPlayer()); }
    @EventHandler(priority = EventPriority.LOW)
    public void onInteract(PlayerInteractEvent e) {
        Block b = e.getClickedBlock();
        if (b != null && b.getState(false) instanceof org.bukkit.block.Container && !may(e.getPlayer(), b)) deny(e, e.getPlayer());
    }
    @EventHandler(ignoreCancelled = true) public void onExplode(EntityExplodeEvent e) { e.blockList().removeIf(b -> claims.containsKey(key(b))); }

    /** A piston may only move blocks inside the same claim state as the piston itself. */
    private boolean crosses(Block piston, List<Block> moved, org.bukkit.block.BlockFace dir) {
        Claim home = claims.get(key(piston));
        for (Block b : moved) for (Block t : new Block[] {b, b.getRelative(dir)}) if (claims.get(key(t)) != home) return true;
        return false;
    }
    @EventHandler(ignoreCancelled = true) public void onExtend(BlockPistonExtendEvent e) { if (crosses(e.getBlock(), e.getBlocks(), e.getDirection())) e.setCancelled(true); }
    @EventHandler(ignoreCancelled = true) public void onRetract(BlockPistonRetractEvent e) { if (crosses(e.getBlock(), e.getBlocks(), e.getDirection())) e.setCancelled(true); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenClaims: " + claims.size() + " claimed chunks, max " + getConfig().getInt("max-claims", 16) + " per player.", NamedTextColor.GREEN)); return true; }
        String k = key(p.getLocation().getChunk());
        Claim c = claims.get(k);
        switch (command.getName().toLowerCase()) {
            case "claim" -> {
                if (c != null) { p.sendMessage(Component.text("Already claimed.", NamedTextColor.RED)); return true; }
                long mine = claims.values().stream().filter(x -> x.owner().equals(p.getUniqueId())).count();
                if (mine >= getConfig().getInt("max-claims", 16)) { p.sendMessage(Component.text("Claim limit reached.", NamedTextColor.RED)); return true; }
                claims.put(k, new Claim(p.getUniqueId(), new ArrayList<>()));
                p.sendMessage(Component.text("Chunk claimed.", NamedTextColor.GREEN));
            }
            case "unclaim" -> {
                if (c == null || !c.owner().equals(p.getUniqueId())) { p.sendMessage(Component.text("Not your claim.", NamedTextColor.RED)); return true; }
                claims.remove(k);
                p.sendMessage(Component.text("Unclaimed.", NamedTextColor.YELLOW));
            }
            default -> {
                OfflinePlayer t = args.length == 1 ? Bukkit.getOfflinePlayerIfCached(args[0]) : null;
                if (c == null || !c.owner().equals(p.getUniqueId()) || t == null) { p.sendMessage(Component.text("Stand in your claim: /trust <known player>", NamedTextColor.RED)); return true; }
                c.trusted().add(t.getUniqueId());
                p.sendMessage(Component.text("Trusted " + args[0] + ".", NamedTextColor.GREEN));
            }
        }
        save();
        return true;
    }
}
