package dev.nxeon.golden.regions;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.util.BoundingBox;

/** Golden safe zones: cuboid regions from config with flags pvp/build/explosions; projectile shooters count for PvP. */
public class Regions extends JavaPlugin implements Listener {
    record Region(String name, String world, BoundingBox box, boolean pvp, boolean build, boolean explosions) {}
    private final List<Region> regions = new ArrayList<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getCommand("regions").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void load() {
        regions.clear();
        ConfigurationSection s = getConfig().getConfigurationSection("regions");
        if (s == null) return;
        for (String n : s.getKeys(false)) {
            ConfigurationSection r = s.getConfigurationSection(n);
            List<Integer> a = r.getIntegerList("min"), b = r.getIntegerList("max");
            if (a.size() != 3 || b.size() != 3) { getLogger().warning("Region " + n + " needs min/max [x, y, z]"); continue; }
            regions.add(new Region(n, r.getString("world", "world"), new BoundingBox(a.get(0), a.get(1), a.get(2), b.get(0) + 1, b.get(1) + 1, b.get(2) + 1), r.getBoolean("pvp", false), r.getBoolean("build", false), r.getBoolean("explosions", false)));
        }
    }

    Region at(Location l) {
        for (Region r : regions) if (l.getWorld() != null && l.getWorld().getName().equals(r.world()) && r.box().contains(l.toVector())) return r;
        return null;
    }

    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) { Region r = at(e.getBlock().getLocation()); if (r != null && !r.build() && !e.getPlayer().hasPermission("goldenregions.bypass")) e.setCancelled(true); }
    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) { Region r = at(e.getBlock().getLocation()); if (r != null && !r.build() && !e.getPlayer().hasPermission("goldenregions.bypass")) e.setCancelled(true); }
    @EventHandler(ignoreCancelled = true)
    public void onExplode(EntityExplodeEvent e) { e.blockList().removeIf(b -> { Region r = at(b.getLocation()); return r != null && !r.explosions(); }); }
    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true)
    public void onPvp(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof Player)) return;
        Player attacker = e.getDamager() instanceof Player p ? p : e.getDamager() instanceof Projectile pr && pr.getShooter() instanceof Player s ? s : null;
        if (attacker == null) return;
        Region r = at(e.getEntity().getLocation());
        if (r != null && !r.pvp()) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        reloadConfig();
        load();
        sender.sendMessage(Component.text("GoldenRegions: " + regions.size() + " regions" + (regions.isEmpty() ? "" : " (" + String.join(", ", regions.stream().map(Region::name).toList()) + ")") + ".", NamedTextColor.GREEN));
        return true;
    }
}
