    @EventHandler(priority = EventPriority.LOWEST, ignoreCancelled = true)
    public void onChat(AsyncChatEvent e) {
        Long until = muted.get(e.getPlayer().getUniqueId());
        if (until != null && until > System.currentTimeMillis()) { e.setCancelled(true); e.getPlayer().sendMessage(Component.text("You are muted.", NamedTextColor.RED)); }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (e.hasChangedPosition() && frozen.containsKey(e.getPlayer().getUniqueId())) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length < 1) return false;
        Player target = Bukkit.getPlayerExact(args[0]);
        switch (command.getName().toLowerCase()) {
            case "mute" -> {
                if (target == null) { sender.sendMessage(Component.text(args[0] + " is not online.", NamedTextColor.RED)); return true; }
                long min = args.length > 1 ? Long.parseLong(args[1].replaceAll("[^0-9]", "0")) : getConfig().getLong("default-mute-minutes", 10);
                muted.put(target.getUniqueId(), System.currentTimeMillis() + min * 60000);
                sender.sendMessage(Component.text("Muted " + target.getName() + " for " + min + " min.", NamedTextColor.YELLOW));
            }
            case "freeze" -> {
                if (target == null) { sender.sendMessage(Component.text(args[0] + " is not online.", NamedTextColor.RED)); return true; }
                boolean on = frozen.remove(target.getUniqueId()) == null;
                if (on) frozen.put(target.getUniqueId(), true);
                sender.sendMessage(Component.text(target.getName() + (on ? " frozen." : " unfrozen."), NamedTextColor.YELLOW));
            }
            default -> {
                if (args.length < 3) { sender.sendMessage(Component.text("/tempban <player> <hours> <reason>", NamedTextColor.GRAY)); return true; }
                var profile = target != null ? target.getPlayerProfile() : Bukkit.createProfile(args[0]);
                long hours;
                try { hours = Long.parseLong(args[1]); } catch (NumberFormatException e) { sender.sendMessage(Component.text("Hours must be a number.", NamedTextColor.RED)); return true; }
                String reason = String.join(" ", List.of(args).subList(2, args.length));
                ProfileBanList bans = Bukkit.getBanList(BanListType.PROFILE);
                bans.addBan(profile, reason, Instant.now().plus(Duration.ofHours(hours)), sender.getName());
                if (target != null) target.kick(Component.text("Banned for " + hours + " h: " + reason, NamedTextColor.RED));
                sender.sendMessage(Component.text("Banned " + args[0] + " for " + hours + " h.", NamedTextColor.YELLOW));
            }
        }
        return true;
    }
}
