package dev.nxeon.golden.vanish;

import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden vanish: hidePlayer(plugin, p) for everyone without the see permission, also for players joining later. */
public class Vanish extends JavaPlugin implements Listener {
    private final Set<UUID> hidden = ConcurrentHashMap.newKeySet();

    @Override
    public void onEnable() {
        getCommand("vanish").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() {
        for (UUID id : hidden) { Player p = getServer().getPlayer(id); if (p != null) getServer().getOnlinePlayers().forEach(o -> o.showPlayer(this, p)); }
    }

    private void refresh(Player viewer) {
        for (UUID id : hidden) {
            Player p = getServer().getPlayer(id);
            if (p == null || p == viewer) continue;
            if (viewer.hasPermission("goldenvanish.see")) viewer.showPlayer(this, p); else viewer.hidePlayer(this, p);
        }
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        refresh(e.getPlayer());
        if (hidden.contains(e.getPlayer().getUniqueId())) e.joinMessage(null);
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { if (hidden.contains(e.getPlayer().getUniqueId())) e.quitMessage(null); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenVanish: " + hidden.size() + " hidden.", NamedTextColor.GRAY)); return true; }
        boolean on = hidden.add(p.getUniqueId());
        if (!on) hidden.remove(p.getUniqueId());
        for (Player o : getServer().getOnlinePlayers()) {
            if (o == p) continue;
            if (on && !o.hasPermission("goldenvanish.see")) o.hidePlayer(this, p); else o.showPlayer(this, p);
        }
        p.sendMessage(Component.text(on ? "You are vanished." : "You are visible.", NamedTextColor.AQUA));
        return true;
    }
}
