import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.CreatureSpawnEvent;
import org.bukkit.event.world.ChunkLoadEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden lag tools: per-chunk mob cap for NATURAL/SPAWNER/BREEDING spawns (CreatureSpawnEvent + SpawnReason; spawn
 * eggs and commands always work), ground-item sweep, chunk-load trim, /lag report.
 */
public class LagTools extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("lag").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        long every = Math.max(60, getConfig().getLong("clear-items-seconds", 600)) * 20L;
        getServer().getScheduler().runTaskTimer(this, this::sweep, every, every);
    }

    private int sweep() {
        int removed = 0;
        for (World w : getServer().getWorlds()) for (Item i : w.getEntitiesByClass(Item.class)) if (i.getTicksLived() > 20 * 60) { i.remove(); removed++; }
        return removed;
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onSpawn(CreatureSpawnEvent e) {
        CreatureSpawnEvent.SpawnReason r = e.getSpawnReason();
        if (r != CreatureSpawnEvent.SpawnReason.NATURAL && r != CreatureSpawnEvent.SpawnReason.SPAWNER && r != CreatureSpawnEvent.SpawnReason.BREEDING) return;
        int cap = getConfig().getInt("max-mobs-per-chunk", 40);
        if (e.getLocation().getChunk().getEntities().length >= cap) e.setCancelled(true);
    }

    @EventHandler
    public void onChunk(ChunkLoadEvent e) {
        if (e.isNewChunk()) return;
        Map<EntityType, Integer> count = new EnumMap<>(EntityType.class);
        int cap = getConfig().getInt("max-same-type-on-load", 60);
        for (Entity en : e.getChunk().getEntities()) {
            if (en.customName() != null || en instanceof org.bukkit.entity.Player) continue; // never named or tamed-by-name mobs
            if (count.merge(en.getType(), 1, Integer::sum) > cap) en.remove();
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("clear")) { sender.sendMessage(Component.text("Removed " + sweep() + " old ground items.", NamedTextColor.GREEN)); return true; }
        int entities = 0, chunks = 0;
        for (World w : getServer().getWorlds()) { entities += w.getEntityCount(); chunks += w.getLoadedChunks().length; }
        double tps = getServer().getTPS()[0];
        sender.sendMessage(Component.text(String.format("GoldenLag: TPS %.1f, %d entities, %d chunks loaded.", Math.min(20.0, tps), entities, chunks), NamedTextColor.AQUA));
        return true;
    }
}
