/**
 * Golden multiworld: /mw list | create <name> [flat|normal] | tp <name> | unload <name>. World names are validated;
 * creating a world blocks the main thread for a moment (say so), WorldLoad/WorldUnload are logged.
 */
public class Worlds extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("mw").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        for (String n : getConfig().getStringList("load-on-start")) if (n.matches("[a-z0-9_]{1,24}") && getServer().getWorld(n) == null) new WorldCreator(n).createWorld();
    }

    @EventHandler public void onLoad(WorldLoadEvent e) { getLogger().info("World loaded: " + e.getWorld().getName()); }
    @EventHandler public void onUnload(WorldUnloadEvent e) { getLogger().info("World unloading: " + e.getWorld().getName()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0].toLowerCase() : "list";
        if (sub.equals("list")) { sender.sendMessage(Component.text("Worlds: " + String.join(", ", getServer().getWorlds().stream().map(World::getName).toList()), NamedTextColor.AQUA)); return true; }
        if (args.length < 2 || !args[1].matches("[a-z0-9_]{1,24}")) { sender.sendMessage(Component.text("World names: 1-24 of a-z 0-9 _", NamedTextColor.RED)); return true; }
        World w = getServer().getWorld(args[1]);
        switch (sub) {
            case "create" -> {
                if (w != null) { sender.sendMessage(Component.text("Already exists.", NamedTextColor.RED)); return true; }
                if (getServer().getWorlds().size() >= getConfig().getInt("max-worlds", 6)) { sender.sendMessage(Component.text("World limit reached.", NamedTextColor.RED)); return true; }
                WorldCreator c = new WorldCreator(args[1]);
                if (args.length > 2 && args[2].equalsIgnoreCase("flat")) c.type(WorldType.FLAT);
                c.generateStructures(false);
                World made = c.createWorld();
                sender.sendMessage(Component.text(made == null ? "Could not create the world." : "Created " + made.getName() + ".", made == null ? NamedTextColor.RED : NamedTextColor.GREEN));
            }
            case "tp" -> {
                if (!(sender instanceof Player p) || w == null) { sender.sendMessage(Component.text("Players only, existing world.", NamedTextColor.RED)); return true; }
                p.teleportAsync(w.getSpawnLocation());
            }
            case "unload" -> {
                if (w == null || w.equals(getServer().getWorlds().get(0))) { sender.sendMessage(Component.text("Cannot unload that world.", NamedTextColor.RED)); return true; }
                w.getPlayers().forEach(p -> p.teleport(getServer().getWorlds().get(0).getSpawnLocation()));
                sender.sendMessage(Component.text(getServer().unloadWorld(w, true) ? "Unloaded." : "Unload refused.", NamedTextColor.YELLOW));
            }
            default -> sender.sendMessage(Component.text("/mw list|create|tp|unload", NamedTextColor.GRAY));
        }
        return true;
    }
}
