package dev.nxeon.golden.bossbar;

import java.time.Duration;
import java.util.HashSet;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.bossbar.BossBar;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.title.Title;
import org.bukkit.Bukkit;
import org.bukkit.NamespacedKey;
import org.bukkit.boss.BarColor;
import org.bukkit.boss.BarStyle;
import org.bukkit.boss.KeyedBossBar;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * Golden boss bars + titles: /countdown <seconds> <text> shows an Adventure boss bar to everyone (own viewer set,
 * clamped progress), a title at the end and an action bar each second. A keyed Bukkit boss bar (org.bukkit.boss) is
 * shown for comparison: it persists across reloads and must be removed with Bukkit.removeBossBar(key).
 */
public class BossBars extends JavaPlugin {
    private BossBar bar;
    private final Set<UUID> viewers = new HashSet<>();
    private BukkitTask task;
    private NamespacedKey legacyKey;

    @Override
    public void onEnable() {
        getCommand("countdown").setExecutor(this);
        legacyKey = new NamespacedKey(this, "info");
        KeyedBossBar legacy = Bukkit.getBossBar(legacyKey);
        if (legacy == null) legacy = Bukkit.createBossBar(legacyKey, "Server info", BarColor.BLUE, BarStyle.SEGMENTED_10);
        legacy.setVisible(false);
    }

    @Override
    public void onDisable() {
        hideAll();
        Bukkit.removeBossBar(legacyKey);
    }

    private void hideAll() {
        if (bar == null) return;
        for (UUID id : viewers) { Player p = Bukkit.getPlayer(id); if (p != null) p.hideBossBar(bar); }
        viewers.clear();
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        int secs;
        try { secs = Math.max(1, Math.min(3600, Integer.parseInt(args.length > 0 ? args[0] : "10"))); } catch (NumberFormatException e) { return false; }
        Component text = MiniMessage.miniMessage().deserialize(args.length > 1 ? String.join(" ", java.util.Arrays.copyOfRange(args, 1, args.length)) : "<red>Event starts");
        if (task != null) task.cancel();
        hideAll();
        bar = BossBar.bossBar(text, 1f, BossBar.Color.RED, BossBar.Overlay.NOTCHED_10);
        final int total = secs;
        final int[] left = {secs};
        task = getServer().getScheduler().runTaskTimer(this, () -> {
            for (Player p : getServer().getOnlinePlayers()) if (viewers.add(p.getUniqueId())) p.showBossBar(bar);
            bar.progress(Math.max(0f, Math.min(1f, left[0] / (float) total)));
            getServer().getOnlinePlayers().forEach(p -> p.sendActionBar(Component.text(left[0] + " s", NamedTextColor.YELLOW)));
            if (left[0]-- <= 0) {
                getServer().getOnlinePlayers().forEach(p -> p.showTitle(Title.title(text, Component.empty(), Title.Times.times(Duration.ofMillis(200), Duration.ofSeconds(2), Duration.ofMillis(500)))));
                hideAll();
                task.cancel();
            }
        }, 0L, 20L);
        sender.sendMessage(Component.text("Countdown of " + secs + " s started.", NamedTextColor.GREEN));
        return true;
    }
}
''', yml("GoldenBossBars", "dev.nxeon.golden.bossbar.BossBars", "Golden reference - boss bars and titles",
