package dev.nxeon.golden.daily;

import java.io.File;
import java.io.IOException;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden daily reward + login streak, in the configured time zone; rewards grow with the streak (capped). */
public class Daily extends JavaPlugin {
    private File file;
    private YamlConfiguration data;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "streaks.yml");
        data = YamlConfiguration.loadConfiguration(file);
        getCommand("daily").setExecutor(this);
    }

    @Override
    public void onDisable() { save(); }
    private void save() { try { data.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); } }

    private LocalDate today() {
        ZoneId zone;
        try { zone = ZoneId.of(getConfig().getString("time-zone", "UTC")); } catch (RuntimeException e) { zone = ZoneId.of("UTC"); }
        return LocalDate.now(zone);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenDaily: day " + today() + " (" + getConfig().getString("time-zone", "UTC") + ").", NamedTextColor.GRAY)); return true; }
        String id = p.getUniqueId().toString();
        LocalDate last = data.contains(id + ".last") ? LocalDate.parse(data.getString(id + ".last")) : null;
        LocalDate now = today();
        if (now.equals(last)) { p.sendMessage(Component.text("Come back tomorrow.", NamedTextColor.RED)); return true; }
        int streak = last != null && last.plusDays(1).equals(now) ? data.getInt(id + ".streak") + 1 : 1;
        data.set(id + ".last", now.toString());
        data.set(id + ".streak", streak);
        save();
        List<String> rewards = getConfig().getStringList("rewards");
        String reward = rewards.get(Math.min(streak, rewards.size()) - 1);
        String[] parts = reward.split(":");
        Material m = Material.matchMaterial(parts[0]);
        if (m != null) p.getInventory().addItem(new ItemStack(m, parts.length > 1 ? Integer.parseInt(parts[1]) : 1)).values().forEach(l -> p.getWorld().dropItemNaturally(p.getLocation(), l));
        p.sendMessage(Component.text("Day " + streak + " reward: " + reward, NamedTextColor.GOLD));
        return true;
    }
}
