package dev.nxeon.golden.sidebar;

import io.papermc.paper.scoreboard.numbers.NumberFormat;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.minimessage.MiniMessage;
import net.kyori.adventure.text.minimessage.tag.resolver.Placeholder;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.scoreboard.Criteria;
import org.bukkit.scoreboard.DisplaySlot;
import org.bukkit.scoreboard.Objective;
import org.bukkit.scoreboard.Scoreboard;
import org.bukkit.scoreboard.Team;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden sidebar: one scoreboard per player, created once; lines are teams with an invisible unique entry whose
 * prefix is updated (no flicker, no recreation every tick); numbers hidden with NumberFormat.blank().
 */
public class Sidebar extends JavaPlugin implements Listener {
    private final Map<UUID, Scoreboard> boards = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getServer().getPluginManager().registerEvents(this, this);
        getCommand("sidebar").setExecutor(this);
        getServer().getOnlinePlayers().forEach(this::create);
        getServer().getScheduler().runTaskTimer(this, () -> getServer().getOnlinePlayers().forEach(this::update), 20L, Math.max(10, getConfig().getLong("update-ticks", 20)));
    }

    private void create(Player p) {
        if (p.getScoreboard() != getServer().getScoreboardManager().getMainScoreboard() && !boards.containsKey(p.getUniqueId())) return; // another plugin owns this player's sidebar
        Scoreboard sb = getServer().getScoreboardManager().getNewScoreboard();
        Objective o = sb.registerNewObjective("golden_side", Criteria.DUMMY, MiniMessage.miniMessage().deserialize(getConfig().getString("title", "<gold>Server</gold>")));
        o.setDisplaySlot(DisplaySlot.SIDEBAR);
        o.numberFormat(NumberFormat.blank());
        List<String> lines = getConfig().getStringList("lines");
        for (int i = 0; i < lines.size() && i < 15; i++) {
            String entry = "\u00a7" + Integer.toHexString(i) + "\u00a7r";
            Team t = sb.registerNewTeam("line" + i);
            t.addEntry(entry);
            o.getScore(entry).setScore(lines.size() - i);
        }
        boards.put(p.getUniqueId(), sb);
        p.setScoreboard(sb);
        update(p);
    }

    private void update(Player p) {
        Scoreboard sb = boards.get(p.getUniqueId());
        if (sb == null) return;
        List<String> lines = getConfig().getStringList("lines");
        for (int i = 0; i < lines.size() && i < 15; i++) {
            Team t = sb.getTeam("line" + i);
            if (t != null) t.prefix(MiniMessage.miniMessage().deserialize(lines.get(i), Placeholder.unparsed("player", p.getName()), Placeholder.unparsed("online", String.valueOf(getServer().getOnlinePlayers().size())), Placeholder.unparsed("level", String.valueOf(p.getLevel()))));
        }
    }

    @EventHandler public void onJoin(PlayerJoinEvent e) { create(e.getPlayer()); }
    @EventHandler public void onQuit(PlayerQuitEvent e) { boards.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        reloadConfig();
        boards.clear();
        getServer().getOnlinePlayers().forEach(p -> { p.setScoreboard(getServer().getScoreboardManager().getMainScoreboard()); create(p); });
        sender.sendMessage(Component.text("GoldenSidebar reloaded: " + getConfig().getStringList("lines").size() + " lines.", NamedTextColor.GREEN));
        return true;
    }
}
