/**
 * Golden custom weapon "Storm Blade": identified by a PDC key (never by name); on hit it may strike lightning
 * (effect only, no fire, no self damage); pressing the swap-hands key (F) while holding it dashes forward with a
 * per-player cooldown. The swap is cancelled so the item stays in the main hand.
 */
public class Weapon extends JavaPlugin implements Listener {
    private NamespacedKey key;
    private final Map<UUID, Long> cooldown = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        key = new NamespacedKey(this, "storm_blade");
        getCommand("stormblade").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    ItemStack create() {
        ItemStack it = new ItemStack(Material.DIAMOND_SWORD);
        it.editMeta(m -> {
            m.displayName(Component.text("Storm Blade", NamedTextColor.AQUA).decoration(TextDecoration.ITALIC, false));
            m.lore(List.of(Component.text("Press F to dash", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false)));
            m.getPersistentDataContainer().set(key, PersistentDataType.BOOLEAN, true);
            m.setEnchantmentGlintOverride(true);
        });
        return it;
    }

    boolean isBlade(ItemStack it) { return it != null && it.hasItemMeta() && it.getItemMeta().getPersistentDataContainer().has(key, PersistentDataType.BOOLEAN); }

    @EventHandler(ignoreCancelled = true)
