        Player p = e.getPlayer();
        if (!isBlade(p.getInventory().getItemInMainHand())) return;
        e.setCancelled(true);
        long now = System.currentTimeMillis(), ready = cooldown.getOrDefault(p.getUniqueId(), 0L);
        if (now < ready) { p.sendActionBar(Component.text("Dash ready in " + ((ready - now) / 1000 + 1) + " s", NamedTextColor.RED)); return; }
