import org.bukkit.potion.PotionEffectType;

/**
 * Golden armor set "Ember": four dyed leather pieces tagged with a PDC key; wearing all four gives a keyed max-health
 * modifier (removed by key before re-adding) and fire resistance. Uses Paper's PlayerArmorChangeEvent (all 1.21.x).
 */
public class ArmorSet extends JavaPlugin implements Listener {
    private NamespacedKey tag, bonus;
    private static final Material[] PIECES = {Material.LEATHER_HELMET, Material.LEATHER_CHESTPLATE, Material.LEATHER_LEGGINGS, Material.LEATHER_BOOTS};

    @Override
    public void onEnable() {
        saveDefaultConfig();
        tag = new NamespacedKey(this, "ember");
        bonus = new NamespacedKey(this, "ember_bonus");
        getCommand("emberset").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    static Attribute maxHealth() {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft("max_health"));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic.max_health"));
    }

    ItemStack piece(Material m) {
        ItemStack it = new ItemStack(m);
        it.editMeta(LeatherArmorMeta.class, meta -> {
            meta.setColor(Color.fromRGB(getConfig().getInt("color", 0xD2501E)));
            meta.displayName(Component.text("Ember " + m.getKey().getKey().replace("leather_", ""), NamedTextColor.GOLD).decoration(TextDecoration.ITALIC, false));
            meta.lore(List.of(Component.text("Full set: +" + getConfig().getInt("bonus-health", 8) + " health, fire resistance", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false)));
            meta.getPersistentDataContainer().set(tag, PersistentDataType.BOOLEAN, true);
        });
        return it;
    }

    boolean wearsSet(Player p) {
        for (ItemStack it : p.getInventory().getArmorContents()) if (it == null || !it.hasItemMeta() || !it.getItemMeta().getPersistentDataContainer().has(tag, PersistentDataType.BOOLEAN)) return false;
        return true;
    }

    void refresh(Player p) {
        AttributeInstance hp = p.getAttribute(maxHealth());
        if (hp == null) return;
        hp.removeModifier(bonus);
        if (wearsSet(p)) {
            hp.addModifier(new AttributeModifier(bonus, getConfig().getInt("bonus-health", 8), AttributeModifier.Operation.ADD_NUMBER));
            p.addPotionEffect(new PotionEffect(PotionEffectType.FIRE_RESISTANCE, PotionEffect.INFINITE_DURATION, 0, true, false, true));
