            PotionEffect fr = p.getPotionEffect(PotionEffectType.FIRE_RESISTANCE);
            if (fr != null && fr.isInfinite()) p.removePotionEffect(PotionEffectType.FIRE_RESISTANCE);
            if (p.getHealth() > hp.getValue()) p.setHealth(hp.getValue());
        }
    }

