/**
 * Golden plugin-side custom enchantment "Lifesteal I-III": the level lives in the item's PDC, the tooltip line is
 * lore. (A data pack enchantment is the other lane: real anvil/table support but only vanilla effect components.)
 */
public class Enchants extends JavaPlugin implements Listener {
    private NamespacedKey key;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        key = new NamespacedKey(this, "lifesteal");
        getCommand("lifesteal").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    int level(ItemStack it) { return it == null || !it.hasItemMeta() ? 0 : it.getItemMeta().getPersistentDataContainer().getOrDefault(key, PersistentDataType.INTEGER, 0); }

    void apply(ItemStack it, int lvl) {
        ItemMeta m = it.getItemMeta();
        m.getPersistentDataContainer().set(key, PersistentDataType.INTEGER, lvl);
        List<Component> lore = new ArrayList<>(m.hasLore() ? m.lore() : List.of());
        lore.removeIf(c -> c.toString().contains("Lifesteal"));
        lore.add(0, Component.text("Lifesteal " + "I".repeat(lvl), NamedTextColor.RED).decoration(TextDecoration.ITALIC, false));
        m.lore(lore);
        it.setItemMeta(m);
    }

    @EventHandler(ignoreCancelled = true)
    public void onHit(EntityDamageByEntityEvent e) {
        if (!(e.getDamager() instanceof Player p)) return;
        int lvl = level(p.getInventory().getItemInMainHand());
        if (lvl <= 0) return;
        double heal = e.getFinalDamage() * getConfig().getDouble("heal-fraction-per-level", 0.1) * lvl;
        p.heal(Math.min(heal, getConfig().getDouble("max-heal-per-hit", 3)));
