 * amethyst shard (Paper PotionMix, removed on disable so a reload never duplicates it).
 */
public class Brew extends JavaPlugin {
    private NamespacedKey mixKey;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        mixKey = new NamespacedKey(this, "miners_brew");
        ItemStack awkward = new ItemStack(Material.POTION);
        awkward.editMeta(PotionMeta.class, m -> m.setBasePotionType(PotionType.AWKWARD));
