    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Player p = args.length == 1 ? Bukkit.getPlayerExact(args[0]) : sender instanceof Player s ? s : null;
        PotionMeta m = (PotionMeta) brew().getItemMeta();
        if (p == null) { sender.sendMessage(Component.text("Miner's Brew: " + m.getCustomEffects().size() + " effects, mix registered.", NamedTextColor.YELLOW)); return true; }
        p.getInventory().addItem(brew());
        return true;
    }
}
