import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden extra drops: per mob type (only when killed by a player, never for players) and per mined block. */
public class Drops extends JavaPlugin implements Listener {
    private final Random random = new Random();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("drops").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private void roll(ConfigurationSection s, java.util.function.Consumer<ItemStack> out) {
        if (s == null) return;
        for (Map<?, ?> m : s.getMapList("drops")) {
            Material mat = Material.matchMaterial(String.valueOf(m.get("item")));
            double chance = m.get("chance") instanceof Number n ? n.doubleValue() : 1.0;
            if (mat != null && random.nextDouble() < chance) out.accept(new ItemStack(mat, m.get("amount") instanceof Number a ? a.intValue() : 1));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onDeath(EntityDeathEvent e) {
        if (e.getEntity() instanceof Player || e.getEntity().getKiller() == null) return;
        roll(getConfig().getConfigurationSection("mobs." + e.getEntityType().getKey().getKey()), e.getDrops()::add);
    }

    @EventHandler(ignoreCancelled = true)
    public void onBlock(BlockDropItemEvent e) {
        roll(getConfig().getConfigurationSection("blocks." + e.getBlockState().getType().getKey().getKey()), it -> e.getBlock().getWorld().dropItemNaturally(e.getBlock().getLocation(), it));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        reloadConfig();
        ConfigurationSection mobs = getConfig().getConfigurationSection("mobs"), blocks = getConfig().getConfigurationSection("blocks");
        long badMobs = mobs == null ? 0 : mobs.getKeys(false).stream().filter(k -> EntityType.fromName(k) == null).count();
        sender.sendMessage(Component.text("GoldenDrops: " + (mobs == null ? 0 : mobs.getKeys(false).size()) + " mobs, " + (blocks == null ? 0 : blocks.getKeys(false).size()) + " blocks, " + badMobs + " unknown.", NamedTextColor.GREEN));
        return true;
    }
}
