package dev.nxeon.golden.armorset;

import com.destroystokyo.paper.event.player.PlayerArmorChangeEvent;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Color;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.attribute.AttributeModifier;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.LeatherArmorMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/**
 * Golden armor set "Ember": four dyed leather pieces tagged with a PDC key; wearing all four gives a keyed max-health
 * modifier (removed by key before re-adding) and fire resistance. Uses Paper's PlayerArmorChangeEvent (all 1.21.x).
 */
public class ArmorSet extends JavaPlugin implements Listener {
    private NamespacedKey tag, bonus;
    private static final Material[] PIECES = {Material.LEATHER_HELMET, Material.LEATHER_CHESTPLATE, Material.LEATHER_LEGGINGS, Material.LEATHER_BOOTS};

    @Override
    public void onEnable() {
        saveDefaultConfig();
        tag = new NamespacedKey(this, "ember");
        bonus = new NamespacedKey(this, "ember_bonus");
        getCommand("emberset").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    static Attribute maxHealth() {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft("max_health"));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic.max_health"));
    }

    ItemStack piece(Material m) {
        ItemStack it = new ItemStack(m);
        it.editMeta(LeatherArmorMeta.class, meta -> {
            meta.setColor(Color.fromRGB(getConfig().getInt("color", 0xD2501E)));
            meta.displayName(Component.text("Ember " + m.getKey().getKey().replace("leather_", ""), NamedTextColor.GOLD).decoration(TextDecoration.ITALIC, false));
            meta.lore(List.of(Component.text("Full set: +" + getConfig().getInt("bonus-health", 8) + " health, fire resistance", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false)));
            meta.getPersistentDataContainer().set(tag, PersistentDataType.BOOLEAN, true);
        });
        return it;
    }

    boolean wearsSet(Player p) {
        for (ItemStack it : p.getInventory().getArmorContents()) if (it == null || !it.hasItemMeta() || !it.getItemMeta().getPersistentDataContainer().has(tag, PersistentDataType.BOOLEAN)) return false;
        return true;
    }

    void refresh(Player p) {
        AttributeInstance hp = p.getAttribute(maxHealth());
        if (hp == null) return;
        hp.removeModifier(bonus);
        if (wearsSet(p)) {
            hp.addModifier(new AttributeModifier(bonus, getConfig().getInt("bonus-health", 8), AttributeModifier.Operation.ADD_NUMBER));
            p.addPotionEffect(new PotionEffect(PotionEffectType.FIRE_RESISTANCE, PotionEffect.INFINITE_DURATION, 0, true, false, true));
        } else {
            PotionEffect fr = p.getPotionEffect(PotionEffectType.FIRE_RESISTANCE);
            if (fr != null && fr.isInfinite()) p.removePotionEffect(PotionEffectType.FIRE_RESISTANCE);
            if (p.getHealth() > hp.getValue()) p.setHealth(hp.getValue());
        }
    }

    // The event fires before the change is visible in the inventory: re-check one tick later.
    @EventHandler public void onArmor(PlayerArmorChangeEvent e) { getServer().getScheduler().runTask(this, () -> refresh(e.getPlayer())); }
    @EventHandler public void onJoin(PlayerJoinEvent e) { refresh(e.getPlayer()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Player p = args.length == 1 ? Bukkit.getPlayerExact(args[0]) : sender instanceof Player s ? s : null;
        if (p == null) { sender.sendMessage(Component.text("Ember set: " + PIECES.length + " pieces, max health attribute " + (maxHealth() != null ? "ok" : "missing") + ".", NamedTextColor.YELLOW)); return true; }
        for (Material m : PIECES) p.getInventory().addItem(piece(m));
        sender.sendMessage(Component.text("Gave the Ember set.", NamedTextColor.GREEN));
        return true;
    }
}
