/**
 * Golden bows/projectiles: a full-force shot (EntityShootBowEvent) marks the arrow with Bukkit metadata (in memory,
 * gone after a restart: fine for a flying arrow; use PDC for anything that must persist), gives it a particle trail
 * from ProjectileLaunchEvent, and on hit it explodes softly (no block damage).
 */
public class Bows extends JavaPlugin implements Listener {
    private static final String META = "golden_power_shot";

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("bows").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler(ignoreCancelled = true)
    public void onShoot(EntityShootBowEvent e) {
        if (e.getEntity() instanceof Player && e.getForce() >= 0.99f && e.getProjectile() instanceof AbstractArrow a) a.setMetadata(META, new FixedMetadataValue(this, true));
