package dev.nxeon.golden.integration;

import java.util.Collection;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.server.PluginDisableEvent;
import org.bukkit.event.server.PluginEnableEvent;
import org.bukkit.event.server.ServerLoadEvent;
import org.bukkit.plugin.Plugin;
import org.bukkit.plugin.RegisteredServiceProvider;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden soft integration: reacts when another plugin enables/disables (PluginEnableEvent/PluginDisableEvent), waits for
 * ServerLoadEvent before looking things up, and lists services offered through the ServicesManager (how one Cyrus mod
 * offers an API to another without reflection).
 */
public class Integration extends JavaPlugin implements Listener {
    private volatile boolean serverLoaded;

    @Override
    public void onEnable() {
        getCommand("integrations").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler public void onLoad(ServerLoadEvent e) { serverLoaded = true; getLogger().info("Server load finished (" + e.getType() + ")"); }
    @EventHandler public void onEnablePlugin(PluginEnableEvent e) { if (e.getPlugin() != this) getLogger().fine("enabled " + e.getPlugin().getName()); }
    @EventHandler public void onDisablePlugin(PluginDisableEvent e) { if (e.getPlugin() != this) getLogger().fine("disabled " + e.getPlugin().getName()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        Collection<Class<?>> services = getServer().getServicesManager().getKnownServices();
        StringBuilder sb = new StringBuilder("Integrations: loaded=" + serverLoaded + ", services=" + services.size());
        for (Class<?> c : services) {
            RegisteredServiceProvider<?> r = getServer().getServicesManager().getRegistration(c);
            Plugin owner = r == null ? null : r.getPlugin();
            sb.append(" | ").append(c.getSimpleName()).append(" by ").append(owner == null ? "?" : owner.getName());
        }
        sender.sendMessage(Component.text(sb.toString(), NamedTextColor.AQUA));
        return true;
    }
}
