/**
 * Golden player heads: /head <name> gives a head (SkullMeta.setOwningPlayer with a CACHED OfflinePlayer; an unknown name
 * would need a blocking web lookup, so it is refused), and players drop their head on a PvP death (configurable chance).
 */
public class Heads extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("head").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

