        ItemStack it = new ItemStack(Material.PLAYER_HEAD);
        it.editMeta(SkullMeta.class, m -> {
            m.setOwningPlayer(owner);
            m.displayName(Component.text((owner.getName() == null ? "Unknown" : owner.getName()) + "'s Head", NamedTextColor.YELLOW).decoration(TextDecoration.ITALIC, false));
            m.lore(List.of(Component.text("A trophy", NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false)));
        });
        return it;
    }

    @EventHandler
    public void onDeath(PlayerDeathEvent e) {
        Player killer = e.getPlayer().getKiller();
        if (killer != null && killer != e.getPlayer() && Math.random() < getConfig().getDouble("pvp-drop-chance", 0.25)) e.getDrops().add(head(e.getPlayer()));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length != 1) return false;
        OfflinePlayer owner = Bukkit.getOfflinePlayerIfCached(args[0]);
        if (owner == null) { sender.sendMessage(Component.text("No cached player " + args[0] + " (they must have joined this server).", NamedTextColor.RED)); return true; }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        p.getInventory().addItem(head(owner));
        return true;
    }
}
