package dev.nxeon.golden.arena;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.GameMode;
import org.bukkit.Location;
import org.bukkit.block.Block;
import org.bukkit.block.data.BlockData;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * Golden minigame (spleef): /spleef join|leave|status queues players; at min players a countdown starts; during the game
 * broken blocks are recorded and restored afterwards; the last player standing wins; inventories are saved and given
 * back. One state machine driven by one repeating task.
 */
public class Arena extends JavaPlugin implements Listener {
    enum State { WAITING, COUNTDOWN, RUNNING }
    private State state = State.WAITING;
    private final Set<UUID> queue = new LinkedHashSet<>(), alive = new LinkedHashSet<>();
    private final Map<UUID, ItemStack[]> saved = new HashMap<>();
    private final Map<Location, BlockData> broken = new HashMap<>();
    private int countdown;
    private BukkitTask loop;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("spleef").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        loop = getServer().getScheduler().runTaskTimer(this, this::tick, 20L, 20L);
    }

    @Override
    public void onDisable() { end(null); }

    private void tick() {
        int min = getConfig().getInt("min-players", 2);
        if (state == State.WAITING && queue.size() >= min) { state = State.COUNTDOWN; countdown = getConfig().getInt("countdown-seconds", 10); }
        if (state == State.COUNTDOWN) {
            if (queue.size() < min) { state = State.WAITING; return; }
            queue.forEach(id -> { Player p = getServer().getPlayer(id); if (p != null) p.sendActionBar(Component.text("Spleef starts in " + countdown, NamedTextColor.YELLOW)); });
            if (countdown-- <= 0) start();
        }
        if (state == State.RUNNING && alive.size() <= 1) end(alive.isEmpty() ? null : getServer().getPlayer(alive.iterator().next()));
    }

    private void start() {
        state = State.RUNNING;
        Location spawn = getConfig().getLocation("arena-spawn", getServer().getWorlds().get(0).getSpawnLocation());
        for (UUID id : new ArrayList<>(queue)) {
            Player p = getServer().getPlayer(id);
            if (p == null) continue;
            saved.put(id, p.getInventory().getContents());
            p.getInventory().clear();
            p.getInventory().addItem(new ItemStack(org.bukkit.Material.DIAMOND_SHOVEL));
            p.setGameMode(GameMode.SURVIVAL);
            p.teleport(spawn);
            alive.add(id);
        }
        queue.clear();
    }

    private void end(Player winner) {
        if (state != State.RUNNING) { state = State.WAITING; return; }
        broken.forEach((loc, data) -> loc.getBlock().setBlockData(data, false));
        broken.clear();
        for (Map.Entry<UUID, ItemStack[]> e : saved.entrySet()) { Player p = getServer().getPlayer(e.getKey()); if (p != null) p.getInventory().setContents(e.getValue()); }
        saved.clear();
        alive.clear();
        state = State.WAITING;
        getServer().broadcast(Component.text(winner == null ? "Spleef ended with no winner." : winner.getName() + " won spleef!", NamedTextColor.GOLD));
    }

    @EventHandler(ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        if (state != State.RUNNING || !alive.contains(e.getPlayer().getUniqueId())) return;
        Block b = e.getBlock();
        if (!getConfig().getStringList("breakable").contains(b.getType().getKey().getKey())) { e.setCancelled(true); return; }
        broken.putIfAbsent(b.getLocation(), b.getBlockData());
        e.setDropItems(false);
    }

    @EventHandler public void onDeath(PlayerDeathEvent e) { if (alive.remove(e.getPlayer().getUniqueId())) { e.getDrops().clear(); e.setKeepInventory(true); } }
    @EventHandler public void onQuit(PlayerQuitEvent e) { queue.remove(e.getPlayer().getUniqueId()); alive.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0].toLowerCase() : "status";
        if (sub.equals("status") || !(sender instanceof Player p)) { sender.sendMessage(Component.text("Spleef: " + state.name().toLowerCase() + ", " + queue.size() + " queued, " + alive.size() + " playing.", NamedTextColor.AQUA)); return true; }
        if (sub.equals("join") && state != State.RUNNING) { queue.add(p.getUniqueId()); p.sendMessage(Component.text("Joined the queue (" + queue.size() + ").", NamedTextColor.GREEN)); }
        else if (sub.equals("leave")) { queue.remove(p.getUniqueId()); p.sendMessage(Component.text("Left the queue.", NamedTextColor.YELLOW)); }
        else p.sendMessage(Component.text("A game is running, wait for the next one.", NamedTextColor.RED));
        return true;
    }
}
''', yml("GoldenArena", "dev.nxeon.golden.arena.Arena", "Golden reference - minigame arena with queue",
 {"spleef": ("Join, leave or check spleef", "/spleef <join|leave|status>", "goldenarena.play")}, {"goldenarena.play": ("Play spleef", "true")}),
