import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/**
 * Golden mining skill: XP per ore from config (placed-then-broken ores give nothing), levels at level*level*100 XP,
 * a Haste perk every 10 levels; progress shown in the action bar; saved per player.
 */
public class Skills extends JavaPlugin implements Listener {
    private final Set<Location> placed = ConcurrentHashMap.newKeySet();
    private File file;
    private YamlConfiguration data;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "skills.yml");
        data = YamlConfiguration.loadConfiguration(file);
        getCommand("skills").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::save, 6000L, 6000L);
    }

    @Override
    public void onDisable() { save(); }
    private void save() { try { data.save(file); } catch (IOException e) { getLogger().warning(e.getMessage()); } }

    static int levelFor(long xp) { int l = 0; while ((long) (l + 1) * (l + 1) * 100 <= xp) l++; return l; }

    @EventHandler(ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) { if (getConfig().isInt("xp." + e.getBlock().getType().getKey().getKey())) placed.add(e.getBlock().getLocation()); }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Material m = e.getBlock().getType();
        int gain = getConfig().getInt("xp." + m.getKey().getKey(), 0);
        if (gain <= 0 || placed.remove(e.getBlock().getLocation())) return;
        Player p = e.getPlayer();
        String path = p.getUniqueId() + ".mining";
        long before = data.getLong(path), after = before + gain;
        data.set(path, after);
        int lb = levelFor(before), la = levelFor(after);
        p.sendActionBar(Component.text("Mining +" + gain + " XP (level " + la + ")", NamedTextColor.AQUA));
        if (la > lb) {
            p.sendMessage(Component.text("Mining level " + la + "!", NamedTextColor.GOLD));
            if (la % 10 == 0) p.addPotionEffect(new PotionEffect(PotionEffectType.HASTE, 20 * 60, la / 10 - 1));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenSkills: level 3 needs " + 9 * 100 + " XP; level for 1000 XP = " + levelFor(1000) + ".", NamedTextColor.GRAY)); return true; }
        long xp = data.getLong(p.getUniqueId() + ".mining");
        p.sendMessage(Component.text("Mining: level " + levelFor(xp) + " (" + xp + " XP)", NamedTextColor.AQUA));
        return true;
    }
}
