/**
 * Golden particle trails: /trail <flame|hearts|dust|off>. DUST needs Particle.DustOptions (spawning it without data
 * throws at runtime); particles are only sent while the player moves, capped per tick.
 */
public class Trails extends JavaPlugin implements Listener {
    private final Map<UUID, String> trails = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        getCommand("trail").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::draw, 2L, 2L);
    }

    static void spawn(Player p, String kind) {
        var at = p.getLocation().add(0, 0.1, 0);
        switch (kind) {
            case "flame" -> p.getWorld().spawnParticle(Particle.FLAME, at, 3, 0.15, 0, 0.15, 0.01);
            case "hearts" -> p.getWorld().spawnParticle(Particle.HEART, at.add(0, 2, 0), 1, 0.3, 0.1, 0.3, 0);
            case "dust" -> p.getWorld().spawnParticle(Particle.DUST, at, 4, 0.2, 0.05, 0.2, 0, new Particle.DustOptions(Color.AQUA, 1.2f));
            default -> {}
        }
    }

    private void draw() {
        int budget = 60;
        for (Map.Entry<UUID, String> e : trails.entrySet()) {
            Player p = getServer().getPlayer(e.getKey());
            if (p == null || p.getVelocity().lengthSquared() < 0.01 && p.isOnGround()) continue;
            if (budget-- <= 0) break;
            spawn(p, e.getValue());
        }
    }

    @EventHandler public void onQuit(PlayerQuitEvent e) { trails.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String kind = args.length == 1 ? args[0].toLowerCase() : "";
        if (!java.util.List.of("flame", "hearts", "dust", "off").contains(kind)) { sender.sendMessage(Component.text("Trails: flame, hearts, dust, off", NamedTextColor.GRAY)); return true; }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        if (kind.equals("off")) trails.remove(p.getUniqueId()); else trails.put(p.getUniqueId(), kind);
        p.sendMessage(Component.text("Trail: " + kind, NamedTextColor.AQUA));
        return true;
    }
}
