/**
 * Golden pets: /pet spawns a fox that follows its owner (Paper Pathfinder moveTo; teleports when far), never targets,
 * takes no damage, is not saved with the chunk (setPersistent(false)) and is removed when the owner leaves.
 */
public class Pets extends JavaPlugin implements Listener {
    private final Map<UUID, Mob> pets = new ConcurrentHashMap<>();
    private NamespacedKey tag;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        tag = new NamespacedKey(this, "pet");
        getCommand("pet").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::follow, 10L, 10L);
    }

    @Override
    public void onDisable() { pets.values().forEach(Mob::remove); pets.clear(); }

    private void follow() {
        pets.forEach((owner, mob) -> {
            Player p = getServer().getPlayer(owner);
            if (p == null || !mob.isValid()) return;
            if (p.getWorld() != mob.getWorld() || p.getLocation().distanceSquared(mob.getLocation()) > 400) { mob.teleport(p.getLocation()); return; }
            Pathfinder pf = mob.getPathfinder();
            if (p.getLocation().distanceSquared(mob.getLocation()) > 9) pf.moveTo(p.getLocation(), getConfig().getDouble("speed", 1.2)); else pf.stopPathfinding();
        });
    }

    @EventHandler public void onTarget(EntityTargetEvent e) { if (e.getEntity().getPersistentDataContainer().has(tag, PersistentDataType.STRING)) e.setCancelled(true); }
    @EventHandler public void onDamage(EntityDamageEvent e) { if (e.getEntity().getPersistentDataContainer().has(tag, PersistentDataType.STRING)) e.setCancelled(true); }
    @EventHandler public void onQuit(PlayerQuitEvent e) { Mob m = pets.remove(e.getPlayer().getUniqueId()); if (m != null) m.remove(); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenPets: " + pets.size() + " pets out.", NamedTextColor.GRAY)); return true; }
        Mob old = pets.remove(p.getUniqueId());
        if (old != null) { old.remove(); p.sendMessage(Component.text("Pet sent home.", NamedTextColor.YELLOW)); return true; }
        Fox fox = p.getWorld().spawn(p.getLocation(), Fox.class, f -> {
            f.customName(Component.text(p.getName() + "'s fox", NamedTextColor.GOLD));
            f.setPersistent(false);
            f.getPersistentDataContainer().set(tag, PersistentDataType.STRING, p.getUniqueId().toString());
        });
        pets.put(p.getUniqueId(), fox);
        return true;
    }
}
