/**
 * Golden steerable mount (1.21.4+ only: PlayerInputEvent / Player.getCurrentInput do not exist on 1.21.1): /mount
 * spawns a tagged strider; while ridden, the rider's forward/back/jump keys push it along the look direction.
 */
public class Mounts extends JavaPlugin implements Listener {
    private NamespacedKey tag;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        tag = new NamespacedKey(this, "mount");
        getCommand("mount").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::drive, 1L, 1L);
    }

