        for (Player p : getServer().getOnlinePlayers()) {
            Entity v = p.getVehicle();
            if (v == null || !v.getPersistentDataContainer().has(tag, PersistentDataType.BOOLEAN)) continue;
            Input in = p.getCurrentInput();
            double speed = getConfig().getDouble("speed", 0.35);
