import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden parkour: a light weighted plate starts the run, iron plates are checkpoints, a gold block under the feet
 * finishes; falling below the course returns to the checkpoint; best times saved. PHYSICAL interact is debounced.
 */
public class Parkour extends JavaPlugin implements Listener {
    record Run(long start, Location checkpoint) {}
    private final Map<UUID, Run> runs = new ConcurrentHashMap<>();
    private File file;
    private YamlConfiguration best;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        file = new File(getDataFolder(), "best.yml");
        best = YamlConfiguration.loadConfiguration(file);
        getCommand("parkour").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler
    public void onPlate(PlayerInteractEvent e) {
        if (e.getAction() != Action.PHYSICAL || e.getClickedBlock() == null) return;
        Player p = e.getPlayer();
        Material m = e.getClickedBlock().getType();
        Run r = runs.get(p.getUniqueId());
        if (m == Material.LIGHT_WEIGHTED_PRESSURE_PLATE && (r == null || System.currentTimeMillis() - r.start() > 2000)) {
            runs.put(p.getUniqueId(), new Run(System.currentTimeMillis(), e.getClickedBlock().getLocation().add(0.5, 0, 0.5)));
            p.sendActionBar(Component.text("Run started!", NamedTextColor.GREEN));
        } else if (m == Material.HEAVY_WEIGHTED_PRESSURE_PLATE && r != null && !r.checkpoint().getBlock().equals(e.getClickedBlock())) {
            runs.put(p.getUniqueId(), new Run(r.start(), e.getClickedBlock().getLocation().add(0.5, 0, 0.5)));
            p.sendActionBar(Component.text("Checkpoint!", NamedTextColor.AQUA));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock()) return;
        Run r = runs.get(e.getPlayer().getUniqueId());
        if (r == null) return;
        Block under = e.getTo().getBlock().getRelative(org.bukkit.block.BlockFace.DOWN);
        if (under.getType() == Material.GOLD_BLOCK) finish(e.getPlayer(), r);
        else if (e.getTo().getY() < r.checkpoint().getY() - getConfig().getInt("fall-distance", 8)) e.getPlayer().teleport(r.checkpoint());
    }

    private void finish(Player p, Run r) {
        runs.remove(p.getUniqueId());
        long ms = System.currentTimeMillis() - r.start();
        long prev = best.getLong(p.getUniqueId().toString(), Long.MAX_VALUE);
        if (ms < prev) { best.set(p.getUniqueId().toString(), ms); try { best.save(file); } catch (IOException ex) { getLogger().warning(ex.getMessage()); } }
        p.sendMessage(Component.text(String.format("Finished in %.2f s%s", ms / 1000.0, ms < prev ? " (new best!)" : ""), NamedTextColor.GOLD));
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenParkour: " + best.getKeys(false).size() + " best times, " + runs.size() + " running.", NamedTextColor.AQUA));
        return true;
    }
}
