        p.sendActionBar(Component.text("Mining +" + gain + " XP (level " + la + ")", NamedTextColor.AQUA));
        if (la > lb) {
            p.sendMessage(Component.text("Mining level " + la + "!", NamedTextColor.GOLD));
            if (la % 10 == 0) p.addPotionEffect(new PotionEffect(PotionEffectType.HASTE, 20 * 60, la / 10 - 1));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenSkills: level 3 needs " + 9 * 100 + " XP; level for 1000 XP = " + levelFor(1000) + ".", NamedTextColor.GRAY)); return true; }
