/**
 * Golden machines (automation): an item-sorting hopper. A hopper with an item frame-free design: if the block BELOW a
 * hopper is a filter barrel, only items whose type matches the barrel's first slot pass (InventoryMoveItemEvent,
 * which fires a lot: keep it cheap, no world lookups beyond the two holders).
 */
public class Machines extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
