import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden clans + parties: /clan create|invite|join|leave|chat|list (saved in config), no friendly fire (projectiles
 * included). Pending invites are in memory; members are stored by UUID.
 */
public class Clans extends JavaPlugin implements Listener {
    private final Map<UUID, String> invites = new HashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("clan").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    String clanOf(UUID id) {
        ConcurrentLookup:
        {
            ConfigurationSection s = getConfig().getConfigurationSection("clans");
            if (s == null) return null;
            for (String c : s.getKeys(false)) if (s.getStringList(c + ".members").contains(id.toString())) return c;
        }
        return null;
    }

    Set<String> members(String clan) { return new HashSet<>(getConfig().getStringList("clans." + clan + ".members")); }

    @EventHandler(ignoreCancelled = true)
    public void onDamage(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof Player v)) return;
        Player a = e.getDamager() instanceof Player p ? p : e.getDamager() instanceof Projectile pr && pr.getShooter() instanceof Player s ? s : null;
        if (a == null || a == v) return;
        String ca = clanOf(a.getUniqueId());
        if (ca != null && ca.equals(clanOf(v.getUniqueId())) && !getConfig().getBoolean("friendly-fire", false)) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0].toLowerCase() : "list";
        if (sub.equals("list")) {
            ConfigurationSection s = getConfig().getConfigurationSection("clans");
            sender.sendMessage(Component.text("Clans: " + (s == null || s.getKeys(false).isEmpty() ? "none" : String.join(", ", s.getKeys(false))), NamedTextColor.AQUA));
            return true;
        }
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
        String mine = clanOf(p.getUniqueId());
        switch (sub) {
            case "create" -> {
                if (mine != null || args.length != 2 || !args[1].matches("[A-Za-z0-9]{3,12}")) { p.sendMessage(Component.text("Leave your clan first; names 3-12 letters/digits.", NamedTextColor.RED)); return true; }
                getConfig().set("clans." + args[1] + ".members", java.util.List.of(p.getUniqueId().toString()));
                saveConfig();
                p.sendMessage(Component.text("Clan " + args[1] + " created.", NamedTextColor.GREEN));
            }
            case "invite" -> {
                Player t = args.length == 2 ? Bukkit.getPlayerExact(args[1]) : null;
                if (mine == null || t == null) { p.sendMessage(Component.text("You need a clan and an online player.", NamedTextColor.RED)); return true; }
                invites.put(t.getUniqueId(), mine);
                t.sendMessage(Component.text(p.getName() + " invited you to " + mine + ": /clan join", NamedTextColor.GOLD));
            }
            case "join" -> {
                String c = invites.remove(p.getUniqueId());
                if (c == null || mine != null) { p.sendMessage(Component.text("No invite (or already in a clan).", NamedTextColor.RED)); return true; }
                Set<String> m = members(c); m.add(p.getUniqueId().toString());
                getConfig().set("clans." + c + ".members", new java.util.ArrayList<>(m));
                saveConfig();
                p.sendMessage(Component.text("Joined " + c + ".", NamedTextColor.GREEN));
            }
            case "leave" -> {
                if (mine == null) return true;
                Set<String> m = members(mine); m.remove(p.getUniqueId().toString());
                getConfig().set("clans." + mine + (m.isEmpty() ? "" : ".members"), m.isEmpty() ? null : new java.util.ArrayList<>(m));
                saveConfig();
                p.sendMessage(Component.text("Left " + mine + ".", NamedTextColor.YELLOW));
            }
            case "chat" -> {
                if (mine == null || args.length < 2) return true;
                Component line = Component.text("[" + mine + "] " + p.getName() + ": ", NamedTextColor.GREEN).append(Component.text(String.join(" ", java.util.Arrays.copyOfRange(args, 1, args.length)), NamedTextColor.WHITE));
                for (String id : members(mine)) { Player o = Bukkit.getPlayer(UUID.fromString(id)); if (o != null) o.sendMessage(line); }
            }
            default -> p.sendMessage(Component.text("/clan create|invite|join|leave|chat|list", NamedTextColor.GRAY));
        }
        return true;
    }
}
