/**
 * Golden kill quests: /quest start <id> | status. Progress lives in the PLAYER's PDC (persists with the player file);
 * only the killer's own kills count; reward items on completion.
 */
public class Quests extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("quest").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private NamespacedKey k(String s) { return new NamespacedKey(this, s); }

    @EventHandler
    public void onKill(EntityDeathEvent e) {
        Player p = e.getEntity().getKiller();
        if (p == null) return;
        PersistentDataContainer pdc = p.getPersistentDataContainer();
        String q = pdc.get(k("active"), PersistentDataType.STRING);
        if (q == null) return;
        EntityType target = Registry.ENTITY_TYPE.get(NamespacedKey.minecraft(getConfig().getString("quests." + q + ".mob", "zombie")));
        if (e.getEntityType() != target) return;
        int n = pdc.getOrDefault(k("progress"), PersistentDataType.INTEGER, 0) + 1, need = getConfig().getInt("quests." + q + ".count", 10);
        pdc.set(k("progress"), PersistentDataType.INTEGER, n);
        p.sendActionBar(Component.text(q + ": " + n + "/" + need, NamedTextColor.YELLOW));
        if (n >= need) {
            pdc.remove(k("active"));
            pdc.remove(k("progress"));
            Material m = Material.matchMaterial(getConfig().getString("quests." + q + ".reward", "diamond"));
            if (m != null) p.getInventory().addItem(new ItemStack(m, getConfig().getInt("quests." + q + ".reward-amount", 1)));
            p.sendMessage(Component.text("Quest " + q + " complete!", NamedTextColor.GOLD));
        }
    }

