        var qs = getConfig().getConfigurationSection("quests");
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenQuests: " + (qs == null ? 0 : qs.getKeys(false).size()) + " quests.", NamedTextColor.GRAY)); return true; }
        if (args.length == 2 && args[0].equalsIgnoreCase("start") && qs != null && qs.contains(args[1])) {
            p.getPersistentDataContainer().set(k("active"), PersistentDataType.STRING, args[1]);
            p.getPersistentDataContainer().set(k("progress"), PersistentDataType.INTEGER, 0);
            p.sendMessage(Component.text("Quest " + args[1] + " started.", NamedTextColor.GREEN));
            return true;
        }
        String q = p.getPersistentDataContainer().get(k("active"), PersistentDataType.STRING);
        p.sendMessage(Component.text(q == null ? "No active quest." : q + ": " + p.getPersistentDataContainer().getOrDefault(k("progress"), PersistentDataType.INTEGER, 0), NamedTextColor.AQUA));
        return true;
    }
}
