package dev.nxeon.golden.cutscene;

import java.time.Duration;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.title.Title;
import org.bukkit.GameMode;
import org.bukkit.Location;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.ItemDisplay;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden cutscene: the player spectates an invisible ItemDisplay "camera" that is teleported along the configured
 * points with teleport interpolation (setTeleportDuration) and titles per point; the old game mode and location are
 * restored at the end, on quit and (if the server stopped mid-scene) on the next join.
 */
public class Cutscenes extends JavaPlugin implements Listener {
    record Saved(GameMode mode, Location loc) {}
    private final Map<UUID, Saved> saved = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("cutscene").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    void play(Player p) {
        List<Location> pts = (List<Location>) (List<?>) getConfig().getList("points", List.of());
        if (pts.size() < 2) return;
        saved.put(p.getUniqueId(), new Saved(p.getGameMode(), p.getLocation()));
        ItemDisplay cam = pts.get(0).getWorld().spawn(pts.get(0), ItemDisplay.class, d -> { d.setTeleportDuration(getConfig().getInt("step-ticks", 40)); d.setPersistent(false); });
        p.setGameMode(GameMode.SPECTATOR);
        p.setSpectatorTarget(cam);
        int step = getConfig().getInt("step-ticks", 40);
        for (int i = 1; i < pts.size(); i++) {
            Location to = pts.get(i);
            int n = i;
            getServer().getScheduler().runTaskLater(this, () -> {
                cam.teleport(to);
                p.showTitle(Title.title(Component.empty(), Component.text("Scene " + n, NamedTextColor.GRAY), Title.Times.times(Duration.ZERO, Duration.ofSeconds(2), Duration.ofMillis(300))));
            }, (long) step * (i - 1) + 1);
        }
        getServer().getScheduler().runTaskLater(this, () -> { cam.remove(); restore(p); }, (long) step * pts.size());
    }

    void restore(Player p) {
        Saved s = saved.remove(p.getUniqueId());
        if (s == null) return;
        p.setSpectatorTarget(null);
        p.setGameMode(s.mode());
        p.teleport(s.loc());
    }

    @EventHandler public void onQuit(PlayerQuitEvent e) { restore(e.getPlayer()); }
    @EventHandler public void onJoin(PlayerJoinEvent e) { if (e.getPlayer().getGameMode() == GameMode.SPECTATOR && !e.getPlayer().hasPermission("goldencutscene.spectator")) e.getPlayer().setGameMode(GameMode.SURVIVAL); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenCutscenes: " + getConfig().getList("points", List.of()).size() + " points.", NamedTextColor.GRAY)); return true; }
        play(p);
        return true;
    }
}
