import org.bukkit.event.player.PlayerChangedWorldEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden ambience/music: per-world looping track by sound key (a vanilla key or the mod's own "<namespace>:<set>.<event>"
 * from the resource pack), restarted after the configured track length (not a fixed guess); stopped on world change.
 */
public class Ambience extends JavaPlugin implements Listener {
    private final Map<UUID, Long> nextStart = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("ambience").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::tick, 40L, 20L);
    }

    private Sound track(String world) {
        String key = getConfig().getString("worlds." + world + ".sound", "");
        return key.isEmpty() ? null : Sound.sound(Key.key(key), Sound.Source.MUSIC, (float) getConfig().getDouble("volume", 0.6), 1f);
    }

    private void tick() {
        long now = System.currentTimeMillis();
        for (Player p : getServer().getOnlinePlayers()) {
            Sound s = track(p.getWorld().getName());
            if (s == null || now < nextStart.getOrDefault(p.getUniqueId(), 0L)) continue;
            p.playSound(s, Sound.Emitter.self());
            nextStart.put(p.getUniqueId(), now + getConfig().getLong("worlds." + p.getWorld().getName() + ".length-seconds", 120) * 1000);
        }
    }

    @EventHandler
    public void onWorld(PlayerChangedWorldEvent e) {
        Sound old = track(e.getFrom().getName());
        if (old != null) e.getPlayer().stopSound(SoundStop.named(old.name()));
        nextStart.remove(e.getPlayer().getUniqueId());
    }

    @EventHandler public void onQuit(PlayerQuitEvent e) { nextStart.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        var ws = getConfig().getConfigurationSection("worlds");
        sender.sendMessage(Component.text("GoldenAmbience: " + (ws == null ? 0 : ws.getKeys(false).size()) + " worlds with music.", NamedTextColor.GREEN));
        return true;
    }
}
