import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerInteractEntityEvent;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.util.Transformation;
import org.joml.AxisAngle4f;
import org.joml.Vector3f;

/**
 * Golden furniture (display-entity technique): /chair places an ItemDisplay (the look; a custom item model on 1.21.4+,
 * a vanilla stair here) facing the player (BlockFace from yaw), a barrier for collision and an Interaction entity as
 * the click box; right-click sits (the player rides the interaction entity); /chair clear removes ours by PDC tag.
 */
public class Furniture extends JavaPlugin implements Listener {
    private NamespacedKey tag;

    @Override
    public void onEnable() {
        tag = new NamespacedKey(this, "furniture");
        getCommand("chair").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    static BlockFace facing(float yaw) {
        BlockFace[] f = {BlockFace.SOUTH, BlockFace.WEST, BlockFace.NORTH, BlockFace.EAST};
        return f[Math.round(((yaw % 360) + 360) % 360 / 90f) & 3];
    }

    void place(Location base, BlockFace face) {
        Block b = base.getBlock();
        String id = b.getX() + "," + b.getY() + "," + b.getZ();
        float rot = switch (face) { case NORTH -> 180f; case EAST -> 270f; case WEST -> 90f; default -> 0f; };
        Location center = b.getLocation().add(0.5, 0.5, 0.5);
        World w = b.getWorld();
        w.spawn(center, ItemDisplay.class, d -> {
            d.setItemStack(new ItemStack(Material.OAK_STAIRS));
            d.setTransformation(new Transformation(new Vector3f(), new AxisAngle4f((float) Math.toRadians(rot), 0, 1, 0), new Vector3f(1f, 1f, 1f), new AxisAngle4f()));
            d.setViewRange(0.6f);
            d.getPersistentDataContainer().set(tag, PersistentDataType.STRING, id);
        });
        w.spawn(b.getLocation().add(0.5, 0, 0.5), Interaction.class, i -> {
            i.setInteractionWidth(1f);
            i.setInteractionHeight(0.6f);
            i.setResponsive(true);
            i.getPersistentDataContainer().set(tag, PersistentDataType.STRING, id);
        });
    }

    @EventHandler(ignoreCancelled = true)
    public void onSit(PlayerInteractEntityEvent e) {
        if (e.getHand() != EquipmentSlot.HAND || !(e.getRightClicked() instanceof Interaction i) || !i.getPersistentDataContainer().has(tag, PersistentDataType.STRING)) return;
        e.setCancelled(true);
        if (i.getPassengers().isEmpty()) i.addPassenger(e.getPlayer());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("clear")) {
            int n = 0;
            for (World w : getServer().getWorlds()) for (Entity en : w.getEntities()) if (en.getPersistentDataContainer().has(tag, PersistentDataType.STRING)) { en.remove(); n++; }
            sender.sendMessage(Component.text("Removed " + n + " furniture entities.", NamedTextColor.YELLOW));
            return true;
        }
        Location at = sender instanceof Player p ? p.getLocation() : getServer().getWorlds().get(0).getSpawnLocation();
        BlockFace face = facing(at.getYaw());
        place(at, face);
        sender.sendMessage(Component.text("Chair placed facing " + face.name().toLowerCase() + ".", NamedTextColor.GREEN));
        return true;
    }
}
''', yml("GoldenFurniture", "dev.nxeon.golden.furniture.Furniture", "Golden reference - display-entity furniture",
