        if (!(st instanceof Container filter)) return;
        ItemStack first = filter.getInventory().getItem(0);
        if (first != null && first.getType() != e.getItem().getType()) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenMachines: sorting hoppers over filter barrels" + (getConfig().getBoolean("enabled", true) ? " (on)" : " (off)") + ".", NamedTextColor.GREEN));
        return true;
    }
}
