package dev.nxeon.golden.graves;

import java.util.ArrayList;
import java.util.List;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.block.Block;
import org.bukkit.block.Chest;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden graves: on death (unless keepInventory) drops go into a chest at a safe spot (never in the void or lava);
 * the chest is tagged (TileState PDC) so only the owner or staff can break it. Overflow stays as normal drops.
 */
public class Graves extends JavaPlugin implements Listener {
    private NamespacedKey owner;

    @Override
    public void onEnable() {
        owner = new NamespacedKey(this, "grave_owner");
        getCommand("graves").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @EventHandler(priority = EventPriority.HIGH)
    public void onDeath(PlayerDeathEvent e) {
        if (e.getKeepInventory() || e.getDrops().isEmpty()) return;
        Location l = e.getPlayer().getLocation();
        int minY = l.getWorld().getMinHeight() + 1;
        if (l.getY() < minY) l.setY(minY);
        Block b = l.getBlock();
        if (b.isLiquid() || b.getType().isSolid()) b = l.getWorld().getHighestBlockAt(l).getRelative(0, 1, 0);
        b.setType(Material.CHEST);
        if (!(b.getState() instanceof Chest chest)) return;
        chest.getPersistentDataContainer().set(owner, PersistentDataType.STRING, e.getPlayer().getUniqueId().toString());
        chest.customName(Component.text(e.getPlayer().getName() + "'s grave"));
        chest.update();
        Chest live = (Chest) b.getState(false);
        List<ItemStack> overflow = new ArrayList<>(live.getBlockInventory().addItem(e.getDrops().toArray(new ItemStack[0])).values());
        e.getDrops().clear();
        e.getDrops().addAll(overflow);
        e.getPlayer().sendMessage(Component.text("Your items are in a grave at " + b.getX() + " " + b.getY() + " " + b.getZ() + ".", NamedTextColor.GOLD));
    }

    @EventHandler(ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        if (!(e.getBlock().getState(false) instanceof Chest c)) return;
        String o = c.getPersistentDataContainer().get(owner, PersistentDataType.STRING);
        if (o != null && !o.equals(e.getPlayer().getUniqueId().toString()) && !e.getPlayer().hasPermission("goldengraves.admin")) e.setCancelled(true);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        sender.sendMessage(Component.text("GoldenGraves active.", NamedTextColor.GREEN));
        return true;
    }
}
