package dev.nxeon.golden.quest;

import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/**
 * Golden kill quests: /quest start <id> | status. Progress lives in the PLAYER's PDC (persists with the player file);
 * only the killer's own kills count; reward items on completion.
 */
public class Quests extends JavaPlugin implements Listener {
    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("quest").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    private NamespacedKey k(String s) { return new NamespacedKey(this, s); }

    @EventHandler
    public void onKill(EntityDeathEvent e) {
        Player p = e.getEntity().getKiller();
        if (p == null) return;
        PersistentDataContainer pdc = p.getPersistentDataContainer();
        String q = pdc.get(k("active"), PersistentDataType.STRING);
        if (q == null) return;
        EntityType target = Registry.ENTITY_TYPE.get(NamespacedKey.minecraft(getConfig().getString("quests." + q + ".mob", "zombie")));
        if (e.getEntityType() != target) return;
        int n = pdc.getOrDefault(k("progress"), PersistentDataType.INTEGER, 0) + 1, need = getConfig().getInt("quests." + q + ".count", 10);
        pdc.set(k("progress"), PersistentDataType.INTEGER, n);
        p.sendActionBar(Component.text(q + ": " + n + "/" + need, NamedTextColor.YELLOW));
        if (n >= need) {
            pdc.remove(k("active"));
            pdc.remove(k("progress"));
            Material m = Material.matchMaterial(getConfig().getString("quests." + q + ".reward", "diamond"));
            if (m != null) p.getInventory().addItem(new ItemStack(m, getConfig().getInt("quests." + q + ".reward-amount", 1)));
            p.sendMessage(Component.text("Quest " + q + " complete!", NamedTextColor.GOLD));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        var qs = getConfig().getConfigurationSection("quests");
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenQuests: " + (qs == null ? 0 : qs.getKeys(false).size()) + " quests.", NamedTextColor.GRAY)); return true; }
        if (args.length == 2 && args[0].equalsIgnoreCase("start") && qs != null && qs.contains(args[1])) {
            p.getPersistentDataContainer().set(k("active"), PersistentDataType.STRING, args[1]);
            p.getPersistentDataContainer().set(k("progress"), PersistentDataType.INTEGER, 0);
            p.sendMessage(Component.text("Quest " + args[1] + " started.", NamedTextColor.GREEN));
            return true;
        }
        String q = p.getPersistentDataContainer().get(k("active"), PersistentDataType.STRING);
        p.sendMessage(Component.text(q == null ? "No active quest." : q + ": " + p.getPersistentDataContainer().getOrDefault(k("progress"), PersistentDataType.INTEGER, 0), NamedTextColor.AQUA));
        return true;
    }
}
''', yml("GoldenQuests", "dev.nxeon.golden.quest.Quests", "Golden reference - kill quests",
