import org.bukkit.NamespacedKey;
import org.bukkit.World;
import org.bukkit.block.structure.Mirror;
import org.bukkit.block.structure.StructureRotation;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.structure.Structure;
import org.bukkit.structure.StructureManager;
import org.bukkit.util.BlockVector;

/**
 * Golden structure placement: builds a small hut once, saves it as a Structure (StructureManager, kept in the plugin's
 * own namespace), then /hut place copies it at a location (rotation from config). No schematic files, no outside paths.
 */
public class Structures extends JavaPlugin {
    private NamespacedKey key;

    @Override
    public void onEnable() {
        saveDefaultConfig();
        key = new NamespacedKey(this, "hut");
        getCommand("hut").setExecutor(this);
    }

    private Structure hut(World w) {
        StructureManager sm = getServer().getStructureManager();
        Structure s = sm.getStructure(key);
        if (s != null) return s;
        Location o = new Location(w, 0, w.getMaxHeight() - 10, 0);
        for (int x = 0; x < 5; x++) for (int y = 0; y < 4; y++) for (int z = 0; z < 5; z++) {
            boolean wall = x == 0 || x == 4 || z == 0 || z == 4 || y == 3;
            o.clone().add(x, y, z).getBlock().setType(wall ? Material.OAK_PLANKS : Material.AIR, false);
        }
        s = sm.createStructure();
        s.fill(o, new BlockVector(5, 4, 5), false);
        for (int x = 0; x < 5; x++) for (int y = 0; y < 4; y++) for (int z = 0; z < 5; z++) o.clone().add(x, y, z).getBlock().setType(Material.AIR, false);
        sm.registerStructure(key, s);
        return s;
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        World w = getServer().getWorlds().get(0);
        Structure s = hut(w);
        if (args.length == 1 && args[0].equalsIgnoreCase("place")) {
            Location at = w.getSpawnLocation().add(8, 0, 8);
            StructureRotation rot = StructureRotation.valueOf(getConfig().getString("rotation", "NONE"));
            s.place(at, true, rot, Mirror.NONE, 0, 1f, new Random());
            sender.sendMessage(Component.text("Hut placed at " + at.getBlockX() + " " + at.getBlockY() + " " + at.getBlockZ() + ".", NamedTextColor.GREEN));
            return true;
        }
        sender.sendMessage(Component.text("Hut structure: " + s.getSize().getBlockX() + "x" + s.getSize().getBlockY() + "x" + s.getSize().getBlockZ() + ", " + s.getPaletteCount() + " palette(s).", NamedTextColor.AQUA));
        return true;
    }
}
