#!/usr/bin/env node
"use strict";
// Fetch + VERIFY the Nxeon-managed BetterModel pin (lib/cyrus/managed/catalog.json "bettermodel") and its runtime
// libraries (lib/cyrus/managed/bettermodel-3.5.0.libraries.json) into a directory, so that
//   <out>/bettermodel/bettermodel-3.5.0-paper.jar     = CYRUS_MANAGED_PLUGIN_DIR layout (artifact path of the catalog)
//   <out>/seeds/bettermodel-3.5.0-paper-libraries/... = what BetterModel's paper-library resolves into <server>/libraries
//   <out>/seeds/bettermodel-3.5.0-libby/...           = what its libby loader puts into plugins/BetterModel/.libs
// Every file is checked against the pinned sha256; a mismatch is deleted and the script exits 1. Test Flight uses the
// seeds (a flight has no internet): run with <out> = /tank/nxeon-build/tmp/testflight (seeds/ is TF_ROOT/seeds) or any
// dir under /tank/nxeon-build/tmp on node-2. Owner/agent tool; the build service and the portal never download.
//   node fetch-bettermodel.js <repo root> <out-dir> [--verify-only]
const fs = require("fs");
const path = require("path");
const https = require("https");
const crypto = require("crypto");

const [root, outDir] = process.argv.slice(2);
const verifyOnly = process.argv.includes("--verify-only");
if (!root || !outDir) { console.error("usage: fetch-bettermodel.js <repo root> <out-dir> [--verify-only]"); process.exit(2); }
const catalog = JSON.parse(fs.readFileSync(path.join(root, "lib/cyrus/managed/catalog.json"), "utf8"));
const entry = catalog.entries.find((e) => e.key === "bettermodel");
const libs = JSON.parse(fs.readFileSync(path.join(root, "lib/cyrus/managed", entry.runtimeLibraries), "utf8"));

function get(url, redirects = 0) {
  return new Promise((resolve, reject) => {
    if (!/^https:\/\//.test(url)) return reject(new Error(`refusing non-https ${url}`));
    https.get(url, { headers: { "User-Agent": "nxeon-cyrus-bettermodel/1.0" }, timeout: 60000 }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location && redirects < 5) { res.resume(); return resolve(get(new URL(res.headers.location, url).toString(), redirects + 1)); }
      if (res.statusCode !== 200) { res.resume(); return reject(new Error(`${url}: HTTP ${res.statusCode}`)); }
      const chunks = []; let n = 0;
      res.on("data", (c) => { n += c.length; if (n > 64 * 1024 * 1024) { res.destroy(); reject(new Error("too large")); } else chunks.push(c); });
      res.on("end", () => resolve(Buffer.concat(chunks)));
    }).on("error", reject).on("timeout", function () { this.destroy(new Error("timeout")); });
  });
}
const safe = (rel) => typeof rel === "string" && rel.length < 400 && !rel.startsWith("/") && !rel.split("/").some((s) => !s || s === "." || s === "..") && /^[A-Za-z0-9_.\/-]+$/.test(rel);

async function one(dest, url, sha256) {
  let buf = fs.existsSync(dest) ? fs.readFileSync(dest) : null;
  if (!buf && !verifyOnly) buf = await get(url);
  if (!buf) throw new Error(`${dest}: missing`);
  const h = crypto.createHash("sha256").update(buf).digest("hex");
  if (h !== sha256) { fs.rmSync(dest, { force: true }); throw new Error(`${dest}: sha256 ${h} != pinned ${sha256}`); }
  if (!fs.existsSync(dest)) { fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.writeFileSync(dest, buf); }
}

(async () => {
  let bad = 0, n = 0;
  const jobs = [{ dest: path.join(outDir, entry.artifact), url: entry.sourceRef.split(" ")[0], sha256: entry.sha256 }];
  for (const [group, seed] of [["paperLibraries", libs.paperLibraries.seed], ["libby", libs.libby.seed]]) {
    for (const f of libs[group].files) {
      if (!safe(f.path)) { console.error(`bad path ${f.path}`); bad++; continue; }
      jobs.push({ dest: path.join(outDir, "seeds", seed, f.path), url: f.source, sha256: f.sha256 });
    }
  }
  for (const j of jobs) {
    try { await one(j.dest, j.url, j.sha256); n++; } catch (e) { console.error(e.message); bad++; }
  }
  console.log(`${n} files verified (BetterModel ${entry.version} + ${libs.paperLibraries.files.length} paper-library + ${libs.libby.files.length} libby files), ${bad} problems`);
  process.exit(bad ? 1 : 0);
