cd /tank/dev-worktrees/cyrus-mc1/lib/cyrus/datapack && cat > emit/enchantment.ts <<'EOF'
import type { DataPackFeatures } from "../versions";
import { attributeId, type DpEnchantment, type DpEntityEffect, type DpLevelValue } from "../spec";
import { textComponent, type Json } from "./common";

const cost = (c: { base: number; perLevelAboveFirst: number }): Json => ({ base: c.base, per_level_above_first: c.perLevelAboveFirst });
const levelValue = (base: number, per?: number): Json => (per === undefined ? base : { type: "minecraft:linear", base, per_level_above_first: per });
const lv = (x: DpLevelValue): Json => (typeof x === "number" ? x : levelValue(x.base, x.perLevelAboveFirst));

/** One vanilla enchantment entity effect (bundle mc-coverage). Shapes are the same on 1.21.1 .. 1.21.11 (vanilla mcdoc). */
export function emitEntityEffect(fx: DpEntityEffect): Json {
  switch (fx.effect) {
    case "apply_mob_effect": return { type: "minecraft:apply_mob_effect", to_apply: fx.mobEffect, min_duration: lv(fx.minDuration), max_duration: lv(fx.maxDuration), min_amplifier: lv(fx.minAmplifier ?? 0), max_amplifier: lv(fx.maxAmplifier ?? fx.minAmplifier ?? 0) };
    case "ignite": return { type: "minecraft:ignite", duration: lv(fx.duration) };
    case "damage_entity": return { type: "minecraft:damage_entity", damage_type: fx.damageType, min_damage: lv(fx.minDamage), max_damage: lv(fx.maxDamage) };
    case "summon_entity": return { type: "minecraft:summon_entity", entity: fx.entity };
    case "play_sound": return { type: "minecraft:play_sound", sound: { sound_id: fx.sound }, volume: fx.volume ?? 1, pitch: fx.pitch ?? 1 };
    case "run_function": return { type: "minecraft:run_function", function: fx.function };
  }
}

/** The enchantment format of this subset is identical on 1.21.1 .. 26.2 (vanilla sharpness/unbreaking compared on every jar);
 * attribute ids are per version (1.21.1 generic.*), resolved from the version's real registry. */
export function emitEnchantment(e: DpEnchantment, fe: DataPackFeatures, ctx: { namespace?: string; id?: string } = {}): Json {
  const out: { [k: string]: Json } = { description: textComponent(e.description) };
  if (e.exclusiveSet) out.exclusive_set = e.exclusiveSet;
  out.supported_items = e.supportedItems;
  if (e.primaryItems) out.primary_items = e.primaryItems;
  Object.assign(out, { weight: e.weight, max_level: e.maxLevel, min_cost: cost(e.minCost), max_cost: cost(e.maxCost), anvil_cost: e.anvilCost, slots: e.slots });
  const fx: { [k: string]: Json[] } = {};
  if (e.effects?.length) {
    for (const x of e.effects) {
