#!/usr/bin/env tsx
// Bundle mc-coverage: the data pack lane additions on a REAL server, per version. Builds one pack with the new
// resource kinds (enchantment post_attack + attributes effects, damage_type, jukebox_song, predicate, item_modifier)
// through the same buildDataPack() the build service bundles, then boots ONE Paper server on node-2 (Test Flight, no
// internet) with it and checks over RCON that every resource loaded and works:
//   loot spawn with set_enchantments (the custom enchantment resolves), damage with the custom damage type,
//   execute if predicate, item modify with the item modifier, a jukebox item with the custom song component.
//   npx tsx scripts/cyrus/golden-datapack-flight.ts 1.21.11 [--out FILE] [--dry]
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { buildDataPack } from "../../lib/cyrus/datapack/emit";
import { atLeast } from "../../lib/cyrus/datapack/versions";
import { runTestFlight } from "../../lib/cyrus/testflight/client";
import type { TestFlightSpec } from "../../lib/cyrus/testflight/types";

const argv = process.argv.slice(2);
const opt = (n: string, d: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
const V = argv[0] ?? "1.21.11";
const NS = "nx_mc1dpk01";

export const GOLDEN_PACK = {
  schemaVersion: 1, name: "coverage", description: "Cyrus mc-coverage data pack lane check",
  resources: [
    { type: "damage_type", id: "zap", damageType: { scaling: "never", exhaustion: 0.1, effects: "burning" } },
    { type: "enchantment", id: "venom", enchantment: {
      description: { text: "Venom", color: "dark_green" }, supportedItems: "#minecraft:enchantable/sword", weight: 2, maxLevel: 3,
      minCost: { base: 10, perLevelAboveFirst: 10 }, maxCost: { base: 30, perLevelAboveFirst: 10 }, anvilCost: 4, slots: ["mainhand"],
      postAttack: [
        { enchanted: "attacker", affected: "victim", effect: { effect: "apply_mob_effect", mobEffect: "minecraft:poison", minDuration: { base: 3, perLevelAboveFirst: 2 }, maxDuration: { base: 3, perLevelAboveFirst: 2 }, minAmplifier: 0, maxAmplifier: 0 } },
        { enchanted: "attacker", affected: "victim", chance: 0.2, effect: { effect: "damage_entity", damageType: `${NS}:zap`, minDamage: 1, maxDamage: 2 } },
      ],
    } },
    { type: "enchantment", id: "swiftness", enchantment: {
      description: "Swiftness", supportedItems: "#minecraft:enchantable/foot_armor", weight: 2, maxLevel: 2,
      minCost: { base: 5, perLevelAboveFirst: 8 }, maxCost: { base: 25, perLevelAboveFirst: 8 }, anvilCost: 2, slots: ["feet"],
      attributes: [{ id: "speed", attribute: "movement_speed", amount: { base: 0.01, perLevelAboveFirst: 0.01 }, operation: "add_value" }],
    } },
    { type: "jukebox_song", id: "theme", song: { sound: "minecraft:music_disc.cat", description: "Cyrus Theme", lengthSeconds: 185, comparatorOutput: 7 } },
    { type: "predicate", id: "always", conditions: [{ cond: "random_chance", chance: 1 }] },
    { type: "item_modifier", id: "shiny", functions: [{ fn: "set_name", name: { text: "Shiny", color: "gold" } }, { fn: "set_enchantments", enchantments: { [`${NS}:venom`]: 2 } }] },
    { type: "loot_table", id: "venom_blade", table: { kind: "generic", pools: [{ rolls: 1, entries: [{ kind: "item", item: "minecraft:iron_sword", functions: [{ fn: "set_enchantments", enchantments: { [`${NS}:venom`]: 3 } }] }] }] } },
  ],
};

async function main() {
  const r = buildDataPack(GOLDEN_PACK, { version: V, namespace: NS });
  if (!r.ok) { console.error(`${V}: the pack did not build:\n${r.errors.join("\n")}`); process.exit(1); }
  const dir = mkdtempSync(path.join(os.tmpdir(), "mc1-dp-"));
  for (const f of r.pack.files) { mkdirSync(path.dirname(path.join(dir, f.path)), { recursive: true }); writeFileSync(path.join(dir, f.path), f.data ?? f.text); }
  if (argv.includes("--dry")) { console.log(r.pack.files.map((f) => `${f.path}\n${f.text}`).join("\n")); return; }
  // Item component syntax for the jukebox check: 1.21.4 and older wrap the song in {song:...}; 1.21.5+ take the id directly.
  const disc = atLeast(V, "1.21.5") ? `minecraft:music_disc_13[minecraft:jukebox_playable="${NS}:theme"]` : `minecraft:music_disc_13[minecraft:jukebox_playable={song:"${NS}:theme"}]`;
  const rcon: TestFlightSpec["rcon"] = [
    { id: "forceload", command: "forceload add 0 0" },
    { id: "loot-ench", command: `loot spawn 0 120 0 loot ${NS}:venom_blade`, expect: ["Dropped 1"] },
    { id: "predicate", command: `execute if predicate ${NS}:always`, expect: ["Test passed"] },
    { id: "chest", command: "setblock 0 100 0 minecraft:chest", expect: ["Changed the block"] },
    { id: "chest-item", command: "item replace block 0 100 0 container.0 with minecraft:iron_sword", expect: ["Replaced"] },
    { id: "item-modifier", command: `item modify block 0 100 0 container.0 ${NS}:shiny`, expect: ["Applied"] },
    { id: "jukebox-disc", command: `item replace block 0 100 0 container.1 with ${disc}`, expect: ["Replaced"] },
    { id: "summon", command: "summon minecraft:zombie 0 101 2 {NoAI:1b,PersistenceRequired:1b}", expect: ["Summoned"] },
    { id: "damage", command: `damage @e[type=minecraft:zombie,limit=1] 1 ${NS}:zap`, expect: ["Applied 1"] },
  ];
  const tf: TestFlightSpec = { version: V, datapacks: [{ localPath: dir, name: "coverage" }], rcon, timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 900 }, memory: { xmxMb: 1024, rssCapMb: 2048 } };
  const { report, summary } = await runTestFlight(tf);
  const ev = (id: string) => report.checks.find((x) => x.id === id)?.evidence ?? [];
  const out = { at: new Date().toISOString(), version: V, namespace: NS, packSha256: r.pack.sha256, files: r.pack.files.map((f) => f.path), apply: r.pack.apply, summary, rcon: ev("rcon_checks"), log: ev("startup_log_clean"), runId: report.runId };
  const file = opt("out", "/root/agent-notes/cyrus-research/mc-coverage-datapack-flights-2026-10-11.json");
  let all: unknown[] = [];
  try { all = JSON.parse(readFileSync(file, "utf8")); } catch { all = []; }
  writeFileSync(file, JSON.stringify([...(Array.isArray(all) ? all : []), out], null, 1) + "\n");
  console.log(`${V} data pack lane: ${summary.overall} (boot ${summary.bootMs} ms) failed=${summary.failed.join(",") || "-"}`);
  for (const l of [...out.rcon, ...out.log.slice(0, 8)]) console.log("  " + l.slice(0, 260));
}

if (require.main === module) main().catch((e) => { console.error(e); process.exit(2); });

