// Bundle mc-coverage, data pack lane gaps: enchantment entity effects (post_attack) + attribute effects, damage types,
// music-disc songs (jukebox_song), predicates and item modifiers. Pure: validation, per-version emission, the emitted-
// file validator and the bundled service copy. Real-server proof: scripts/cyrus/golden-datapack-flight.ts.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { validateDataPackSpec, attributeId, needsRestart, type DataPackSpec } from "../lib/cyrus/datapack/spec";
import { buildDataPack } from "../lib/cyrus/datapack/emit";
import { validatePackFiles } from "../lib/cyrus/datapack/validate";
import { isVanilla } from "../lib/cyrus/datapack/versions";

const ROOT = path.join(__dirname, "..");
const NS = "nx_mc1dpk01";
const PACK: DataPackSpec = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/golden/datapack.json"), "utf8").replaceAll("$NS", NS));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const DPJS = require(path.join(ROOT, "services/modbuilder/datapack-spec.js"));
const V = ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"];
const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x));
const file = (v: string, p: string) => { const b = buildDataPack(PACK, { version: v, namespace: NS }); assert.ok(b.ok, JSON.stringify(!b.ok && b.errors)); return JSON.parse(b.ok ? b.pack.files.find((f) => f.path === p)!.text : "null"); };
const codes = (spec: unknown, v = "1.21.11") => { const r = validateDataPackSpec(spec, { version: v, namespace: NS }); return r.ok ? [] : r.errors.map((e) => e.code); };

describe("data pack lane gaps (mc-coverage)", () => {
  it("the golden pack validates and builds on every data pack version, needs a restart, TS == bundled service copy", () => {
    for (const v of V) {
      const a = buildDataPack(PACK, { version: v, namespace: NS }), b = DPJS.buildDataPack(PACK, { version: v, namespace: NS });
      assert.ok(a.ok, `${v}: ${JSON.stringify(!a.ok && a.errors)}`);
      assert.equal(b.ok, true, v);
      if (a.ok) {
        assert.equal(a.pack.sha256, b.pack.sha256, `${v}: service bundle is stale (npx tsx scripts/cyrus/build-datapack-artifacts.ts)`);
        assert.equal(a.pack.apply, "restart");
        const rep = validatePackFiles(a.pack.files, v);
        assert.ok(rep.ok, `${v}: ${rep.errors.join("; ")}`);
        for (const t of ["damage_type/zap", "jukebox_song/theme", "predicate/always", "item_modifier/shiny"]) assert.ok(a.pack.files.some((f) => f.path === `data/${NS}/${t}.json`), `${v} ${t}`);
      }
    }
    assert.equal(needsRestart(PACK), true);
  });
  it("vanilla id kinds for the new registries come from the real jars", () => {
    for (const v of ["1.21.1", "1.21.11"]) {
      for (const t of ["apply_mob_effect", "ignite", "damage_entity", "summon_entity", "play_sound", "run_function"]) assert.ok(isVanilla("enchantment_entity_effect_type", t, v), `${v} ${t}`);
      assert.ok(isVanilla("damage_type", "minecraft:magic", v));
      assert.ok(isVanilla("jukebox_song", "minecraft:cat", v));
      assert.ok(isVanilla("enchantment_effect_component_type", "post_attack", v) && isVanilla("enchantment_effect_component_type", "attributes", v));
    }
  });
  it("attribute ids are per version (1.21.1 generic.*)", () => {
    assert.equal(attributeId("movement_speed", "1.21.1"), "minecraft:generic.movement_speed");
    assert.equal(attributeId("movement_speed", "1.21.11"), "minecraft:movement_speed");
    assert.equal(attributeId("block_interaction_range", "1.21.1"), "minecraft:player.block_interaction_range");
    assert.equal(attributeId("not_an_attribute", "1.21.11"), null);
    assert.equal(file("1.21.1", `data/${NS}/enchantment/swiftness.json`).effects["minecraft:attributes"][0].attribute, "minecraft:generic.movement_speed");
    assert.deepEqual(file("1.21.11", `data/${NS}/enchantment/swiftness.json`).effects["minecraft:attributes"][0], { id: `${NS}:enchantment.swiftness.speed`, attribute: "minecraft:movement_speed", amount: { type: "minecraft:linear", base: 0.01, per_level_above_first: 0.01 }, operation: "add_value" });
  });
  it("post_attack effects: vanilla shapes, chance as a random_chance requirement", () => {
    const pa = file("1.21.4", `data/${NS}/enchantment/venom.json`).effects["minecraft:post_attack"];
    assert.deepEqual(pa[0], { enchanted: "attacker", affected: "victim", effect: { type: "minecraft:apply_mob_effect", to_apply: "minecraft:poison", min_duration: { type: "minecraft:linear", base: 3, per_level_above_first: 2 }, max_duration: { type: "minecraft:linear", base: 3, per_level_above_first: 2 }, min_amplifier: 0, max_amplifier: 0 } });
    assert.deepEqual(pa[1].requirements, { condition: "minecraft:random_chance", chance: 0.2 });
    assert.equal(pa[1].effect.damage_type, `${NS}:zap`);
  });
  it("damage type, song, predicate and item modifier files", () => {
    assert.deepEqual(file("1.21.11", `data/${NS}/damage_type/zap.json`), { message_id: `${NS}.zap`, scaling: "never", exhaustion: 0.1, effects: "burning" });
    assert.deepEqual(file("1.21.11", `data/${NS}/jukebox_song/theme.json`), { sound_event: { sound_id: "minecraft:music_disc.cat" }, description: { text: "Cyrus Theme" }, length_in_seconds: 185, comparator_output: 7 });
    assert.deepEqual(file("1.21.11", `data/${NS}/predicate/always.json`), { condition: "minecraft:random_chance", chance: 1 });
    assert.equal(file("1.21.11", `data/${NS}/item_modifier/shiny.json`).length, 2);
  });
  it("refuses unknown effects, missing own damage types, bad sound keys, foreign namespaces", () => {
    const venom = (s: DataPackSpec) => (s.resources[1] as unknown as { enchantment: { postAttack: { effect: Record<string, unknown> }[] } }).enchantment.postAttack;
    const a = clone(PACK); venom(a)[0].effect.mobEffect = "minecraft:not_an_effect";
    assert.deepEqual(codes(a), ["unknown_vanilla_id"]);
    const b = clone(PACK); venom(b)[1].effect.damageType = `${NS}:missing`;
    assert.deepEqual(codes(b), ["unresolved_ref"]);
    const c = clone(PACK); (c.resources[3] as unknown as { song: { sound: string } }).song.sound = `${NS}:nodot`;
    assert.deepEqual(codes(c), ["sound_key"]);
    const d = clone(PACK); (d.resources[3] as unknown as { song: { sound: string } }).song.sound = "other_ns:x.y";
    assert.deepEqual(codes(d), ["foreign_namespace"]);
    const e = clone(PACK); (e.resources[2] as unknown as { enchantment: { attributes: { attribute: string }[] } }).enchantment.attributes[0].attribute = "fly_speed_xyz";
    assert.deepEqual(codes(e), ["unknown_vanilla_id"]);
  });
  it("the emitted-file validator checks the new files' fields", () => {
    const b = buildDataPack(PACK, { version: "1.21.11", namespace: NS });
    assert.ok(b.ok);
    if (!b.ok) return;
    const bad = b.pack.files.map((f) => (f.path.endsWith("damage_type/zap.json") ? { ...f, text: JSON.stringify({ message_id: "x", scaling: "never", exhaustion: 0, colour: "red" }) } : f.path.endsWith("predicate/always.json") ? { ...f, text: JSON.stringify({ condition: "minecraft:not_real" }) } : f));
    const rep = validatePackFiles(bad, "1.21.11");
    assert.equal(rep.ok, false);
    assert.ok(rep.errors.some((x) => /has no field "colour"/.test(x)), rep.errors.join("; "));
    assert.ok(rep.errors.some((x) => /not_real/.test(x)), rep.errors.join("; "));
  });
});

