    assert.equal(rep.ok, false);
    assert.ok(rep.errors.some((x) => /has no field "colour"/.test(x)), rep.errors.join("; "));
    assert.ok(rep.errors.some((x) => /not_real/.test(x)), rep.errors.join("; "));
  });
});

