// Bundle mc-coverage: CUSTOM BLOCKS for vanilla clients, the block-state-carrier technique (BB-vanilla-techniques row 1,
// the mechanism ItemsAdder / Oraxen / Nexo / CraftEngine use; implemented here from the documented vanilla mechanism,
// no third-party code). A mod's custom block is a note_block in a RESERVED state: the resource pack's
// blockstates/note_block.json maps that state to the mod's own cube model; every other state keeps the vanilla model.
//
// Reserved states: the 7 mob-head instruments (zombie, skeleton, creeper, dragon, wither_skeleton, piglin, custom_head)
// x 25 notes x powered = 350 states. Vanilla only reaches them when a mob head sits ON a note block and the block updates;
// with Paper's `block-updates.disable-noteblock-updates: true` (config/paper-global.yml; needs a restart) it never does.
// A mod gets one instrument (its "home", by namespace hash, like glyph blocks) = 50 blocks; collisions with another mod's
// home are reported (two mods = one blockstate file, the conflict engine's single-owner pack file rule).
//
// Pure + client-safe: validation, allocation, pack files (blockstate, block models, 1.21.4+ item definitions) and the Java
// support class (place / break / drops / no tuning / no note sounds / piston + explosion protection) for the plugin.
// Server facts verified on real Paper (scripts/cyrus/golden-noteblock-flight.ts); how it LOOKS needs a real client.
import { z } from "zod";
import { fnv1a64, NAMESPACE_RE } from "../engine-core/identifiers";

export const NOTEBLOCK_SPEC_VERSION = 1;
/** The mob-head instruments in vanilla blockstate names, in Bukkit Instrument names (same order). */
export const RESERVED_INSTRUMENTS = ["zombie", "skeleton", "creeper", "dragon", "wither_skeleton", "piglin", "custom_head"] as const;
export const BUKKIT_INSTRUMENT: Record<(typeof RESERVED_INSTRUMENTS)[number], string> = { zombie: "ZOMBIE", skeleton: "SKELETON", creeper: "CREEPER", dragon: "DRAGON", wither_skeleton: "WITHER_SKELETON", piglin: "PIGLIN", custom_head: "CUSTOM_HEAD" };
/** Every note_block instrument per version (data generator blocks.json, 2026-10-11): 23 on 1.21.x, 27 on 26.2 (trumpets). */
export const NOTEBLOCK_INSTRUMENTS_121 = ["harp", "basedrum", "snare", "hat", "bass", "flute", "bell", "guitar", "chime", "xylophone", "iron_xylophone", "cow_bell", "didgeridoo", "bit", "banjo", "pling", "zombie", "skeleton", "creeper", "dragon", "wither_skeleton", "piglin", "custom_head"] as const;
export const NOTEBLOCK_INSTRUMENTS_262 = ["harp", "basedrum", "snare", "hat", "bass", "flute", "bell", "guitar", "chime", "xylophone", "iron_xylophone", "cow_bell", "didgeridoo", "bit", "banjo", "pling", "trumpet", "trumpet_exposed", "trumpet_oxidized", "trumpet_weathered", "zombie", "skeleton", "creeper", "dragon", "wither_skeleton", "piglin", "custom_head"] as const;
export const NOTEBLOCK_LIMITS = { maxBlocks: 50, notes: 25 } as const;
export const BLOCK_SOUNDS = ["stone", "wood", "metal", "glass", "gravel", "wool", "amethyst_block"] as const;

const Tex = z.string().regex(/^[a-z][a-z0-9_]{1,31}$/, "a texture name of this mod (assets/textures/<name>.json)");
export const CustomBlockSchema = z.strictObject({
  id: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/),
  displayName: z.string().min(1).max(40),
  /** One texture for every face, or top/side/bottom. */
  texture: z.union([Tex, z.strictObject({ top: Tex, side: Tex, bottom: Tex })]),
  /** What breaking it drops: the block item itself, nothing, or a vanilla item. */
  drops: z.union([z.literal("self"), z.literal("none"), z.strictObject({ item: z.string().regex(/^minecraft:[a-z0-9_]+$/), count: z.number().int().min(1).max(64).optional() })]).default("self"),
  sound: z.enum(BLOCK_SOUNDS).default("stone"),
});
export type CustomBlock = z.infer<typeof CustomBlockSchema>;
export const NoteBlockSpecSchema = z.strictObject({ version: z.literal(NOTEBLOCK_SPEC_VERSION), blocks: z.array(CustomBlockSchema).min(1).max(NOTEBLOCK_LIMITS.maxBlocks) });
export type NoteBlockSpec = z.infer<typeof NoteBlockSpecSchema>;

export type BlockState = { instrument: (typeof RESERVED_INSTRUMENTS)[number]; note: number; powered: boolean };
export type Allocated = CustomBlock & { state: BlockState };
export type NbCheck = { ok: true; spec: NoteBlockSpec; blocks: Allocated[]; home: (typeof RESERVED_INSTRUMENTS)[number]; warnings: string[] } | { ok: false; errors: string[] };

/** The mod's home instrument: stable per namespace. */
export const homeInstrument = (ns: string): (typeof RESERVED_INSTRUMENTS)[number] => RESERVED_INSTRUMENTS[Number(fnv1a64(`noteblock:${ns}`) % BigInt(RESERVED_INSTRUMENTS.length))];

/** Block i of a mod: note = i % 25, powered = i >= 25 (50 states per instrument). Deterministic: same order, same states. */
export function stateFor(ns: string, index: number): BlockState {
  return { instrument: homeInstrument(ns), note: index % NOTEBLOCK_LIMITS.notes, powered: index >= NOTEBLOCK_LIMITS.notes };
}

export function checkNoteBlockSpec(raw: unknown, ctx: { namespace: string; textures?: readonly string[] }): NbCheck {
  if (!NAMESPACE_RE.test(ctx.namespace)) return { ok: false, errors: [`"${ctx.namespace}" is not a reserved nx_ namespace`] };
  const p = NoteBlockSpecSchema.safeParse(raw);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 20).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`) };
  const errors: string[] = [], warnings: string[] = [];
  const seen = new Set<string>();
  for (const b of p.data.blocks) {
    if (seen.has(b.id)) errors.push(`blocks: ${b.id} is defined twice`);
    seen.add(b.id);
    const texs = typeof b.texture === "string" ? [b.texture] : [b.texture.top, b.texture.side, b.texture.bottom];
    if (ctx.textures) for (const t of texs) if (!ctx.textures.includes(t)) errors.push(`blocks.${b.id}: texture ${t} is not one of this mod's textures`);
  }
  if (errors.length) return { ok: false, errors };
  const blocks = p.data.blocks.map((b, i) => ({ ...b, state: stateFor(ctx.namespace, i) }));
  warnings.push("custom note-block blocks need block-updates.disable-noteblock-updates: true in config/paper-global.yml (server-wide: vanilla note blocks stop re-tuning from neighbour updates) and one restart");
  return { ok: true, spec: p.data, blocks, home: homeInstrument(ctx.namespace), warnings };
}

const stateKey = (instrument: string, note: number, powered: boolean) => `instrument=${instrument},note=${note},powered=${powered}`;
const texRef = (ns: string, t: string) => `${ns}:item/${t}`;

export type PackFile = { path: string; text: string };

/**
 * Resource pack files for one mod on one version. The note_block blockstate lists EVERY state (vanilla's own file is a
 * single "" variant, which cannot be combined with keyed variants), so the instrument list must be the version's own.
 */
export function noteBlockPackFiles(blocks: readonly Allocated[], ns: string, opts: { instruments: readonly string[]; itemModels: boolean }): PackFile[] {
  const byState = new Map(blocks.map((b) => [stateKey(b.state.instrument, b.state.note, b.state.powered), b] as const));
  const variants: Record<string, { model: string }> = {};
  for (const ins of opts.instruments) for (let n = 0; n < NOTEBLOCK_LIMITS.notes; n++) for (const pw of [false, true]) {
    const k = stateKey(ins, n, pw);
    const b = byState.get(k);
    variants[k] = { model: b ? `${ns}:block/${b.id}` : "minecraft:block/note_block" };
  }
  const files: PackFile[] = [{ path: "assets/minecraft/blockstates/note_block.json", text: JSON.stringify({ variants }, null, 1) + "\n" }];
  for (const b of blocks) {
    const model = typeof b.texture === "string"
      ? { parent: "minecraft:block/cube_all", textures: { all: texRef(ns, b.texture) } }
      : { parent: "minecraft:block/cube_bottom_top", textures: { top: texRef(ns, b.texture.top), side: texRef(ns, b.texture.side), bottom: texRef(ns, b.texture.bottom) } };
    files.push({ path: `assets/${ns}/models/block/${b.id}.json`, text: JSON.stringify(model, null, 1) + "\n" });
    if (opts.itemModels) files.push({ path: `assets/${ns}/items/${b.id}.json`, text: JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:block/${b.id}` } }, null, 1) + "\n" });
  }
  return files.sort((a, b) => (a.path < b.path ? -1 : 1));
}

const javaString = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/[^\x20-\x7e]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`)}"`;

/**
 * The plugin's support class (one per mod, package `pkg`). Placing the block item puts the reserved state; breaking it
 * drops the block item (survival) and plays the configured sound; right-click tuning, note sounds, pistons and explosions
 * never change or move a custom block. `itemModels` = 1.21.4+ (setItemModel on the block item); 1.21.1 uses a named
 * note_block item (custom-model-data icons are the texture lane's legacy path).
 */
export function noteBlockJava(blocks: readonly Allocated[], ns: string, pkg: string, opts: { itemModels: boolean }): string {
  const rows = blocks.map((b) => `        def(${javaString(b.id)}, ${javaString(b.displayName)}, Instrument.${BUKKIT_INSTRUMENT[b.state.instrument]}, ${b.state.note}, ${b.state.powered}, ${b.drops === "self" ? '"self"' : b.drops === "none" ? '"none"' : javaString(b.drops.item + ":" + (b.drops.count ?? 1))}, ${javaString(b.sound)});`).join("\n");
  return `package ${pkg};

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.GameMode;
import org.bukkit.Instrument;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Note;
import org.bukkit.block.Block;
import org.bukkit.block.data.type.NoteBlock;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockExplodeEvent;
import org.bukkit.event.block.BlockPistonExtendEvent;
import org.bukkit.event.block.BlockPistonRetractEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.block.NotePlayEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/** GENERATED by Cyrus (lib/cyrus/blocks/noteblock.ts) for ${ns}: custom blocks on reserved note_block states. */
public final class CustomBlocks implements Listener {
    public record Def(String id, String name, Instrument instrument, int note, boolean powered, String drops, String sound) {}
    private final Map<String, Def> byId = new LinkedHashMap<>();
    private final JavaPlugin plugin;
    private final NamespacedKey itemKey;

    public CustomBlocks(JavaPlugin plugin) {
        this.plugin = plugin;
        this.itemKey = new NamespacedKey(plugin, "custom_block");
${rows}
    }

    private void def(String id, String name, Instrument instrument, int note, boolean powered, String drops, String sound) {
        byId.put(id, new Def(id, name, instrument, note, powered, drops, sound));
    }

    public List<String> ids() { return new ArrayList<>(byId.keySet()); }

    /** The custom block at this position, or null (a vanilla note block or any other block). */
    public Def at(Block b) {
        if (b.getType() != Material.NOTE_BLOCK || !(b.getBlockData() instanceof NoteBlock nb)) return null;
        for (Def d : byId.values()) if (d.instrument() == nb.getInstrument() && d.note() == nb.getNote().getId() && d.powered() == nb.isPowered()) return d;
        return null;
    }

    public ItemStack item(String id, int amount) {
        Def d = byId.get(id);
        if (d == null) return null;
        ItemStack it = new ItemStack(Material.NOTE_BLOCK, amount);
        it.editMeta(m -> {
            m.displayName(Component.text(d.name()).decoration(TextDecoration.ITALIC, false));
            m.getPersistentDataContainer().set(itemKey, PersistentDataType.STRING, d.id());${opts.itemModels ? `
            m.setItemModel(new NamespacedKey(${javaString(ns)}, d.id()));` : ""}
        });
        return it;
    }

    /** Puts the block's reserved state at b without physics (also used by commands). */
    public boolean place(Block b, String id) {
        Def d = byId.get(id);
        if (d == null) return false;
        NoteBlock nb = (NoteBlock) Material.NOTE_BLOCK.createBlockData();
        nb.setInstrument(d.instrument());
        nb.setNote(new Note(d.note()));
        nb.setPowered(d.powered());
        b.setBlockData(nb, false);
        return true;
    }

    private void sound(Block b, Def d, String kind) {
        b.getWorld().playSound(Sound.sound(Key.key("minecraft", "block." + d.sound() + "." + kind), Sound.Source.BLOCK, 1f, 0.9f), b.getX() + 0.5, b.getY() + 0.5, b.getZ() + 0.5);
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onPlace(BlockPlaceEvent e) {
        ItemStack it = e.getItemInHand();
        String id = it.hasItemMeta() ? it.getItemMeta().getPersistentDataContainer().get(itemKey, PersistentDataType.STRING) : null;
        if (id == null || !byId.containsKey(id)) return;
        place(e.getBlockPlaced(), id);
        sound(e.getBlockPlaced(), byId.get(id), "place");
    }

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBreak(BlockBreakEvent e) {
        Def d = at(e.getBlock());
        if (d == null) return;
        e.setDropItems(false);
        sound(e.getBlock(), d, "break");
        if (e.getPlayer().getGameMode() == GameMode.CREATIVE || d.drops().equals("none")) return;
        ItemStack drop;
        if (d.drops().equals("self")) drop = item(d.id(), 1);
        else {
            String[] p = d.drops().split(":");
            Material m = Material.matchMaterial(p[0] + ":" + p[1]);
            drop = m == null ? null : new ItemStack(m, Integer.parseInt(p[2]));
        }
        if (drop != null) e.getBlock().getWorld().dropItemNaturally(e.getBlock().getLocation().add(0.5, 0.5, 0.5), drop);
    }

    /** No tuning: right-clicking a custom block (or with a custom block item) never changes the note. */
    @EventHandler(priority = EventPriority.LOW)
    public void onInteract(PlayerInteractEvent e) {
        if (e.getAction() != Action.RIGHT_CLICK_BLOCK || e.getClickedBlock() == null || at(e.getClickedBlock()) == null) return;
        if (e.getPlayer().isSneaking() && e.getItem() != null && e.getItem().getType().isBlock()) return; // let players place against it
        e.setUseInteractedBlock(org.bukkit.event.Event.Result.DENY);
    }

    @EventHandler(ignoreCancelled = true)
    public void onNote(NotePlayEvent e) { if (at(e.getBlock()) != null) e.setCancelled(true); }

    @EventHandler(ignoreCancelled = true)
    public void onPistonOut(BlockPistonExtendEvent e) { if (e.getBlocks().stream().anyMatch(b -> at(b) != null)) e.setCancelled(true); }

    @EventHandler(ignoreCancelled = true)
    public void onPistonIn(BlockPistonRetractEvent e) { if (e.getBlocks().stream().anyMatch(b -> at(b) != null)) e.setCancelled(true); }

    @EventHandler(ignoreCancelled = true)
    public void onExplode(EntityExplodeEvent e) { e.blockList().removeIf(b -> at(b) != null && dropOnExplode(b)); }

    @EventHandler(ignoreCancelled = true)
    public void onBlockExplode(BlockExplodeEvent e) { e.blockList().removeIf(b -> at(b) != null && dropOnExplode(b)); }

    /** Exploded custom blocks drop their own item instead of a note block. */
    private boolean dropOnExplode(Block b) {
        Def d = at(b);
        if (!d.drops().equals("none")) { ItemStack it = item(d.id(), 1); if (it != null) b.getWorld().dropItemNaturally(b.getLocation().add(0.5, 0.5, 0.5), it); }
        b.setType(Material.AIR, false);
        return true;
    }
}
`;
}

/** Plain-language limits for the planner / matrix. */
export const NOTEBLOCK_LIMITS_TEXT = [
  "Custom blocks are note blocks in reserved states with the mod's own look: players accept the resource pack to see them; without it they look like note blocks.",
  "The server needs block-updates.disable-noteblock-updates: true (Paper global config, one restart); it is server-wide, so vanilla note blocks no longer re-tune themselves from neighbouring blocks.",
  `At most ${NOTEBLOCK_LIMITS.maxBlocks} custom block types per mod; they break as fast as a note block and keep its hardness; another mod that also ships note-block blocks shares one blockstate file (the conflict check warns).`,
];

