  sound: z.enum(BLOCK_SOUNDS).default("stone"),
});
export type CustomBlock = z.infer<typeof CustomBlockSchema>;
export const NoteBlockSpecSchema = z.strictObject({ version: z.literal(NOTEBLOCK_SPEC_VERSION), blocks: z.array(CustomBlockSchema).min(1).max(NOTEBLOCK_LIMITS.maxBlocks) });
export type NoteBlockSpec = z.infer<typeof NoteBlockSpecSchema>;

export type BlockState = { instrument: (typeof RESERVED_INSTRUMENTS)[number]; note: number; powered: boolean };
export type Allocated = CustomBlock & { state: BlockState };
export type NbCheck = { ok: true; spec: NoteBlockSpec; blocks: Allocated[]; home: (typeof RESERVED_INSTRUMENTS)[number]; warnings: string[] } | { ok: false; errors: string[] };

/** The mod's home instrument: stable per namespace. */
export const homeInstrument = (ns: string): (typeof RESERVED_INSTRUMENTS)[number] => RESERVED_INSTRUMENTS[Number(fnv1a64(`noteblock:${ns}`) % BigInt(RESERVED_INSTRUMENTS.length))];

/** Block i of a mod: note = i % 25, powered = i >= 25 (50 states per instrument). Deterministic: same order, same states. */
export function stateFor(ns: string, index: number): BlockState {
  return { instrument: homeInstrument(ns), note: index % NOTEBLOCK_LIMITS.notes, powered: index >= NOTEBLOCK_LIMITS.notes };
}

export function checkNoteBlockSpec(raw: unknown, ctx: { namespace: string; textures?: readonly string[] }): NbCheck {
  if (!NAMESPACE_RE.test(ctx.namespace)) return { ok: false, errors: [`"${ctx.namespace}" is not a reserved nx_ namespace`] };
  const p = NoteBlockSpecSchema.safeParse(raw);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 20).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`) };
  const errors: string[] = [], warnings: string[] = [];
  const seen = new Set<string>();
  for (const b of p.data.blocks) {
    if (seen.has(b.id)) errors.push(`blocks: ${b.id} is defined twice`);
    seen.add(b.id);
    const texs = typeof b.texture === "string" ? [b.texture] : [b.texture.top, b.texture.side, b.texture.bottom];
    if (ctx.textures) for (const t of texs) if (!ctx.textures.includes(t)) errors.push(`blocks.${b.id}: texture ${t} is not one of this mod's textures`);
  }
  if (errors.length) return { ok: false, errors };
  const blocks = p.data.blocks.map((b, i) => ({ ...b, state: stateFor(ctx.namespace, i) }));
  warnings.push("custom note-block blocks need block-updates.disable-noteblock-updates: true in config/paper-global.yml (server-wide: vanilla note blocks stop re-tuning from neighbour updates) and one restart");
  return { ok: true, spec: p.data, blocks, home: homeInstrument(ctx.namespace), warnings };
}

const stateKey = (instrument: string, note: number, powered: boolean) => `instrument=${instrument},note=${note},powered=${powered}`;
const texRef = (ns: string, t: string) => `${ns}:item/${t}`;

export type PackFile = { path: string; text: string };

/**
 * Resource pack files for one mod on one version. The note_block blockstate lists EVERY state (vanilla's own file is a
 * single "" variant, which cannot be combined with keyed variants), so the instrument list must be the version's own.
 */
export function noteBlockPackFiles(blocks: readonly Allocated[], ns: string, opts: { instruments: readonly string[]; itemModels: boolean }): PackFile[] {
  const byState = new Map(blocks.map((b) => [stateKey(b.state.instrument, b.state.note, b.state.powered), b] as const));
  const variants: Record<string, { model: string }> = {};
  for (const ins of opts.instruments) for (let n = 0; n < NOTEBLOCK_LIMITS.notes; n++) for (const pw of [false, true]) {
    const k = stateKey(ins, n, pw);
    const b = byState.get(k);
    variants[k] = { model: b ? `${ns}:block/${b.id}` : "minecraft:block/note_block" };
  }
  const files: PackFile[] = [{ path: "assets/minecraft/blockstates/note_block.json", text: JSON.stringify({ variants }, null, 1) + "\n" }];
  for (const b of blocks) {
    const model = typeof b.texture === "string"
      ? { parent: "minecraft:block/cube_all", textures: { all: texRef(ns, b.texture) } }
      : { parent: "minecraft:block/cube_bottom_top", textures: { top: texRef(ns, b.texture.top), side: texRef(ns, b.texture.side), bottom: texRef(ns, b.texture.bottom) } };
    files.push({ path: `assets/${ns}/models/block/${b.id}.json`, text: JSON.stringify(model, null, 1) + "\n" });
    if (opts.itemModels) files.push({ path: `assets/${ns}/items/${b.id}.json`, text: JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:block/${b.id}` } }, null, 1) + "\n" });
  }
  return files.sort((a, b) => (a.path < b.path ? -1 : 1));
}

const javaString = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/[^\x20-\x7e]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`)}"`;

/**
 * The plugin's support class (one per mod, package `pkg`). Placing the block item puts the reserved state; breaking it
 * drops the block item (survival) and plays the configured sound; right-click tuning, note sounds, pistons and explosions
 * never change or move a custom block. `itemModels` = 1.21.4+ (setItemModel on the block item); 1.21.1 uses a named
 * note_block item (custom-model-data icons are the texture lane's legacy path).
 */
export function noteBlockJava(blocks: readonly Allocated[], ns: string, pkg: string, opts: { itemModels: boolean }): string {
  const rows = blocks.map((b) => `        def(${javaString(b.id)}, ${javaString(b.displayName)}, Instrument.${BUKKIT_INSTRUMENT[b.state.instrument]}, ${b.state.note}, ${b.state.powered}, ${b.drops === "self" ? '"self"' : b.drops === "none" ? '"none"' : javaString(b.drops.item + ":" + (b.drops.count ?? 1))}, ${javaString(b.sound)});`).join("\n");
  return `package ${pkg};

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.sound.Sound;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.GameMode;
import org.bukkit.Instrument;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Note;
import org.bukkit.block.Block;
import org.bukkit.block.data.type.NoteBlock;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.Action;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.block.BlockExplodeEvent;
import org.bukkit.event.block.BlockPistonExtendEvent;
import org.bukkit.event.block.BlockPistonRetractEvent;
import org.bukkit.event.block.BlockPlaceEvent;
import org.bukkit.event.block.NotePlayEvent;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.event.player.PlayerInteractEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

/** GENERATED by Cyrus (lib/cyrus/blocks/noteblock.ts) for ${ns}: custom blocks on reserved note_block states. */
public final class CustomBlocks implements Listener {
    public record Def(String id, String name, Instrument instrument, int note, boolean powered, String drops, String sound) {}
    private final Map<String, Def> byId = new LinkedHashMap<>();
    private final JavaPlugin plugin;
    private final NamespacedKey itemKey;

    public CustomBlocks(JavaPlugin plugin) {
        this.plugin = plugin;
        this.itemKey = new NamespacedKey(plugin, "custom_block");
${rows}
    }

    private void def(String id, String name, Instrument instrument, int note, boolean powered, String drops, String sound) {
        byId.put(id, new Def(id, name, instrument, note, powered, drops, sound));
    }

    public List<String> ids() { return new ArrayList<>(byId.keySet()); }

    /** The custom block at this position, or null (a vanilla note block or any other block). */
    public Def at(Block b) {
