#!/usr/bin/env tsx
// Bundle mc-coverage: writes the golden note-block custom-block plugin (services/modbuilder/golden/plugins/mc-noteblocks)
// from lib/cyrus/blocks/noteblock.ts, so the golden harness compiles the GENERATED support class on every buildable
// version (src@1.21.1 = no item models) and the golden Test Flight checks the reserved states on a real server.
//   npx tsx scripts/cyrus/golden-noteblock.ts [--check]
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { checkNoteBlockSpec, noteBlockJava, noteBlockPackFiles, NOTEBLOCK_INSTRUMENTS_121 } from "../../lib/cyrus/blocks/noteblock";

const ROOT = path.resolve(__dirname, "../..");
const DIR = path.join(ROOT, "services/modbuilder/golden/plugins/mc-noteblocks");
export const NB_NS = "nx_mc1blk01";
export const NB_SPEC = { version: 1, blocks: [
  { id: "ruby_block", displayName: "Ruby Block", texture: "ruby_block", sound: "amethyst_block" },
  { id: "marble", displayName: "Marble", texture: { top: "marble_top", side: "marble_side", bottom: "marble_top" }, sound: "stone" },
  { id: "ore_shard", displayName: "Shard Ore", texture: "shard_ore", drops: { item: "minecraft:amethyst_shard", count: 2 } },
] };

const MAIN = `package dev.nxeon.golden.noteblocks;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden custom blocks (note-block state carrier): /cblock list | give <id> [player] | place <id> x y z | info x y z. */
public class NoteBlocks extends JavaPlugin {
    private CustomBlocks blocks;

    @Override
    public void onEnable() {
        blocks = new CustomBlocks(this);
        getServer().getPluginManager().registerEvents(blocks, this);
        getCommand("cblock").setExecutor(this);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0].toLowerCase() : "list";
        World w = getServer().getWorlds().get(0);
        try {
            switch (sub) {
                case "give" -> {
                    Player p = args.length > 2 ? Bukkit.getPlayerExact(args[2]) : sender instanceof Player s ? s : null;
                    var it = args.length > 1 ? blocks.item(args[1], 16) : null;
                    if (it == null) { sender.sendMessage(Component.text("Unknown block.", NamedTextColor.RED)); return true; }
                    if (p == null) { sender.sendMessage(Component.text("Item ok: " + it.getType().getKey().getKey() + ".", NamedTextColor.YELLOW)); return true; }
                    p.getInventory().addItem(it);
                }
                case "place" -> {
                    Block b = w.getBlockAt(Integer.parseInt(args[2]), Integer.parseInt(args[3]), Integer.parseInt(args[4]));
                    sender.sendMessage(Component.text(blocks.place(b, args[1]) ? "Placed " + args[1] + "." : "Unknown block.", NamedTextColor.GREEN));
                }
                case "info" -> {
                    Block b = w.getBlockAt(Integer.parseInt(args[1]), Integer.parseInt(args[2]), Integer.parseInt(args[3]));
                    CustomBlocks.Def d = blocks.at(b);
                    sender.sendMessage(Component.text(d == null ? "Not a custom block: " + b.getBlockData().getAsString() : "Custom block " + d.id() + " (" + b.getBlockData().getAsString() + ")", NamedTextColor.AQUA));
                }
                default -> sender.sendMessage(Component.text("Custom blocks: " + String.join(", ", blocks.ids()), NamedTextColor.AQUA));
            }
        } catch (RuntimeException e) {
            sender.sendMessage(Component.text("Usage: /cblock list | give <id> [player] | place <id> x y z | info x y z", NamedTextColor.GRAY));
        }
        return true;
    }
}
`;

export function goldenFiles(): Record<string, string> {
  const chk = checkNoteBlockSpec(NB_SPEC, { namespace: NB_NS });
  if (!chk.ok) throw new Error(chk.errors.join("; "));
  const st = (i: number) => chk.blocks[i].state;
  const stateText = (i: number) => `instrument=${st(i).instrument},note=${st(i).note},powered=${st(i).powered}`;
  const golden = {
    archetype: "custom_blocks",
    notes: "GENERATED by scripts/cyrus/golden-noteblock.ts from lib/cyrus/blocks/noteblock.ts; do not edit",
    rcon: [
      { command: "cblock list", expect: ["Custom blocks: ruby_block, marble, ore_shard"] },
      { command: "cblock give ruby_block", expect: ["Item ok: note_block."] },
      { command: "cblock place ruby_block 3 100 3", expect: ["Placed ruby_block."] },
      { command: "execute if block 3 100 3 minecraft:note_block[" + stateText(0) + "]", expect: ["Test passed"] },
      { command: "cblock info 3 100 3", expect: ["Custom block ruby_block"] },
      { command: "cblock place ore_shard 4 100 3", expect: ["Placed ore_shard."] },
      { command: "execute if block 4 100 3 minecraft:note_block[" + stateText(2) + "]", expect: ["Test passed"] },
      { command: "setblock 5 100 3 minecraft:note_block", expect: ["Changed the block"] },
      { command: "cblock info 5 100 3", expect: ["Not a custom block"] },
    ],
  };
  const yml = `name: GoldenNoteBlocks\nversion: 1.0.0\nmain: dev.nxeon.golden.noteblocks.NoteBlocks\napi-version: '@API@'\ndescription: Golden reference - custom blocks on reserved note block states (generated support class)\nauthor: Nxeon Mod Builder\ncommands:\n  cblock:\n    description: Custom block tools\n    usage: /cblock <list|give|place|info>\n    permission: goldenblocks.admin\npermissions:\n  goldenblocks.admin:\n    description: Use /cblock\n    default: op\n`;
  const pkg = "dev.nxeon.golden.noteblocks";
  const pack = noteBlockPackFiles(chk.blocks, NB_NS, { instruments: NOTEBLOCK_INSTRUMENTS_121, itemModels: true });
  return {
    "plugin.yml": yml,
    "golden.json": JSON.stringify(golden, null, 1) + "\n",
    "src/dev/nxeon/golden/noteblocks/NoteBlocks.java": MAIN,
    "src/dev/nxeon/golden/noteblocks/CustomBlocks.java": noteBlockJava(chk.blocks, NB_NS, pkg, { itemModels: true }),
    "src@1.21.1/dev/nxeon/golden/noteblocks/CustomBlocks.java": noteBlockJava(chk.blocks, NB_NS, pkg, { itemModels: false }),
    "pack-files.txt": pack.map((f) => `${f.path} ${Buffer.byteLength(f.text)}`).join("\n") + "\n",
  };
}

if (require.main === module) {
  let stale = 0;
  for (const [rel, text] of Object.entries(goldenFiles())) {
    const abs = path.join(DIR, rel);
    if (process.argv.includes("--check")) { if (!existsSync(abs) || readFileSync(abs, "utf8") !== text) { stale++; console.error(`stale ${rel}`); } continue; }
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, text);
    console.log(`wrote ${rel}`);
  }
  if (stale) process.exit(1);
}

