const Hex = z.string().regex(/^#[0-9a-fA-F]{6}$/);
export const ArmorSetSchema = z.strictObject({
  id: z.string().regex(/^[a-z][a-z0-9_]{1,24}$/),
  displayName: z.string().min(1).max(32),
  palette: z.strictObject({ base: Hex, light: Hex, dark: Hex, accent: Hex.optional() }),
  style: z.enum(ARMOR_STYLES),
  /** Armor points per piece (vanilla iron: 2/6/5/2, diamond: 3/8/6/3). */
  armor: z.strictObject({ helmet: z.number().min(0).max(10), chestplate: z.number().min(0).max(15), leggings: z.number().min(0).max(12), boots: z.number().min(0).max(10) }),
  toughness: z.number().min(0).max(5).default(0),
  /** Full-set bonus: a vanilla potion effect while all four pieces are worn (key without minecraft:). */
  setBonus: z.strictObject({ effect: z.string().regex(/^[a-z_]{2,32}$/), amplifier: z.number().int().min(0).max(4) }).optional(),
});
export type ArmorSet = z.infer<typeof ArmorSetSchema>;
export const ArmorSpecSchema = z.strictObject({ version: z.literal(ARMOR_SPEC_VERSION), sets: z.array(ArmorSetSchema).min(1).max(ARMOR_LIMITS.maxSets) });
export type ArmorSpec = z.infer<typeof ArmorSpecSchema>;

export function checkArmorSpec(raw: unknown, ctx: { namespace: string }): { ok: true; spec: ArmorSpec } | { ok: false; errors: string[] } {
  if (!NAMESPACE_RE.test(ctx.namespace)) return { ok: false, errors: [`"${ctx.namespace}" is not a reserved nx_ namespace`] };
  const p = ArmorSpecSchema.safeParse(raw);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 20).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`) };
  const ids = p.data.sets.map((s) => s.id);
  if (new Set(ids).size !== ids.length) return { ok: false, errors: ["sets: two sets share an id"] };
  return { ok: true, spec: p.data };
}

// ---------------------------------------------------------------------------------------------------------------
// Raster + PNG (w x h)
// ---------------------------------------------------------------------------------------------------------------
export type Img = { w: number; h: number; px: Uint8ClampedArray };
const img = (w: number, h: number): Img => ({ w, h, px: new Uint8ClampedArray(w * h * 4) });
const rgb = (hex: string): [number, number, number] => [parseInt(hex.slice(1, 3), 16), parseInt(hex.slice(3, 5), 16), parseInt(hex.slice(5, 7), 16)];
const mix = (a: [number, number, number], b: [number, number, number], t: number): [number, number, number] => [0, 1, 2].map((i) => Math.round(a[i] + (b[i] - a[i]) * t)) as [number, number, number];
function put(m: Img, x: number, y: number, c: [number, number, number], a = 255) {
  if (x < 0 || y < 0 || x >= m.w || y >= m.h) return;
  const i = (y * m.w + x) * 4;
  m.px[i] = c[0]; m.px[i + 1] = c[1]; m.px[i + 2] = c[2]; m.px[i + 3] = a;
}
function chunk(type: string, data: Uint8Array): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0); out.write(type, 4, "ascii"); Buffer.from(data).copy(out, 8);
  out.writeUInt32BE(crc32(out.subarray(4, 8 + data.length)), 8 + data.length);
  return out;
}
export function encodePngWH(m: Img): Buffer {
  const raw = Buffer.alloc(m.h * (m.w * 4 + 1));
  for (let y = 0; y < m.h; y++) { raw[y * (m.w * 4 + 1)] = 0; Buffer.from(m.px.buffer, m.px.byteOffset + y * m.w * 4, m.w * 4).copy(raw, y * (m.w * 4 + 1) + 1); }
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(m.w, 0); ihdr.writeUInt32BE(m.h, 4); ihdr[8] = 8; ihdr[9] = 6;
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk("IHDR", ihdr), chunk("IDAT", deflateSync(raw, { level: 9 })), chunk("IEND", Buffer.alloc(0))]);
}

// ---------------------------------------------------------------------------------------------------------------
// The vanilla humanoid armor UV layout (64x32): a box at texture offset (u, v) with size (w, h, d) unfolds into
// top (u+d, v, w, d), bottom (u+d+w, v, w, d), right (u, v+d, d, h), front (u+d, v+d, w, h), left (u+d+w, v+d, d, h),
// back (u+2d+w, v+d, w, h).
// ---------------------------------------------------------------------------------------------------------------
type Face = { x: number; y: number; w: number; h: number; side: "top" | "bottom" | "front" | "back" | "left" | "right" };
function box(u: number, v: number, w: number, h: number, d: number): Face[] {
  return [
    { x: u + d, y: v, w, h: d, side: "top" }, { x: u + d + w, y: v, w, h: d, side: "bottom" },
    { x: u, y: v + d, w: d, h, side: "right" }, { x: u + d, y: v + d, w, h, side: "front" },
    { x: u + d + w, y: v + d, w: d, h, side: "left" }, { x: u + 2 * d + w, y: v + d, w, h, side: "back" },
  ];
}
const HEAD = box(0, 0, 8, 8, 8), BODY = box(16, 16, 8, 12, 4), ARM = box(40, 16, 4, 12, 4), LEG = box(0, 16, 4, 12, 4);

type Pal = { base: [number, number, number]; light: [number, number, number]; dark: [number, number, number]; accent: [number, number, number] };
function shadeFor(p: Pal, side: Face["side"]): [number, number, number] {
  return side === "top" ? p.light : side === "front" ? mix(p.base, p.light, 0.25) : side === "back" || side === "bottom" ? mix(p.base, p.dark, 0.45) : p.base;
}
/** Paint one face: shaded fill, the style's pattern, a dark rim. rows = which rows of the face to paint (0..h-1). */
function paintFace(m: Img, f: Face, p: Pal, style: ArmorSet["style"], rows?: [number, number], hole?: (x: number, y: number) => boolean) {
  const [r0, r1] = rows ?? [0, f.h - 1];
  const fill = shadeFor(p, f.side);
  for (let yy = r0; yy <= r1; yy++) for (let xx = 0; xx < f.w; xx++) {
    if (hole && hole(xx, yy)) continue;
    let c = fill;
    const rim = xx === 0 || xx === f.w - 1 || yy === r0 || yy === r1;
    if (style === "plate" && (yy - r0) % 4 === 3) c = mix(fill, p.dark, 0.5);
    if (style === "scale" && ((xx + Math.floor((yy - r0) / 2)) % 3 === 0) && (yy - r0) % 2 === 1) c = mix(fill, p.dark, 0.4);
    if (style === "cloth" && (xx + yy) % 5 === 0) c = mix(fill, p.light, 0.3);
    if (style === "leather" && (xx * 7 + yy * 3) % 11 === 0) c = mix(fill, p.dark, 0.25);
    if (style === "crystal" && (xx === yy % f.w || xx === (f.w - 1 - (yy % f.w)))) c = mix(fill, p.light, 0.55);
    if (rim) c = mix(fill, p.dark, 0.6);
    if (f.side === "front" && yy === r0 + 1 && xx > 0 && xx < f.w - 1 && style !== "cloth") c = p.accent;
    put(m, f.x + xx, f.y + yy, c);
  }
}

/** humanoid layer (helmet, chestplate, boots) and humanoid_leggings layer for one set. */
export function armorLayers(set: ArmorSet): { humanoid: Img; leggings: Img } {
  const p: Pal = { base: rgb(set.palette.base), light: rgb(set.palette.light), dark: rgb(set.palette.dark), accent: rgb(set.palette.accent ?? set.palette.light) };
  const hum = img(64, 32), leg = img(64, 32);
  // helmet: the head box, the face opening left clear on the front (rows 3..6, columns 1..6)
  for (const f of HEAD) paintFace(hum, f, p, set.style, undefined, f.side === "front" ? (x, y) => y >= 3 && y <= 6 && x >= 1 && x <= 6 : undefined);
  // chestplate: body + arms
  for (const f of BODY) paintFace(hum, f, p, set.style);
  for (const f of ARM) paintFace(hum, f, p, set.style, f.side === "top" || f.side === "bottom" ? undefined : [0, 9]);
  // boots: the lower 4 rows of the legs (+ soles)
  for (const f of LEG) paintFace(hum, f, p, set.style, f.side === "top" ? undefined : f.side === "bottom" ? undefined : [8, 11]);
  // leggings: the legs (upper 9 rows) + the lower 4 rows of the body (the belt)
  for (const f of LEG) paintFace(leg, f, p, set.style, f.side === "top" || f.side === "bottom" ? undefined : [0, 8]);
  for (const f of BODY) if (f.side !== "top" && f.side !== "bottom") paintFace(leg, f, p, set.style, [8, 11]);
  return { humanoid: hum, leggings: leg };
}

const ICON: Record<ArmorPiece, string[]> = {
  helmet: ["................", "................", "....oooooooo....", "...o########o...", "..o##++++++##o..", "..o#+######-#o..", "..o#--------#o..", "..o##o....o##o..", "..o##o....o##o..", "...oo......oo...", "................", "................", "................", "................", "................", "................"],
  chestplate: ["................", "..ooo......ooo..", ".o###o....o###o.", ".o#+##oooo##+#o.", ".o#++######++#o.", "..o#+######-#o..", "...o#++++++-o...", "...o########o...", "...o#------#o...", "...o########o...", "...o#------#o...", "...o########o...", "....oooooooo....", "................", "................", "................"],
  leggings: ["................", "...oooooooooo...", "...o########o...", "...o#++++++#o...", "...o###oo###o...", "...o##o..o##o...", "...o##o..o##o...", "...o#+o..o+#o...", "...o##o..o##o...", "...o##o..o##o...", "...o#-o..o-#o...", "...oooo..oooo...", "................", "................", "................", "................"],
  boots: ["................", "................", "................", "................", "................", "................", "...oooo..oooo...", "...o##o..o##o...", "...o#+o..o+#o...", "...o##o..o##o...", "..o###o..o###o..", ".o####o..o####o.", ".o#---o..o---#o.", ".ooooo....ooooo.", "................", "................"],
};
export function armorIcon(set: ArmorSet, piece: ArmorPiece): Img {
  const p: Pal = { base: rgb(set.palette.base), light: rgb(set.palette.light), dark: rgb(set.palette.dark), accent: rgb(set.palette.accent ?? set.palette.light) };
  const m = img(16, 16);
  ICON[piece].forEach((row, y) => [...row].forEach((ch, x) => {
    const c = ch === "#" ? p.base : ch === "+" ? p.light : ch === "-" ? mix(p.base, p.dark, 0.5) : ch === "o" ? mix(p.dark, [0, 0, 0], 0.35) : null;
    if (c) put(m, x, y, c as [number, number, number]);
  }));
  return m;
}

export type ArmorFile = { path: string; text?: string; data?: Buffer };
/** Resource pack files (1.21.4+ layout): equipment assets, worn layer textures, item definitions, item models, icons. */
export function armorPackFiles(spec: ArmorSpec, ns: string): ArmorFile[] {
  const out: ArmorFile[] = [];
  for (const s of spec.sets) {
    const { humanoid, leggings } = armorLayers(s);
    out.push({ path: `assets/${ns}/equipment/${s.id}.json`, text: JSON.stringify({ layers: { humanoid: [{ texture: `${ns}:${s.id}` }], humanoid_leggings: [{ texture: `${ns}:${s.id}` }] } }, null, 1) + "\n" });
    out.push({ path: `assets/${ns}/textures/entity/equipment/humanoid/${s.id}.png`, data: encodePngWH(humanoid) });
    out.push({ path: `assets/${ns}/textures/entity/equipment/humanoid_leggings/${s.id}.png`, data: encodePngWH(leggings) });
    for (const piece of ARMOR_PIECES) {
      const id = `${s.id}_${piece}`;
      out.push({ path: `assets/${ns}/textures/item/${id}.png`, data: encodePngWH(armorIcon(s, piece)) });
      out.push({ path: `assets/${ns}/models/item/${id}.json`, text: JSON.stringify({ parent: "minecraft:item/generated", textures: { layer0: `${ns}:item/${id}` } }, null, 1) + "\n" });
      out.push({ path: `assets/${ns}/items/${id}.json`, text: JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${id}` } }, null, 1) + "\n" });
    }
  }
  return out.sort((a, b) => (a.path < b.path ? -1 : 1));
}

const js = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/[^\x20-\x7e]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`)}"`;
const SLOT: Record<ArmorPiece, string> = { helmet: "HEAD", chestplate: "CHEST", leggings: "LEGS", boots: "FEET" };
const LEATHER: Record<ArmorPiece, string> = { helmet: "LEATHER_HELMET", chestplate: "LEATHER_CHESTPLATE", leggings: "LEATHER_LEGGINGS", boots: "LEATHER_BOOTS" };

/**
 * The plugin support class. modern (1.21.4+): any carrier + setEquippable(slot, model) + setItemModel; legacy (1.21.1):
 * dyed leather in the base colour (no worn custom look: there is no equippable component). Armor points and toughness are
 * keyed attribute modifiers (prefix-free names looked up in the registry, generic.* on 1.21.1).
 */
export function armorJava(spec: ArmorSpec, ns: string, pkg: string, opts: { modern: boolean }): string {
  const sets = spec.sets.map((s) => `        sets.put(${js(s.id)}, new Set(${js(s.id)}, ${js(s.displayName)}, 0x${s.palette.base.slice(1)}, new double[] {${ARMOR_PIECES.map((p) => s.armor[p]).join(", ")}}, ${s.toughness}, ${s.setBonus ? js(s.setBonus.effect) : "null"}, ${s.setBonus?.amplifier ?? 0}));`).join("\n");
  return `package ${pkg};

import com.destroystokyo.paper.event.player.PlayerArmorChangeEvent;
import java.util.LinkedHashMap;
import java.util.Map;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Color;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.Registry;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeModifier;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.inventory.EquipmentSlot;
import org.bukkit.inventory.EquipmentSlotGroup;
import org.bukkit.inventory.ItemStack;${opts.modern ? `
import org.bukkit.inventory.meta.components.EquippableComponent;` : `
import org.bukkit.inventory.meta.LeatherArmorMeta;`}
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

/** GENERATED by Cyrus (lib/cyrus/equipment/armor.ts) for ${ns}: custom armor sets (${opts.modern ? "equippable worn looks, 1.21.4+" : "dyed leather, 1.21.1"}). */
public final class ArmorSets implements Listener {
    public record Set(String id, String name, int color, double[] armor, double toughness, String bonusEffect, int bonusAmplifier) {}
    public static final String[] PIECES = {"helmet", "chestplate", "leggings", "boots"};
    private static final EquipmentSlot[] SLOTS = {EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET};
    private static final EquipmentSlotGroup[] GROUPS = {EquipmentSlotGroup.HEAD, EquipmentSlotGroup.CHEST, EquipmentSlotGroup.LEGS, EquipmentSlotGroup.FEET};
    private static final Material[] CARRIERS = {Material.${LEATHER.helmet}, Material.${LEATHER.chestplate}, Material.${LEATHER.leggings}, Material.${LEATHER.boots}};
    private final Map<String, Set> sets = new LinkedHashMap<>();
    private final JavaPlugin plugin;
    private final NamespacedKey tag;

    public ArmorSets(JavaPlugin plugin) {
        this.plugin = plugin;
        this.tag = new NamespacedKey(plugin, "armor_set");
${sets}
    }

    public java.util.Set<String> ids() { return sets.keySet(); }

    static Attribute attribute(String key) {
        Attribute a = Registry.ATTRIBUTE.get(NamespacedKey.minecraft(key));
        return a != null ? a : Registry.ATTRIBUTE.get(NamespacedKey.minecraft("generic." + key));
    }

    public ItemStack item(String id, int piece) {
        Set s = sets.get(id);
        if (s == null || piece < 0 || piece > 3) return null;
        ItemStack it = new ItemStack(CARRIERS[piece]);
        it.editMeta(m -> {
            m.displayName(Component.text(s.name() + " " + Character.toUpperCase(PIECES[piece].charAt(0)) + PIECES[piece].substring(1)).decoration(TextDecoration.ITALIC, false));
            m.getPersistentDataContainer().set(tag, PersistentDataType.STRING, s.id());
            Attribute armor = attribute("armor"), tough = attribute("armor_toughness");
            if (armor != null) m.addAttributeModifier(armor, new AttributeModifier(new NamespacedKey(plugin, s.id() + "_" + PIECES[piece] + "_armor"), s.armor()[piece], AttributeModifier.Operation.ADD_NUMBER, GROUPS[piece]));
            if (tough != null && s.toughness() > 0) m.addAttributeModifier(tough, new AttributeModifier(new NamespacedKey(plugin, s.id() + "_" + PIECES[piece] + "_toughness"), s.toughness(), AttributeModifier.Operation.ADD_NUMBER, GROUPS[piece]));${opts.modern ? `
            EquippableComponent eq = m.getEquippable();
            eq.setSlot(SLOTS[piece]);
            eq.setModel(new NamespacedKey(${js(ns)}, s.id()));
            m.setEquippable(eq);
            m.setItemModel(new NamespacedKey(${js(ns)}, s.id() + "_" + PIECES[piece]));` : `
            if (m instanceof LeatherArmorMeta lm) lm.setColor(Color.fromRGB(s.color()));`}
        });
        return it;
    }

    /** "<model> <slot>" of an item this class made (for self-checks), or null. */
    public String describe(ItemStack it) {
        if (it == null || !it.hasItemMeta() || !it.getItemMeta().getPersistentDataContainer().has(tag, PersistentDataType.STRING)) return null;${opts.modern ? `
        EquippableComponent eq = it.getItemMeta().getEquippable();
        return eq.getModel() + " " + eq.getSlot();` : `
        return "leather " + ((LeatherArmorMeta) it.getItemMeta()).getColor().asRGB();`}
    }

    private boolean wearsSet(Player p, String id) {
        for (ItemStack it : p.getInventory().getArmorContents()) {
            if (it == null || !it.hasItemMeta() || !id.equals(it.getItemMeta().getPersistentDataContainer().get(tag, PersistentDataType.STRING))) return false;
        }
        return true;
    }

    @EventHandler
    public void onArmor(PlayerArmorChangeEvent e) {
        plugin.getServer().getScheduler().runTask(plugin, () -> {
            Player p = e.getPlayer();
            for (Set s : sets.values()) {
                if (s.bonusEffect() == null) continue;
                PotionEffectType type = Registry.EFFECT.get(NamespacedKey.minecraft(s.bonusEffect()));
                if (type == null) continue;
                PotionEffect cur = p.getPotionEffect(type);
                if (wearsSet(p, s.id())) p.addPotionEffect(new PotionEffect(type, PotionEffect.INFINITE_DURATION, s.bonusAmplifier(), true, false, true));
                else if (cur != null && cur.isInfinite()) p.removePotionEffect(type);
            }
        });
    }
}
`;
}

export const ARMOR_LIMITS_TEXT = [
  "Worn custom armor looks need Minecraft 1.21.4+ (the equippable component) and players accepting the resource pack; on 1.21.1 Cyrus makes dyed leather armor with the set's colour and stats.",
  "Armor points, toughness and set bonuses come from the plugin (attribute modifiers, effects); the armor trim and enchantment glint rules of the carrier item still apply.",
];

