#!/usr/bin/env tsx
// Bundle mc-coverage: writes the golden custom-armor plugin (services/modbuilder/golden/plugins/mc-armor) from
// lib/cyrus/equipment/armor.ts: the generated ArmorSets support class (equippable worn looks on 1.21.4+, src@1.21.1 =
// dyed leather) so the golden harness compiles it on every buildable version and the golden flight checks the items.
// Also writes the pack files to .cyrus-local/golden/armor-pack/ for review.  npx tsx scripts/cyrus/golden-armor.ts [--check]
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { armorJava, armorPackFiles, checkArmorSpec } from "../../lib/cyrus/equipment/armor";

const ROOT = path.resolve(__dirname, "../..");
const DIR = path.join(ROOT, "services/modbuilder/golden/plugins/mc-armor");
export const ARMOR_NS = "nx_mc1arm01";
export const ARMOR_SPEC = { version: 1, sets: [
  { id: "ember", displayName: "Ember", palette: { base: "#c2461e", light: "#f2a03c", dark: "#4a1608", accent: "#ffe28a" }, style: "plate", armor: { helmet: 3, chestplate: 7, leggings: 6, boots: 3 }, toughness: 1, setBonus: { effect: "fire_resistance", amplifier: 0 } },
  { id: "tidal", displayName: "Tidal", palette: { base: "#2a7fa8", light: "#7fd6f0", dark: "#0c2a3f" }, style: "scale", armor: { helmet: 2, chestplate: 6, leggings: 5, boots: 2 } },
] };

const MAIN = `package dev.nxeon.golden.armor;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden custom armor: /customarmor list | check <set> | give <set> [player]. */
public class Armor extends JavaPlugin {
    private ArmorSets sets;

    @Override
    public void onEnable() {
        sets = new ArmorSets(this);
        getServer().getPluginManager().registerEvents(sets, this);
        getCommand("customarmor").setExecutor(this);
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0] : "list";
        if (sub.equals("check") && args.length == 2) {
            StringBuilder sb = new StringBuilder("Armor " + args[1] + ":");
            for (int i = 0; i < 4; i++) { ItemStack it = sets.item(args[1], i); sb.append(" ").append(ArmorSets.PIECES[i]).append("=").append(it == null ? "missing" : sets.describe(it)); }
            sender.sendMessage(Component.text(sb.toString(), NamedTextColor.AQUA));
            return true;
        }
        if (sub.equals("give") && args.length >= 2) {
            Player p = args.length > 2 ? Bukkit.getPlayerExact(args[2]) : sender instanceof Player s ? s : null;
            if (p == null) { sender.sendMessage(Component.text("Players only.", NamedTextColor.RED)); return true; }
            for (int i = 0; i < 4; i++) { ItemStack it = sets.item(args[1], i); if (it != null) p.getInventory().addItem(it); }
            return true;
        }
        sender.sendMessage(Component.text("Armor sets: " + String.join(", ", sets.ids()), NamedTextColor.AQUA));
        return true;
    }
}
`;

export function goldenFiles(): Record<string, string> {
  const chk = checkArmorSpec(ARMOR_SPEC, { namespace: ARMOR_NS });
  if (!chk.ok) throw new Error(chk.errors.join("; "));
  const pkg = "dev.nxeon.golden.armor";
  const yml = `name: GoldenArmor\nversion: 1.0.0\nmain: dev.nxeon.golden.armor.Armor\napi-version: '@API@'\ndescription: Golden reference - custom armor sets (generated support class)\nauthor: Nxeon Mod Builder\ncommands:\n  customarmor:\n    description: Custom armor tools\n    usage: /customarmor <list|check|give>\n    permission: goldenarmor.admin\npermissions:\n  goldenarmor.admin:\n    description: Use /customarmor\n    default: op\n`;
  const golden = {
    archetype: "armor_sets",
    notes: "GENERATED by scripts/cyrus/golden-armor.ts from lib/cyrus/equipment/armor.ts; do not edit. The 1.21.4+ check expects the equippable model; 1.21.1 (src@1.21.1) expects dyed leather.",
    rcon: [
      { command: "customarmor list", expect: ["Armor sets: ember, tidal"] },
      { command: "customarmor check ember", expect: ["helmet=", "boots="], expectNot: ["missing"] },
    ],
  };
  return {
    "plugin.yml": yml,
    "golden.json": JSON.stringify(golden, null, 1) + "\n",
    "src/dev/nxeon/golden/armor/Armor.java": MAIN,
