// Bundle mc-coverage lane gaps (pure): custom blocks on reserved note_block states (lib/cyrus/blocks/noteblock.ts) and
// custom armor with worn looks (lib/cyrus/equipment/armor.ts); the golden plugins generated from them are fresh; the
// GameRules autofix; precheck `unless`; the coverage-driven failure rules on the anti-pattern corpus sources.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { checkNoteBlockSpec, homeInstrument, noteBlockJava, noteBlockPackFiles, stateFor, NOTEBLOCK_INSTRUMENTS_121, NOTEBLOCK_INSTRUMENTS_262, RESERVED_INSTRUMENTS } from "../lib/cyrus/blocks/noteblock";
import { armorIcon, armorLayers, armorPackFiles, checkArmorSpec, encodePngWH } from "../lib/cyrus/equipment/armor";
import { goldenFiles as noteblockGolden, NB_NS, NB_SPEC } from "../scripts/cyrus/golden-noteblock";
import { goldenFiles as armorGolden, ARMOR_NS, ARMOR_SPEC } from "../scripts/cyrus/golden-armor";

const ROOT = path.join(__dirname, "..");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const AF = require(path.join(ROOT, "services/modbuilder/autofix.js"));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PC = require(path.join(ROOT, "services/modbuilder/precheck.js"));

describe("custom blocks (note_block state carrier)", () => {
  it("allocates deterministic reserved states (mob-head instruments only, 50 per mod)", () => {
    assert.ok(RESERVED_INSTRUMENTS.includes(homeInstrument("nx_aaaa1111")));
    assert.equal(homeInstrument("nx_aaaa1111"), homeInstrument("nx_aaaa1111"));
    assert.deepEqual(stateFor("nx_x1234567", 0).note, 0);
    assert.deepEqual([stateFor("nx_x1234567", 24).note, stateFor("nx_x1234567", 24).powered, stateFor("nx_x1234567", 25).note, stateFor("nx_x1234567", 25).powered], [24, false, 0, true]);
    const r = checkNoteBlockSpec(NB_SPEC, { namespace: NB_NS });
    assert.ok(r.ok);
    if (r.ok) assert.ok(r.warnings.some((w) => /disable-noteblock-updates/.test(w)));
    assert.equal(checkNoteBlockSpec({ version: 1, blocks: [] }, { namespace: NB_NS }).ok, false);
    assert.equal(checkNoteBlockSpec(NB_SPEC, { namespace: NB_NS, textures: ["ruby_block"] }).ok, false, "unknown textures are refused");
  });
  it("the blockstate covers every state of the version and keeps vanilla for the unused ones", () => {
    const r = checkNoteBlockSpec(NB_SPEC, { namespace: NB_NS });
    assert.ok(r.ok);
    if (!r.ok) return;
    for (const [ins, n] of [[NOTEBLOCK_INSTRUMENTS_121, 1150], [NOTEBLOCK_INSTRUMENTS_262, 1350]] as const) {
      const files = noteBlockPackFiles(r.blocks, NB_NS, { instruments: ins, itemModels: true });
      const bs = JSON.parse(files.find((f) => f.path === "assets/minecraft/blockstates/note_block.json")!.text);
      const keys = Object.keys(bs.variants);
      assert.equal(keys.length, n);
      const custom = keys.filter((k) => bs.variants[k].model !== "minecraft:block/note_block");
      assert.equal(custom.length, 3);
      assert.ok(custom.every((k) => RESERVED_INSTRUMENTS.some((i) => k.startsWith(`instrument=${i},`))));
    }
    const legacy = noteBlockPackFiles(r.blocks, NB_NS, { instruments: NOTEBLOCK_INSTRUMENTS_121, itemModels: false });
    assert.ok(!legacy.some((f) => f.path.includes("/items/")), "1.21.1: no item model definitions");
    const java = noteBlockJava(r.blocks, NB_NS, "dev.x", { itemModels: true });
    assert.match(java, /Instrument\.[A-Z_]+, 0, false/);
    assert.match(java, /NotePlayEvent/);
    assert.match(java, /setItemModel/);
    assert.doesNotMatch(noteBlockJava(r.blocks, NB_NS, "dev.x", { itemModels: false }), /setItemModel/);
  });
  it("the golden plugin is generated from the module (fresh)", () => {
    for (const [rel, text] of Object.entries(noteblockGolden())) assert.equal(fs.readFileSync(path.join(ROOT, "services/modbuilder/golden/plugins/mc-noteblocks", rel), "utf8"), text, `${rel}: npx tsx scripts/cyrus/golden-noteblock.ts`);
  });
});

describe("custom armor (equippable worn looks)", () => {
  it("validates and draws the 64x32 humanoid layers and 16x16 icons", () => {
    const r = checkArmorSpec(ARMOR_SPEC, { namespace: ARMOR_NS });
    assert.ok(r.ok);
    if (!r.ok) return;
    const { humanoid, leggings } = armorLayers(r.spec.sets[0]);
    assert.deepEqual([humanoid.w, humanoid.h, leggings.w, leggings.h], [64, 32, 64, 32]);
    const alpha = (m: { w: number; px: Uint8ClampedArray }, x: number, y: number) => m.px[(y * m.w + x) * 4 + 3];
    assert.equal(alpha(humanoid, 9, 8), 255, "helmet front frame");
    assert.equal(alpha(humanoid, 10, 12), 0, "helmet face opening");
    assert.equal(alpha(humanoid, 21, 24), 255, "chestplate front");
    assert.equal(alpha(leggings, 5, 22), 255, "leggings");
    assert.equal(alpha(leggings, 9, 8), 0, "no helmet on the leggings layer");
    const png = encodePngWH(armorIcon(r.spec.sets[0], "helmet"));
    assert.equal(png.readUInt32BE(16), 16);
    const files = armorPackFiles(r.spec, ARMOR_NS);
    const eq = JSON.parse(files.find((f) => f.path === `assets/${ARMOR_NS}/equipment/ember.json`)!.text!);
    assert.deepEqual(eq, { layers: { humanoid: [{ texture: `${ARMOR_NS}:ember` }], humanoid_leggings: [{ texture: `${ARMOR_NS}:ember` }] } });
    assert.ok(files.some((f) => f.path === `assets/${ARMOR_NS}/textures/entity/equipment/humanoid_leggings/tidal.png`));
    assert.equal(files.filter((f) => f.path.includes("/items/")).length, 8);
    assert.equal(checkArmorSpec({ version: 1, sets: [ARMOR_SPEC.sets[0], ARMOR_SPEC.sets[0]] }, { namespace: ARMOR_NS }).ok, false);
  });
  it("the golden plugin is generated from the module (fresh)", () => {
    for (const [rel, text] of Object.entries(armorGolden())) assert.equal(fs.readFileSync(path.join(ROOT, "services/modbuilder/golden/plugins/mc-armor", rel), "utf8"), text, `${rel}: npx tsx scripts/cyrus/golden-armor.ts`);
  });
});

describe("knowledge fixes from the golden corpus", () => {
  const ws = () => { const d = fs.mkdtempSync(path.join(os.tmpdir(), "mc1-")); fs.mkdirSync(path.join(d, "src/main/java/x"), { recursive: true }); return d; };
  it("autofix: GameRule.* -> GameRules.* on 1.21.11 (same name or same-meaning rename), never where GameRules is missing", () => {
    const d = ws(), rel = "src/main/java/x/A.java", abs = path.join(d, rel);
    fs.writeFileSync(abs, "package x;\nimport org.bukkit.GameRule;\nclass A { void f(org.bukkit.World w) { w.setGameRule(GameRule.KEEP_INVENTORY, true); w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE, false); w.setGameRule(GameRule.DISABLE_RAIDS, true); } }\n");
    const idx = new Map([["GameRules", ["org.bukkit.GameRules"]], ["GameRule", ["org.bukkit.GameRule"]]]);
    const deps = { classIndex: () => idx, members: () => ({ fields: ["KEEP_INVENTORY", "ADVANCE_TIME", "RAIDS"], methods: [] }) };
    const r = AF.fixGameRules([{ rel, abs }], "1.21.11", deps);
    const t = fs.readFileSync(abs, "utf8");
    assert.match(t, /GameRules\.KEEP_INVENTORY/);
    assert.match(t, /GameRules\.ADVANCE_TIME/);
    assert.match(t, /GameRule\.DISABLE_RAIDS/, "inverted rules are left to the model");
    assert.match(t, /import org\.bukkit\.GameRules;/);
    assert.ok(r.fixes.length >= 3);
    const d2 = ws(), abs2 = path.join(d2, rel);
    fs.writeFileSync(abs2, "package x;\nclass A { Object o = org.bukkit.GameRule.KEEP_INVENTORY; }\n");
    assert.equal(AF.fixGameRules([{ rel, abs: abs2 }], "1.21.8", { classIndex: () => new Map(), members: () => null }).fixes.length, 0);
  });
  it("precheck: the new rules fire on the anti-pattern corpus and `unless` spares a filtered PlayerMoveEvent handler", () => {
    const anti = path.join(ROOT, "services/modbuilder/golden/antipatterns");
    for (const id of fs.readdirSync(anti)) {
      const exp = JSON.parse(fs.readFileSync(path.join(anti, id, "expect.json"), "utf8"));
      if (exp.expect.layer !== "precheck") continue;
      const dir = path.join(anti, id, "src");
      const files: { rel: string; abs: string }[] = [];
      const walk = (p: string) => { for (const e of fs.readdirSync(p, { withFileTypes: true })) { const a = path.join(p, e.name); if (e.isDirectory()) walk(a); else files.push({ rel: path.relative(dir, a), abs: a }); } };
      walk(dir);
      for (const v of exp.versions ?? ["1.21.1", "1.21.11"]) assert.ok(PC.precheck(files, v).some((h: { rule: string }) => h.rule === exp.expect.rule), `${id} ${v}: ${exp.expect.rule}`);
    }
    const d = ws(), rel = "src/main/java/x/M.java", abs = path.join(d, rel);
    fs.writeFileSync(abs, "package x;\nclass M { @org.bukkit.event.EventHandler public void onMove(org.bukkit.event.player.PlayerMoveEvent e) { if (!e.hasChangedBlock()) return; } }\n");
    assert.ok(!PC.precheck([{ rel, abs }], "1.21.11").some((h: { rule: string }) => h.rule === "playermove-unfiltered"));
  });
  it("the golden corpus never uses a pattern the failure rules forbid", () => {
    const base = path.join(ROOT, "services/modbuilder/golden/plugins");
    for (const id of fs.readdirSync(base)) {
      const files: { rel: string; abs: string }[] = [];
      const walk = (p: string) => { if (!fs.existsSync(p)) return; for (const e of fs.readdirSync(p, { withFileTypes: true })) { const a = path.join(p, e.name); if (e.isDirectory()) walk(a); else if (e.name.endsWith(".java")) files.push({ rel: path.relative(base, a), abs: a }); } };
      walk(path.join(base, id, "src"));
      for (const v of ["1.21.4", "1.21.8", "1.21.11"]) assert.deepEqual(PC.precheck(files, v).map((h: { rule: string; where: string }) => `${h.rule} ${h.where}`), [], `${id} ${v}`);
    }
  });
});

