describe("knowledge fixes from the golden corpus", () => {
  const ws = () => { const d = fs.mkdtempSync(path.join(os.tmpdir(), "mc1-")); fs.mkdirSync(path.join(d, "src/main/java/x"), { recursive: true }); return d; };
  it("autofix: GameRule.* -> GameRules.* on 1.21.11 (same name or same-meaning rename), never where GameRules is missing", () => {
    const d = ws(), rel = "src/main/java/x/A.java", abs = path.join(d, rel);
    fs.writeFileSync(abs, "package x;\nimport org.bukkit.GameRule;\nclass A { void f(org.bukkit.World w) { w.setGameRule(GameRule.KEEP_INVENTORY, true); w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE, false); w.setGameRule(GameRule.DISABLE_RAIDS, true); } }\n");
    const idx = new Map([["GameRules", ["org.bukkit.GameRules"]], ["GameRule", ["org.bukkit.GameRule"]]]);
    const deps = { classIndex: () => idx, members: () => ({ fields: ["KEEP_INVENTORY", "ADVANCE_TIME", "RAIDS"], methods: [] }) };
    const r = AF.fixGameRules([{ rel, abs }], "1.21.11", deps);
    const t = fs.readFileSync(abs, "utf8");
    assert.match(t, /GameRules\.KEEP_INVENTORY/);
    assert.match(t, /GameRules\.ADVANCE_TIME/);
    assert.match(t, /GameRule\.DISABLE_RAIDS/, "inverted rules are left to the model");
    assert.match(t, /import org\.bukkit\.GameRules;/);
    assert.ok(r.fixes.length >= 3);
    const d2 = ws(), abs2 = path.join(d2, rel);
    fs.writeFileSync(abs2, "package x;\nclass A { Object o = org.bukkit.GameRule.KEEP_INVENTORY; }\n");
    assert.equal(AF.fixGameRules([{ rel, abs: abs2 }], "1.21.8", { classIndex: () => new Map(), members: () => null }).fixes.length, 0);
  });
  it("precheck: the new rules fire on the anti-pattern corpus and `unless` spares a filtered PlayerMoveEvent handler", () => {
    const anti = path.join(ROOT, "services/modbuilder/golden/antipatterns");
    for (const id of fs.readdirSync(anti)) {
      const exp = JSON.parse(fs.readFileSync(path.join(anti, id, "expect.json"), "utf8"));
      if (exp.expect.layer !== "precheck") continue;
      const dir = path.join(anti, id, "src");
      const files: { rel: string; abs: string }[] = [];
      const walk = (p: string) => { for (const e of fs.readdirSync(p, { withFileTypes: true })) { const a = path.join(p, e.name); if (e.isDirectory()) walk(a); else files.push({ rel: path.relative(dir, a), abs: a }); } };
      walk(dir);
      for (const v of exp.versions ?? ["1.21.1", "1.21.11"]) assert.ok(PC.precheck(files, v).some((h: { rule: string }) => h.rule === exp.expect.rule), `${id} ${v}: ${exp.expect.rule}`);
    }
    const d = ws(), rel = "src/main/java/x/M.java", abs = path.join(d, rel);
    fs.writeFileSync(abs, "package x;\nclass M { @org.bukkit.event.EventHandler public void onMove(org.bukkit.event.player.PlayerMoveEvent e) { if (!e.hasChangedBlock()) return; } }\n");
    assert.ok(!PC.precheck([{ rel, abs }], "1.21.11").some((h: { rule: string }) => h.rule === "playermove-unfiltered"));
  });
  it("the golden corpus never uses a pattern the failure rules forbid", () => {
    const base = path.join(ROOT, "services/modbuilder/golden/plugins");
    for (const id of fs.readdirSync(base)) {
      const files: { rel: string; abs: string }[] = [];
      const walk = (p: string) => { if (!fs.existsSync(p)) return; for (const e of fs.readdirSync(p, { withFileTypes: true })) { const a = path.join(p, e.name); if (e.isDirectory()) walk(a); else if (e.name.endsWith(".java")) files.push({ rel: path.relative(base, a), abs: a }); } };
      walk(path.join(base, id, "src"));
      for (const v of ["1.21.4", "1.21.8", "1.21.11"]) assert.deepEqual(PC.precheck(files, v).map((h: { rule: string; where: string }) => `${h.rule} ${h.where}`), [], `${id} ${v}`);
    }
  });
});

